local config = {
  ui_story_5070_50700101_1_dialog_content = "Ahh! This is really bad...",
  ui_story_5070_50700101_2_dialog_content = "We're almost down to the last of our reserve funds.",
  ui_story_5070_50700101_3_dialog_content = "I've been too busy to take on jobs lately, and Soroz just had maintenance done...",
  ui_story_5070_50700101_4_dialog_content = "Somehow, we burned through almost all of our money.",
  ui_story_5070_50700101_5_dialog_content = "If Vice finds out, she's gonna put me on ration crackers and short-dated instant coffee for every meal again—",
  ui_story_5070_50700101_6_dialog_content = "Oh? What do we have here?",
  ui_story_5070_50700101_7_dialog_content = "Vice! I-It's nothing, it's just...",
  ui_story_5070_50700101_8_dialog_content = "It's just that we're on the verge of bankruptcy, so we have to reactivate our wartime rationing protocols. Is that it?",
  ui_story_5070_50700101_9_dialog_content = "... So you already knew.",
  ui_story_5070_50700101_10_dialog_content = "It'd be even weirder if I didn't...",
  ui_story_5070_50700101_11_dialog_content = "Honestly, you need to do a better job of keeping track of the Colossus' expenses. I can't be up here to help all the time, you know.",
  ui_story_5070_50700101_12_dialog_content = "Still, it looks like fate is on our side. Take a look at this!",
  ui_story_5070_50700101_13_dialog_content = "A Courier just brought us an urgent message from the Lin Guild—",
  ui_story_5070_50700101_14_dialog_content = "\"Dear PlayerName, the following matter concerns the very future of our guild. As such, it is our sincerest wish...\"",
  ui_story_5070_50700101_15_dialog_content = "\"...that as the Navigator of the Colossus and a master of the psychic arts, please lend us your aid.\"",
  ui_story_5070_50700101_16_dialog_content = "The Lin Guild has helped us out plenty of times before, but now they need our help! They're offering a huge reward too!",
  ui_story_5070_50700101_17_dialog_content = "A chance to improve our standing with the Lin Family AND make a ton of money?",
  ui_story_5070_50700101_18_dialog_content = "Sounds great! I'll chart a course for Umbraton right away!",
  ui_story_5070_50700101_19_dialog_content = "Hang on, the job isn't in Umbraton this time.",
  ui_story_5070_50700101_20_dialog_content = "It's in Twin Pavilions Bay.",
  ui_story_5070_50700101_21_dialog_content = "But if the job concerns the entire future of the Lin Guild, why wouldn't we go to their headquarters first?",
  ui_story_5070_50700101_22_dialog_content = "Because according to them, Twin Pavilions Bay is just as important as Umbraton... if not more so.",
  ui_story_5070_50700101_23_dialog_content = "Carleen?! I thought you were still reading in your room!",
  ui_story_5070_50700101_24_dialog_content = "I still have enough time off to accompany you this time... Besides, I'm the only one here who knows Twin Pavilions Bay.",
  ui_story_5070_50700101_25_dialog_content = "For Lumopolis, trade between Twin Pavilions Bay and Umbraton is vital for the economy.",
  ui_story_5070_50700101_26_dialog_content = "The faraway land of Longzhou brings all kinds of goods to our shores...",
  ui_story_5070_50700101_27_dialog_content = "Including plenty of valuable products and skills that we have no way of reproducing here in Astra.",
  ui_story_5070_50700101_28_dialog_content = "The Lin Guild is also from Longzhou.",
  ui_story_5070_50700101_29_dialog_content = "After braving the vast ocean to get here, the place where they first made landfall was none other than Twin Pavilions Bay.",
  ui_story_5070_50700101_30_dialog_content = "To this day, it serves as Astra's only accessible harbor for Longzhou's merchant ships. In a way, it's the foundation of the Lin Family's commercial operations.",
  ui_story_5070_50700101_31_dialog_content = "Considering how urgent this invitation sounds, I don't think they're exaggerating when they say <color=#FFB400>the future of the Lin Guild</color> is at stake.",
  ui_story_5070_50700101_32_dialog_content = "Then we should go there as soon as possible.",
  ui_story_5070_50700101_33_dialog_content = "But where exactly is this Twin Pavilions Bay?",
  ui_story_5070_50700101_34_dialog_content = "Allow me to show you the way.",
  ui_story_5070_50700101_35_dialog_content = "We can reach there quickly by following the Gold River all the way to its source.",
  ui_story_5070_50700101_36_dialog_content = "Incredible! Twin Pavilions Bay looks nothing like any other place in Astra!",
  ui_story_5070_50700101_37_dialog_content = "It's like someone took a place from a totally different world and dropped it right here.",
  ui_story_5070_50700101_38_dialog_content = "I've only ever read about it in books as well.",
  ui_story_5070_50700101_39_dialog_content = "The Lin Family spearheaded the development of this area with the people who first traveled along the ocean route they established.",
  ui_story_5070_50700101_40_dialog_content = "As a result, more and more visitors from Longzhou began to arrive here.",
  ui_story_5070_50700101_41_dialog_content = "This, in turn, led to the establishment of such a Longzhou-style city on the shores of Astra.",
  ui_story_5070_50700101_42_dialog_content = "... It's even more wonderful in person than its descriptions in our books.",
  ui_story_5070_50700101_43_dialog_content = "Steamed buns, fresh off the stove! Piping hot and full of savory meat! Would you care for some steamed buns, my friends?",
  ui_story_5070_50700101_44_dialog_content = "Freshly-arrived travelers, I take it? Then you must try our tea!",
  ui_story_5070_50700101_45_dialog_content = "Pre-Rain Longjing, Yunmeng Silver Bud, Infinite Large-Leaf, and even Danshan Oolong: we carry every kind of famous tea, straight from the fields of Longzhou!",
  ui_story_5070_50700101_46_dialog_content = "It smells amazing here!",
  ui_story_5070_50700101_47_dialog_content = "So many things I've never seen before! When we finish our job, we definitely have to come back for some shopping.",
  ui_story_5070_50700101_48_dialog_content = "Speaking of the job, did the letter say anything about where to find the guild?",
  ui_story_5070_50700101_49_dialog_content = "<color=#e8d9bb>Suddenly, a gust of wind blows past.</color>",
  ui_story_5070_50700101_50_dialog_content = "My letter—!!!",
  ui_story_5070_50700101_51_dialog_content = "H-Huh? Did that golden dragonfly grab my letter?",
  ui_story_5070_50700101_52_dialog_content = "Wait, this isn't a normal dragonfly... is this thing made of metal?",
  ui_story_5070_50700101_53_dialog_content = "I'd hold onto things more carefully if I were you.",
  ui_story_5070_50700101_54_dialog_content = "Oh, uh... Thanks.",
  ui_story_5070_50700101_55_dialog_content = "Don't mention it!",
  ui_story_5070_50700101_56_dialog_content = "... Was that another Longzhou specialty?",
  ui_story_5070_50700101_57_dialog_content = "There you are! Pardon me, but are you PlayerName?",
  ui_story_5070_50700101_58_dialog_content = "Yes, that's me. I came to help the Lins!",
  ui_story_5070_50700101_59_dialog_content = "I'm a representative from the Lin Guild. We're very grateful for your assistance. Now if you don't mind, I'll go ahead and discuss the details with you.",
  ui_story_5070_50700101_60_dialog_content = "I'm sure you're all somewhat familiar with the Lin Guild, yes?",
  ui_story_5070_50700101_61_dialog_content = "We specialize in the transportation and distribution of goods and technology from Longzhou that aren't normally found in Astra.",
  ui_story_5070_50700101_62_dialog_content = "However, the vast ocean dividing our two continents is fraught with danger.",
  ui_story_5070_50700101_63_dialog_content = "As it stands, only the Lin Family's vessels can make seasonal voyages along routes the ancestors established.",
  ui_story_5070_50700101_64_dialog_content = "But the Shadowind, one of our most important merchant vessels, hasn't been seen in over half a year for reasons still unknown.",
  ui_story_5070_50700101_65_dialog_content = "No contact for over half a year? Could something have happened back in Longzhou?",
  ui_story_5070_50700101_66_dialog_content = "We... have no way of knowing that either.",
  ui_story_5070_50700101_67_dialog_content = "Currently, the only way for information to travel between our two lands is through the Lin Family's merchant ships.",
  ui_story_5070_50700101_68_dialog_content = "Even the Lin Guild itself has no other way of communicating with their people in Longzhou.",
  ui_story_5070_50700101_69_dialog_content = "Unfortunately, Miss Carleen is right.",
  ui_story_5070_50700101_70_dialog_content = "Neither Astra nor Longzhou have developed a communication device capable of spanning the vast ocean between them.",
  ui_story_5070_50700101_71_dialog_content = "Two days ago, however, we received a signal from out on the water–one that is used internally by the Lin Family.",
  ui_story_5070_50700101_72_dialog_content = "We believe it came from one of the merchant ships arriving this season!",
  ui_story_5070_50700101_73_dialog_content = "But the signal suddenly disappeared before we could respond, and we haven't received anything like it ever since.",
  ui_story_5070_50700101_74_dialog_content = "I see. You want us to use the Colossus to search for the missing ship, right?",
  ui_story_5070_50700101_75_dialog_content = "Precisely! Given the circumstances, you're our best hope of finding it!",
  ui_story_5070_50700101_76_dialog_content = "Understood. We'll do everything we can.",
  ui_story_5070_50700101_77_dialog_content = "(For the next few days, we scoured the ocean from atop the Colossus for any sign of the merchant ship.)",
  ui_story_5070_50700101_78_dialog_content = "We've searched every inch of the sea surrounding the port, but we haven't seen so much as a piece of driftwood out here.",
  ui_story_5070_50700101_79_dialog_content = "At the very least, we can rule out the ship disappearing in the nearby waters. That's good news, right?",
  ui_story_5070_50700101_80_dialog_content = "Yes, but now it seems our only choice is to search even further out.",
  ui_story_5070_50700101_81_dialog_content = "Is that okay, PlayerName?",
  ui_story_5070_50700101_82_dialog_content = "To be honest, I'm not very confident about this...",
  ui_story_5070_50700101_83_dialog_content = "As it stands, Soroz isn't equipped to handle unexpected storms in the open sea.",
  ui_story_5070_50700101_84_dialog_content = "I don't have much experience out there either. The furthest I've gone from the mainland is Cloud Island.",
  ui_story_5070_50700101_85_dialog_content = "If the ship went missing even further than that, rescuing them would be even more difficult.",
  ui_story_5070_50700101_86_dialog_content = "...",
  ui_story_5070_50700101_87_dialog_content = "Huh? Why are you two just silently staring at me like that?",
  ui_story_5070_50700101_88_dialog_content = "Because it's you talking, and usually...",
  ui_story_5070_50700101_89_dialog_content = "even when there's no hope, you manage to come up with something, don't you?",
  ui_story_5070_50700101_90_dialog_content = "I think you guys are overestimating my resilience... But, you're right.",
  ui_story_5070_50700101_91_dialog_content = "We accepted the job, after all. The least we can do is try our best.",
  ui_story_5070_50700101_92_dialog_content = "I'll use my full power to scan as much of the sea around us as possible. Hopefully I manage to find something.",
  ui_story_5070_50700101_93_option_content = "Force Boost!",
  ui_story_5070_50700101_94_dialog_content = "In the direction of the wind... Yes! There's a large number of Aurorians in that direction over there!",
  ui_story_5070_50700101_95_dialog_content = "The bountiful ocean provides! Looks like we finally have a lead now!",
  ui_story_5070_50700101_96_dialog_content = "Wait, you two, look over there. The skies are darkening, but the sea behind us is as calm and still as a mirror.",
  ui_story_5070_50700101_97_dialog_content = "There's a storm approaching from up ahead!",
  ui_story_5070_50700101_98_dialog_content = "I see the ship! It's massive!",
  ui_story_5070_50700101_99_dialog_content = "It's a Lin Family merchant ship.",
  ui_story_5070_50700101_100_dialog_content = "We have to save them! But I don't know if the Colossus can–",
  ui_story_5070_50700101_101_dialog_content = "Wait, PlayerName.",
  ui_story_5070_50700101_102_dialog_content = "Take a closer look.",
  ui_story_5070_50700101_103_dialog_content = "The people on the ship... I can sense they're a little nervous, but they're not panicking at all.",
  ui_story_5070_50700101_104_dialog_content = "The passengers on the deck are moving with a clear purpose too. It's as if someone's directing their actions with a steady hand.",
  ui_story_5070_50700101_105_dialog_content = "C-Captain! There appears to be something flying overhead...",
  ui_story_5070_50700101_106_dialog_content = "Don't worry about that right now. Continue tightening the ship's stays, and keep the rudder stable.",
  ui_story_5070_50700101_107_dialog_content = "Keep your eyes on the water's surface.",
  ui_story_5070_50700101_108_dialog_content = "We're forcing our way through!",
  ui_story_5070_50700101_109_dialog_content = "Aye aye, captain!",
  ui_story_5070_50700101_110_dialog_content = "<color=#e8d9bb>The tides surge as colossal waves rise and crash with a deafening roar.</color>",
  ui_story_5070_50700101_111_dialog_content = "<color=#e8d9bb>But just as the pounding waves converge into a deadly whirlpool, the ship manages to break through to safety!</color>",
  ui_story_5070_50700101_112_dialog_content = "Thank goodness they made it out!",
  ui_story_5070_50700101_113_dialog_content = "Phew...",
  ui_story_5070_50700101_114_dialog_content = "That was way too close! I thought my heart was gonna give out!",
  ui_story_5070_50700101_115_dialog_content = "The captain of that ship must be one incredible person.",
  ui_story_5070_50700101_116_dialog_content = "The ship's hull is covered in damage. It must have weathered plenty of storms on its way here.",
  ui_story_5070_50700101_117_dialog_content = "I'm surprised it can still sail so smoothly.",
  ui_story_5070_50700101_118_dialog_content = "The rest of the voyage should be peaceful enough. I don't think they'll run into any more danger.",
  ui_story_5070_50700101_119_dialog_content = "Let's escort it the rest of the way back before finding a place to land.",
  ui_story_5070_50700101_120_dialog_content = "It's the Shadowind! It's finally back!",
  ui_story_5070_50700101_121_dialog_content = "It looks different than before!",
  ui_story_5070_50700101_122_dialog_content = "What do you know? That's because it's a completely different ship from the previous Shadowind.",
  ui_story_5070_50700101_123_dialog_content = "Years ago, there were rumors that Ye was developing a brand-new mechanical core for Ji's largest vessels...",
  ui_story_5070_50700101_124_dialog_content = "This must be one of those new-and-improved ships!",
  ui_story_5070_50700101_125_dialog_content = "Stronger, faster, and tougher than ever before! The newest iteration of the Shadowind is the only one of its kind!",
  ui_story_5070_50700101_126_dialog_content = "S-So many people.",
  ui_story_5070_50700101_127_dialog_content = "Whenever a ship comes to port, the people of this city come out to welcome them. It's something of a small ceremony for them.",
  ui_story_5070_50700101_128_dialog_content = "Haha... But with how excited this crowd is, we can hardly see the ship itself.",
  ui_story_5070_50700101_129_dialog_content = "PlayerName! Thank goodness I've found you!",
  ui_story_5070_50700101_130_dialog_content = "Huh? It's the Lin Guild's...",
  ui_story_5070_50700101_131_dialog_content = "Yes, and as you can see, the Shadowind has finally arrived safely at our harbor!",
  ui_story_5070_50700101_132_dialog_content = "The captain would like a word with you as well. This way, please.",
  ui_story_5070_50700101_133_dialog_content = "The captain? But we didn't do anything at all...",
  ui_story_5070_50700101_134_dialog_content = "That's hardly true.",
  ui_story_5070_50700101_135_dialog_content = "Allow me to introduce myself. I'm Mu Yuebai, the captain of Shadowind.",
  ui_story_5070_50700101_136_dialog_content = "Perhaps it was nothing for the legendary Caelestite, but you helped the Shadowind more than you know.",
  ui_story_5070_50700101_137_dialog_content = "The truth is, our ship encountered a serious problem half a year ago, and we lost contact with the Lin Family.",
  ui_story_5070_50700101_138_dialog_content = "Our armillary sphere, a tool used by the Lin Family to navigate the sea based on the positions of the stars, was also lost in the aftermath.",
  ui_story_5070_50700101_139_dialog_content = "As a result, we had to rely on experience and sea charts alone to plot a new, half-blind course across the ocean.",
  ui_story_5070_50700101_140_dialog_content = "Along the way, we were beset by savage storms and vicious Eclipsites, and that whirlpool we encountered earlier was just as dangerous.",
  ui_story_5070_50700101_141_dialog_content = "If it wasn't for your guidance, PlayerName...",
  ui_story_5070_50700101_142_dialog_content = "Even if we had escaped the whirlpool, we'd have been lost at sea for days before finding our way here.",
  ui_story_5070_50700101_143_dialog_content = "So even if you think you did nothing for us, I must properly express my gratitude for your guidance and protection.",
  ui_story_5070_50700101_144_dialog_content = "Per the guild's tradition, those who help the Lin Family in a significant way must be repaid twice over by being taken into the guild as honored guests.",
  ui_story_5070_50700101_145_dialog_content = "If the Twin Pavilions Bay branch is unable to compensate you, then on my authority as captain, I'll repay you myself.",
  ui_story_5070_50700101_146_dialog_content = "A-Ahem! Don't get ahead of yourself now, Captain Yuebai.",
  ui_story_5070_50700101_147_dialog_content = "We've already come to an agreement the Astra way. Furthermore, our honored friend does not fully align himself with any particular entity...",
  ui_story_5070_50700101_148_dialog_content = "I need your answer, PlayerName. Will you join forces with the Lin Family?",
  ui_story_5070_50700101_149_dialog_content = "(Huh? Am I imagining things, or is the captain trying to get me to join them officially?!)",
  ui_story_5070_50700101_150_dialog_content = "C-Captain! While it's true that I came here looking for a big reward...",
  ui_story_5070_50700101_151_dialog_content = "I only helped in the smallest of ways, that's the truth. And I was just carrying out my duty as per the agreement.",
  ui_story_5070_50700101_152_dialog_content = "Speaking of repayment, the Lin family has been kind to me too. It goes both ways.",
  ui_story_5070_50700101_153_dialog_content = "Which is why I can't accept that kind of reward, or join the Lin Family for that matter.",
  ui_story_5070_50700101_154_dialog_content = "...",
  ui_story_5070_50700101_155_dialog_content = "Heheh, I've long since known about Captain Yuebai's heavy-handed way of dealing with others. Her benevolence is matched only by her imposing strength...",
  ui_story_5070_50700101_156_dialog_content = "Imagine getting turned down, how very amusing.",
  ui_story_5070_50700101_157_dialog_content = "Allow me to intervene on this young man's behalf...",
  ui_story_5070_50700101_158_dialog_content = "so that he may speak with you on more local terms, would that be acceptable?",
  ui_story_5070_50700101_159_dialog_content = "Yep! I'm not looking for an alliance or any special treatment. Being friends with the Lin Family is good enough for me!",
  ui_story_5070_50700101_160_dialog_content = "I wouldn't mind going for a ride on the Shadowind someday though! You're welcome to come aboard my Colossus too, Captain Yuebai!",
  ui_story_5070_50700101_161_dialog_content = "... The Shadowind is far too damaged to properly entertain guests right now.",
  ui_story_5070_50700101_162_dialog_content = "Since Lady Dantang has made her wishes clear, I'll naturally abide by them.",
  ui_story_5070_50700101_163_dialog_content = "Forgive me if I was out of line just now.",
  ui_story_5070_50700101_164_dialog_content = "Don't worry about it! You can just call me by my name too.",
  ui_story_5070_50700101_165_dialog_content = "The Shadowind will be docked here for the next two weeks or so. With all of the repairs it requires, we might have need of your services again soon.",
  ui_story_5070_50700101_166_dialog_content = "You will be generously compensated, of course.",
  ui_story_5070_50700101_167_dialog_content = "Sounds good to me! Some of my friends are still waiting for me, but I look forward to seeing you again!",
  ui_story_5070_50700101_168_dialog_content = "Just a moment, Captain. I wasn't informed that the Shadowind would stay in port for so long.",
  ui_story_5070_50700101_169_dialog_content = "Are there any other requests that—",
  ui_story_5070_50700101_170_dialog_content = "<color=#e8d9bb>Crack!</color>",
  ui_story_5070_50700101_171_dialog_content = "<color=#e8d9bb>A splitting sound rings out from the ship overhead as a large piece of lumber suddenly breaks off and falls into the sea.</color>",
  ui_story_5070_50700101_172_dialog_content = "Does that answer your question?",
  ui_story_5070_50700101_173_dialog_content = "U-Understood... The Shadowind is certainly in dire need of repair. I'll contact Li and Sun right away.",
  ui_story_5070_50700101_174_dialog_content = "Rest assured, they're experts. They oversee the repairs done on every ship that docks in Twin Pavilions Bay.",
  ui_story_5070_50700101_175_dialog_content = "This won't be an easy job for them, I'm afraid.",
  ui_story_5070_50700101_176_dialog_content = "Why isn't PlayerName back yet? Don't tell me they've detained him?!",
  ui_story_5070_50700101_177_dialog_content = "Ugh, I can't just stay here and wait. I have to go look for him!",
  ui_story_5070_50700101_178_dialog_content = "So this is Twin Pavilions Bay?",
  ui_story_5070_50700101_179_dialog_content = "The architectural style is indeed reminiscent of Longzhou, but a few details have been somewhat exoticized. Interesting, to say the least.",
  ui_story_5070_50700101_180_dialog_content = "Let's go for a tour of the town, Jiu.",
  ui_story_5070_50700101_181_dialog_content = "I happen to know that a certain personage from Ye who has been here for some time now...",
  ui_story_5070_50700101_182_dialog_content = "I'm sure she can show us plenty of interesting sights here.",
  ui_story_5070_50700101_183_dialog_content = "The voyage was a long and tiring one, Your Highness. Shouldn't we find a place for you to rest first?",
  ui_story_5070_50700101_184_dialog_content = "My, my, you seem to be missing the point, Miss Jiu.",
  ui_story_5070_50700101_185_dialog_content = "The best part of any journey is enjoying the sights and roaming the streets to your heart's content.",
  ui_story_5070_50700101_186_dialog_content = "Allow me to accompany the two of you. Perhaps I can find even more auspicious ground for Princess Dantang to tread upon?",
  ui_story_5070_50700101_187_dialog_content = "Hmph. I'm tired.",
  ui_story_5070_50700101_188_dialog_content = "Jiu is right, we should go back to Yuebai and rest for the day.",
  ui_story_5070_50700101_189_dialog_content = "Hey... Wait for me, Your Highness!",
  ui_story_5070_50700101_190_dialog_content = "I can have many types of people with me. Friends, warriors, and even enemies...",
  ui_story_5070_50700101_191_dialog_content = "But swindlers have no place at my side.",
  ui_story_5070_50700101_192_dialog_content = "Don't be so cruel, Your Highness. And after all we've been through together too...",
  ui_story_5070_50700101_193_dialog_content = "(She's really pretty... Wait, did that guy call her \"Highness\"?!)",
  ui_story_5070_50700101_194_dialog_content = "Vice? Vice! What are you looking at?",
  ui_story_5070_50700101_195_dialog_content = "Aaah! You're finally back!",
  ui_story_5070_50700101_196_dialog_content = "I was just thinking that on top of bringing lots of goods...",
  ui_story_5070_50700101_197_dialog_content = "The Shadowind also brought lots of interesting people. Some of them might even become our friends!",
  ui_story_5070_50700101_198_dialog_content = "Agh, this won't work. If only it was still the old Shadowind.",
  ui_story_5070_50700101_199_dialog_content = "I can hardly recognize any of the techniques used on this new model, whether it's the furnace, the heat dissipators, or the waterproofing.",
  ui_story_5070_50700101_200_dialog_content = "And don't even get me started on all these Ye components they threw into the mix.",
  ui_story_5070_50700101_201_dialog_content = "See?",
  ui_story_5070_50700101_202_dialog_content = "...",
  ui_story_5070_50700101_203_dialog_content = "Pardon me... What seems to be the trouble, everyone?",
  ui_story_5070_50700101_204_dialog_content = "Princess Dantang!",
  ui_story_5070_50700101_205_dialog_content = "I would rather not bother you with the details, Your Highness. After all, you have your mission to carry out.",
  ui_story_5070_50700101_206_dialog_content = "Are you still upset with me for upstaging you earlier, Yuebai?",
  ui_story_5070_50700101_207_dialog_content = "You're all too familiar with the dealings and disputes between the eight vassal kingdoms of Longzhou.",
  ui_story_5070_50700101_208_dialog_content = "Although I'm here as a representative of Ji, to them, I'll always be a Ye hostage.",
  ui_story_5070_50700101_209_dialog_content = "Earning the Ji kingdom's full trust is extremely difficult, given my identity.",
  ui_story_5070_50700101_210_dialog_content = "Which is precisely why I volunteered to sail across the sea and come to Astra.",
  ui_story_5070_50700101_211_dialog_content = "I can only hope that my actions will prove my sincerity.",
  ui_story_5070_50700101_212_dialog_content = "All that I do, I do for the mutual peace and prosperity of the two kingdoms.",
  ui_story_5070_50700101_213_dialog_content = "And since the Shadowind is inextricably linked to commerce, shouldn't I also be concerned for its well-being?",
  ui_story_5070_50700101_214_dialog_content = "If so, then naturally I must do all that I can for its sake.",
  ui_story_5070_50700101_215_dialog_content = "... It's the Shadowind's repairs.",
  ui_story_5070_50700101_216_dialog_content = "This new ship is equipped with the most cutting-edge technology that was carefully developed by Ye's finest technicians. It's nothing like its predecessor.",
  ui_story_5070_50700101_217_dialog_content = "Without artisans who are capable of mastering this new technology, I'm afraid repairing the Shadowind will be a long and difficult project.",
  ui_story_5070_50700101_218_dialog_content = "Twin Pavilions Bay has plenty of raw materials and shipwrights to work with them, but none of them are equipped to handle the Shadowind...",
  ui_story_5070_50700101_219_dialog_content = "Phew!",
  ui_story_5070_50700101_220_dialog_content = "Princess Dantang?",
  ui_story_5070_50700101_221_dialog_content = "If it had been anything else, I really wouldn't have been able to help at all.",
  ui_story_5070_50700101_222_dialog_content = "But if you need a talented Ye artisan, I think I know just the person for the job.",
  ui_story_5070_50700101_223_dialog_content = "How much time were you planning to spend on the Shadowind's repairs, Yuebai?",
  ui_story_5070_50700101_224_dialog_content = "Half a month.",
  ui_story_5070_50700101_225_dialog_content = "Then there should be enough time.",
  ui_story_5070_50700101_226_dialog_content = "Put your minds at ease. Ye's greatest artisan happens to be right here in Twin Pavilions Bay.",
  ui_story_5070_50700101_227_dialog_content = "By using this transmitter bird that she invented, I should be able to find her soon!",
  ui_story_5070_50700101_228_dialog_content = "Now that the Shadowind is safely docked in the harbor, our work here should be done... Sigh...",
  ui_story_5070_50700101_229_dialog_content = "Is something troubling you?",
  ui_story_5070_50700101_230_dialog_content = "I know what it is. PlayerName made such a big, righteous deal about refusing Captain Yuebai's offer...",
  ui_story_5070_50700101_231_dialog_content = "Kicking himself for turning down such a sweet deal, I bet.",
  ui_story_5070_50700101_232_dialog_content = "If you knew it would bother you this much, you should have just accepted back then.",
  ui_story_5070_50700101_233_dialog_content = "... No way.",
  ui_story_5070_50700101_234_dialog_content = "Even though Soroz's repairs and our daily expenses have made things tight lately...",
  ui_story_5070_50700101_235_dialog_content = "Even though I have no idea where I'll find another job...",
  ui_story_5070_50700101_236_dialog_content = "I won't accept payment for something I didn't do.",
  ui_story_5070_50700101_237_dialog_content = "Besides, I'm still pretty young. I don't want to spend the best years of my life working as a clerk for the Lin Guild or something...",
  ui_story_5070_50700101_238_dialog_content = "I don't think joining the Lin Guild necessarily means that you have to become a clerk.",
  ui_story_5070_50700101_239_dialog_content = "I think you might be missing the point here, Carleen.",
  ui_story_5070_50700101_240_dialog_content = "My fellow Twin Pavilions Bay kin!!!",
  ui_story_5070_50700101_241_dialog_content = "Wow, that's really loud! Where is that coming from?",
  ui_story_5070_50700101_242_dialog_content = "Did they install one of Illumina's military loudspeaker systems on the roofs or something?",
  ui_story_5070_50700101_243_dialog_content = "After a long and arduous journey from Longzhou, the Shadowind will be in port for approximately two weeks,",
  ui_story_5070_50700101_244_dialog_content = "and will undergo much-needed repair work!",
  ui_story_5070_50700101_245_dialog_content = "To this end, we're recruiting any capable porters and craftsmen in the area!",
  ui_story_5070_50700101_246_dialog_content = "Everyone is invited to sign up! Those who lend their knowledge and labor to our repair efforts",
  ui_story_5070_50700101_247_dialog_content = "will reap the benefits that the Shadowind brings from the other side of the sea!",
  ui_story_5070_50700101_248_dialog_content = "(Panting) B-Boss... Hurry and gather the workers!",
  ui_story_5070_50700101_249_dialog_content = "I've gotta hire more temp staff right away. I'm gonna go work on an announcement right away.",
  ui_story_5070_50700101_250_dialog_content = "I don't think you need to! I'm pretty sure the whole town heard the news!",
  ui_story_5070_50700101_251_dialog_content = "But how? I didn't know Twin Pavilions Bay had a system like this in place...",
  ui_story_5070_50700101_252_dialog_content = "Could this have something to do with what Captain Yuebai said earlier...?",
  ui_story_5070_50700101_253_dialog_content = "What perfect timing! Let's go see if there are any good jobs available!",
  ui_story_5070_50700101_254_dialog_content = "We might be able to make a fair amount of money while we're here!",
  ui_story_5070_50700201_1_dialog_content = "And so we spent two very productive weeks in Twin Pavilions Bay.",
  ui_story_5070_50700201_2_dialog_content = "Aside from doing all kinds of odd jobs for the Shadowind, I also did plenty of other things...",
  ui_story_5070_50700201_3_dialog_content = "For instance, there was one day when Carleen and I were watching the repairs being done on the Shadowind.",
  ui_story_5070_50700201_4_dialog_content = "A strange fortune-teller holding a bunch of weird-looking sticks appeared and tricked us into drawing a bunch of weird fortune sticks.",
  ui_story_5070_50700201_5_dialog_content = "I also helped Vice prepare for a special dance that's supposed to bring blessings and ward off disasters at sea.",
  ui_story_5070_50700201_6_dialog_content = "That was also the day that we formally met Princess Dantang, who'd previously saved me from that uncomfortable situation.",
  ui_story_5070_50700201_7_dialog_content = "At first, I was worried that a noble from a foreign country would be hard to talk to, but she turned out to be really approachable and intelligent.",
  ui_story_5070_50700201_8_dialog_content = "Afterward, she and her black-clothed servant taught us all about Longzhou's unique culture.",
  ui_story_5070_50700201_9_dialog_content = "Unfortunately, Carleen and Vice had to go back to Lumopolis and Illumina after receiving new orders.",
  ui_story_5070_50700201_10_dialog_content = "But that won't stop me from earning even more money for us! This is a rare opportunity, after all!",
  ui_story_5070_50700201_11_dialog_content = "... PlayerName?",
  ui_story_5070_50700201_12_dialog_content = "Huh? Oh! Sorry, Princess Dantang, I blanked out for a minute there.",
  ui_story_5070_50700201_13_dialog_content = "That's quite alright, I was just about to get to the important part.",
  ui_story_5070_50700201_14_dialog_content = "Also, didn't I tell you to just call me Dantang?",
  ui_story_5070_50700201_15_dialog_content = "Yes, sorry Prin—I mean Dantang.",
  ui_story_5070_50700201_16_dialog_content = "(Sighs) I didn't come here to listen to apologies, you know.",
  ui_story_5070_50700201_17_dialog_content = "I promised Yuebai that I would find her the perfect artisan to fix her ship, didn't I?",
  ui_story_5070_50700201_18_dialog_content = "Under her supervision, the Shadowind's repairs have gone swimmingly, and the ship is already in its last phase of maintenance.",
  ui_story_5070_50700201_19_dialog_content = "For that reason, we have begun preparations for a celebratory feast to commemorate the completion of the Shadowind's repairs.",
  ui_story_5070_50700201_20_dialog_content = "As for my own mission, my efforts have also proven fruitful.",
  ui_story_5070_50700201_21_dialog_content = "The Lumopolis envoy finally returned with a response thanks to Lady Carleen.",
  ui_story_5070_50700201_22_dialog_content = "They have agreed to welcome us as visitors from Longzhou and discuss both trade negotiations and Eclipsite countermeasures.",
  ui_story_5070_50700201_23_dialog_content = "The envoy will also attend the feast, and will travel to Longzhou aboard the Shadowind to visit Ji.",
  ui_story_5070_50700201_24_dialog_content = "Sounds like a successful mission to me, Dantang! Congrats!",
  ui_story_5070_50700201_25_dialog_content = "Heheh, thank you, PlayerName.",
  ui_story_5070_50700201_26_dialog_content = "Now then, the reason I've come here today is to invite you to the banquet as well.",
  ui_story_5070_50700201_27_dialog_content = "You mean I can go too? I'd be honored!",
  ui_story_5070_50700201_28_dialog_content = "And we'd be honored to have you there.",
  ui_story_5070_50700201_29_dialog_content = "A pity that Miss Vice and Lady Carleen won't be coming. I truly wanted to express my gratitude for their help personally.",
  ui_story_5070_50700201_30_dialog_content = "I'll be sure to treat you especially well in their absence.",
  ui_story_5070_50700201_31_dialog_content = "That sounds good to me. I'll finish up the rest of my work in the meantime. See you at the banquet!",
  ui_story_5070_50700201_32_dialog_content = "Let's see...",
  ui_story_5070_50700201_33_dialog_content = "Deliver a bill to the shop in the eastern part of town, check. Gather and return the workers' tools, check.",
  ui_story_5070_50700201_34_dialog_content = "Deliver a shipment of goods to this warehouse at the end of Chunxi Street, check... but not really.",
  ui_story_5070_50700201_35_dialog_content = "*Sighs*",
  ui_story_5070_50700201_36_dialog_content = "I got up early to deliver this shipment, but no one has come to get it yet.",
  ui_story_5070_50700201_37_dialog_content = "I even had the time to get some other stuff done in the meantime. I wonder why no one's here?",
  ui_story_5070_50700201_38_dialog_content = "Today's the day of the Shadowind's banquet. I'm gonna be late if the client doesn't show up.",
  ui_story_5070_50700201_39_dialog_content = "What's with these weirdly shaped crates anyway?",
  ui_story_5070_50700201_40_dialog_content = "Do they really need this stuff to fix a ship?",
  ui_story_5070_50700201_41_dialog_content = "... Huh?",
  ui_story_5070_50700201_42_dialog_content = "Why does it feel like something's off about these crates?",
  ui_story_5070_50700201_43_dialog_content = "<color=#e8d9bb>Creak—Creak—</color>",
  ui_story_5070_50700201_44_dialog_content = "What was that?!",
  ui_story_5070_50700201_45_dialog_content = "<color=#e8d9bb>Crack!</color>",
  ui_story_5070_50700201_46_dialog_content = "Is that some kind of... crab monster? W-Wait, stay back!",
  ui_story_5070_50700201_47_dialog_content = "Those pincers look nasty, but it's a good thing I was quick enough to avoid them...",
  ui_story_5070_50700201_48_dialog_content = "Hiss—!",
  ui_story_5070_50700201_49_dialog_content = "Whoa—It can breathe fire?!",
  ui_story_5070_50700201_50_dialog_content = "<color=#e8d9bb>A spout of scorching fire erupts from the monster's mouth.</color>",
  ui_story_5070_50700201_51_dialog_content = "<color=#e8d9bb>Suddenly, a large parasol appears.</color>",
  ui_story_5070_50700201_52_dialog_content = "<color=#e8d9bb>Glinting brightly as it rapidly spins around, the metallic parasol quickly disperses the incoming flames.</color>",
  ui_story_5070_50700201_53_dialog_content = "Dry weather makes it easy for things to catch fire, so be careful!",
  ui_story_5070_50700201_54_dialog_content = "<color=#e8d9bb>The monsters' flames seem to have no end, but the parasol keeps them well at bay. Only a faint heat from the fire manages to get through.</color>",
  ui_story_5070_50700201_55_dialog_content = "That voice sounds familiar... Hey, I remember now! You used that dragonfly to help me catch my letter before!",
  ui_story_5070_50700201_56_dialog_content = "But what's with this parasol...?",
  ui_story_5070_50700201_57_dialog_content = "Oh, I wouldn't touch that right now if I were you. I'm not liable for any injuries you might sustain!",
  ui_story_5070_50700201_58_dialog_content = "Besides, I still have to deal with these rascals.",
  ui_story_5070_50700202_1_dialog_content = "A-Amazing!",
  ui_story_5070_50700202_2_dialog_content = "(It looks just like a regular parasol, but it's sharper than even the most legendary sword!)",
  ui_story_5070_50700202_3_dialog_content = "(When it's open, no amount of water or fire can get past it.)",
  ui_story_5070_50700202_4_dialog_content = "(When it's closed, it turns into an unstoppable blade.)",
  ui_story_5070_50700202_5_dialog_content = "(My eyes can't even follow her movements!)",
  ui_story_5070_50700202_6_dialog_content = "(With a flick of the wrist and a twist of her parasol, she turned those monsters into a bunch of scrap metal.)",
  ui_story_5070_50700202_7_dialog_content = "Hiss—",
  ui_story_5070_50700202_8_dialog_content = "(Wait, they're made of metal? Does that mean someone built these things?)",
  ui_story_5070_50700202_9_dialog_content = "Why in the world would anyone want to make giant, mechanical crabs as terrifying as this...?",
  ui_story_5070_50700202_10_dialog_content = "These fire crabs are just one of many Clockwork Beasts that are regularly used in the Ye kingdom's workshops.",
  ui_story_5070_50700202_11_dialog_content = "They're designed to assist with welding and joint construction, nothing more.",
  ui_story_5070_50700202_12_dialog_content = "Their pincers and their ability to unleash small, controlled flames make them a useful addition to any workshop!",
  ui_story_5070_50700202_13_dialog_content = "Welding? Joint construction? Wait, so does that mean they thought I was raw material or something?",
  ui_story_5070_50700202_14_dialog_content = "Well... judging from your strength and durability, you clearly don't fit the bill.",
  ui_story_5070_50700202_15_dialog_content = "Logically speaking, fire crabs shouldn't make such a simple mistake...",
  ui_story_5070_50700202_16_dialog_content = "I don't know how I'm supposed to feel about that.",
  ui_story_5070_50700202_17_dialog_content = "What's more, Ye has very strict regulations concerning the dissemination and use of Clockwork Beasts.",
  ui_story_5070_50700202_18_dialog_content = "For them to not only appear in this place and even attack people...",
  ui_story_5070_50700202_19_dialog_content = "It definitely means that someone's up to no good.",
  ui_story_5070_50700202_20_dialog_content = "So are you gonna come out on your own, or do I need to make the first move?",
  ui_story_5070_50700202_21_dialog_content = "(There's someone else in here?!)",
  ui_story_5070_50700202_22_dialog_content = "<color=#e8d9bb>A shadowy figure suddenly leaps out of the shadows and sprints towards the door.</color>",
  ui_story_5070_50700202_23_dialog_content = "Hold it!",
  ui_story_5070_50700202_24_dialog_content = "(He dodged the attack... I have to cut him off somehow!)",
  ui_story_5070_50700202_25_dialog_content = "Force Boost!",
  ui_story_5070_50700202_26_dialog_content = "Relax, I know the rules. After all, I've been doing this kinda thing in Umbraton for years.",
  ui_story_5070_50700202_27_dialog_content = "After accepting a client's payment, it's only natural to do things according to their wishes.",
  ui_story_5070_50700202_28_dialog_content = "Besides, they're only asking me to learn how to work these, uh... What do you call these giant crabs again?",
  ui_story_5070_50700202_29_dialog_content = "\"Furnace-Forged Crabs\" or something, right?",
  ui_story_5070_50700202_30_dialog_content = "It'll be a pain, that's for sure.",
  ui_story_5070_50700202_31_dialog_content = "But this pain is nothing if it means I get to make the Lin Family and the Shadowind suffer.",
  ui_story_5070_50700202_32_dialog_content = "(He's targeting the Shadowind? But why...?)",
  ui_story_5070_50700202_33_dialog_content = "Outta my way!",
  ui_story_5070_50700202_34_dialog_content = "Ah—",
  ui_story_5070_50700202_35_dialog_content = "Careful.",
  ui_story_5070_50700202_36_dialog_content = "Th-Thanks for catching me. I would've gotten really hurt if you hadn't. Who was—",
  ui_story_5070_50700202_37_dialog_content = "Never mind him. No use chasing cornered prey, unless you want to get bitten.",
  ui_story_5070_50700202_38_dialog_content = "That guy's just an insignificant puppet.",
  ui_story_5070_50700202_39_dialog_content = "As for the one pulling his strings, I already have my suspicions.",
  ui_story_5070_50700202_40_dialog_content = "I'll have to rely on the folks here in Twin Pavilions Bay to help me find this–",
  ui_story_5070_50700202_41_dialog_content = "W-Wait, that voice!",
  ui_story_5070_50700202_42_dialog_content = "No wonder you sound so familiar! You're the one who put all those loudspeakers on the city gate towers!",
  ui_story_5070_50700202_43_dialog_content = "Who exactly are you?",
  ui_story_5070_50700202_44_dialog_content = "Huh? You don't know who I am?",
  ui_story_5070_50700202_45_dialog_content = "I-I'm sorry?",
  ui_story_5070_50700202_46_dialog_content = "Haha, just pulling your leg! I'm not so conceited that I would blame someone across the sea for not knowing who I am!",
  ui_story_5070_50700202_47_dialog_content = "Still, I'm surprised Dantang hasn't introduced me, considering how much she's told me about you.",
  ui_story_5070_50700202_48_dialog_content = "That's not very fair at all!",
  ui_story_5070_50700202_49_dialog_content = "Anyway, allow me to introduce myself.",
  ui_story_5070_50700202_50_dialog_content = "My name's Xuan Ji. I'm an artisan.",
  ui_story_5070_50700202_51_dialog_content = "And just like Princess Dantang, I also hail from the artisan capital of Longzhou: the vassal kingdom of Ye.",
  ui_story_5070_50700202_52_dialog_content = "I've been living in Twin Pavilions Bay for a while now, idling away and doing things like returning lost objects to their rightful owners.",
  ui_story_5070_50700202_53_dialog_content = "But thanks to Princess Dantang's weighty recommendation, I'm now the temporary head technician for the Shadowind.",
  ui_story_5070_50700202_54_dialog_content = "I'm not only in charge of the Shadowind's repairs, but also the maintenance of the voice-transmitting Clockwork Birds that I lent to the Lin Guild.",
  ui_story_5070_50700202_55_dialog_content = "Clockwork Birds? So that's how you did it...?",
  ui_story_5070_50700202_56_dialog_content = "Yep! Essentially, they're just flying loudspeakers that never need to be hung up.",
  ui_story_5070_50700202_57_dialog_content = "But that didn't stop me from carefully attaching beaks and feathers to them!",
  ui_story_5070_50700202_58_dialog_content = "... So you're the great artisan that Dantang told me about.",
  ui_story_5070_50700202_59_dialog_content = "You sure live up to your name!",
  ui_story_5070_50700202_60_dialog_content = "I should also mention something.",
  ui_story_5070_50700202_61_dialog_content = "Those big, terrifying crabs lying all over the ground? I designed them too.",
  ui_story_5070_50700202_62_dialog_content = "?",
  ui_story_5070_50700301_1_dialog_content = "Without further ado, please welcome Captain Yuebai as she delivers a speech for tonight's banquet!",
  ui_story_5070_50700301_2_dialog_content = "The Shadowind's smooth and expedient repairs were the result of everyone's hard work and perseverance.",
  ui_story_5070_50700301_3_dialog_content = "Tonight's banquet is in honor of everyone in attendance.",
  ui_story_5070_50700301_4_dialog_content = "The Lin Family has always valued hard and honest work, and is more than happy to reward such fine efforts.",
  ui_story_5070_50700301_5_dialog_content = "So please eat, drink, and enjoy yourselves as much as possible tonight.",
  ui_story_5070_50700301_6_dialog_content = "Wooo!!!",
  ui_story_5070_50700301_7_dialog_content = "I never thought a banquet as lively as this could be held on a ship.",
  ui_story_5070_50700301_8_dialog_content = "Your praise is most appreciated, Telema of Lumopolis.",
  ui_story_5070_50700301_9_dialog_content = "I wonder what other surprises Longzhou has in store for me? I'm looking forward to finding out.",
  ui_story_5070_50700301_10_dialog_content = "That's only natural.",
  ui_story_5070_50700301_11_dialog_content = "Longzhou is very particular when it comes to receiving guests from afar. As an envoy from Lumopolis, you'll be regarded as a rare and special guest.",
  ui_story_5070_50700301_12_dialog_content = "Nothing but the very best treatment will suffice.",
  ui_story_5070_50700301_13_dialog_content = "When you put it that way, I'm all the more excited to visit the other side of the sea!",
  ui_story_5070_50700301_14_dialog_content = "But Longzhou is still a long way away, so may I first learn a little more about the Shadowind's features?",
  ui_story_5070_50700301_15_dialog_content = "Ever since I arrived in Twin Pavilions Bay, I've heard so many interesting rumors about this ship's technology.",
  ui_story_5070_50700301_16_dialog_content = "With its meticulously crafted components and countless functions, the Shadowind is supposed to be nothing short of a work of art.",
  ui_story_5070_50700301_17_dialog_content = "In any case, it looks far more agreeable than any of the bulky and unwieldy technology used in Illumina or the desert.",
  ui_story_5070_50700301_18_dialog_content = "Every place has its own unique technologies. Naturally, their advantages and disadvantages are just as varied.",
  ui_story_5070_50700301_19_dialog_content = "Allow me to find a suitable guide to introduce its features.",
  ui_story_5070_50700301_20_dialog_content = "(Xuan Ji... Where have you gone?)",
  ui_story_5070_50700301_21_dialog_content = "Ah, Sun! Your timing couldn't be more perfect!",
  ui_story_5070_50700301_22_dialog_content = "Y-Your Highness?! H-How may I be of service?",
  ui_story_5070_50700301_23_dialog_content = "Would you be so kind as to show some of the Shadowind's features to our friend here? The envoy of Lumopolis is very curious about the ship's many functions.",
  ui_story_5070_50700301_24_dialog_content = "But of course!",
  ui_story_5070_50700301_25_dialog_content = "I've been tinkering with these contraptions for the last few decades. You won't find a better guide than me!",
  ui_story_5070_50700301_26_dialog_content = "Then I'll leave the rest in your capable hands.",
  ui_story_5070_50700301_27_dialog_content = "Until we meet again, my lady.",
  ui_story_5070_50700301_28_dialog_content = "Phew.",
  ui_story_5070_50700301_29_dialog_content = "What is it, Your Highness? Do you require rest?",
  ui_story_5070_50700301_30_dialog_content = "Not at all. It's far too early for me to start feeling tired.",
  ui_story_5070_50700301_31_dialog_content = "But... I wonder where PlayerName could be?",
  ui_story_5070_50700301_32_dialog_content = "Could it be that his work has delayed his arrival?",
  ui_story_5070_50700301_33_dialog_content = "I could always go search for him—",
  ui_story_5070_50700301_34_dialog_content = "Wait!",
  ui_story_5070_50700301_35_dialog_content = "What is it, Jiu?",
  ui_story_5070_50700301_36_dialog_content = "Be wary of your surroundings, Your Highness.",
  ui_story_5070_50700301_37_dialog_content = "...",
  ui_story_5070_50700301_38_dialog_content = "Seems like I'll have to recite the Shadowind's code of conduct for our passengers some other time.",
  ui_story_5070_50700301_39_dialog_content = "What is it? What's going on?!",
  ui_story_5070_50700301_40_dialog_content = "Oh my, what could it be now? It was hard enough to gain a seat for tonight's banquet...",
  ui_story_5070_50700301_41_dialog_content = "An inauspicious start to the night, I must say.",
  ui_story_5070_50700301_42_dialog_content = "Stay on your guard, everyone!",
  ui_story_5070_50700301_43_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5070_50700301_44_dialog_content = "Ah! The ship is rocking back and forth!",
  ui_story_5070_50700301_45_dialog_content = "Captain! Some of the Clockwork Beasts have started attacking the Shadowind's support structures!",
  ui_story_5070_50700301_46_dialog_content = "We're in the middle of a banquet, aren't we? White Night up high. What on earth is going on here?!",
  ui_story_5070_50700301_47_dialog_content = "I demand to know what's happening to this ship right now!",
  ui_story_5070_50700301_48_dialog_content = "...",
  ui_story_5070_50700301_49_dialog_content = "Please stay here, Your Highness. I'll go take care of things.",
  ui_story_5070_50700301_50_dialog_content = "Very well, but be careful.",
  ui_story_5070_50700302_1_dialog_content = "The matter has been settled, Your Highness.",
  ui_story_5070_50700302_2_dialog_content = "I'm glad to hear it.",
  ui_story_5070_50700302_3_dialog_content = "But why do you look so troubled? Don't tell me you were hurt during the chaos—",
  ui_story_5070_50700302_4_dialog_content = "I'm fine, Jiu.",
  ui_story_5070_50700302_5_dialog_content = "Due to the Clockwork Beasts losing control, the Lin Guild is now discussing whether or not to delay the Shadowind's departure.",
  ui_story_5070_50700302_6_dialog_content = "This decision isn't being made out of cowardice.",
  ui_story_5070_50700302_7_dialog_content = "However, the sea is fraught with dangers, like storms and Eclipsites...",
  ui_story_5070_50700302_8_dialog_content = "To add to all of that, our Clockwork Beasts have begun inexplicably attacking us.",
  ui_story_5070_50700302_9_dialog_content = "It's too dangerous to leave the harbor. We must be patient and continue watching for any changes.",
  ui_story_5070_50700302_10_dialog_content = "But we don't have time to simply wait and see.",
  ui_story_5070_50700302_11_dialog_content = "As many of you are aware, I have journeyed to Astra in order to accomplish two goals.",
  ui_story_5070_50700302_12_dialog_content = "The first is to improve relations with the governing factions of this continent and formally enter trade agreements.",
  ui_story_5070_50700302_13_dialog_content = "The second is to exchange technical and tactical knowledge for countering the Eclipsite threat.",
  ui_story_5070_50700302_14_dialog_content = "Does everyone know why these two goals have been given such high priority?",
  ui_story_5070_50700302_15_dialog_content = "It's because the coasts of Longzhou have fallen under frequent Eclipsite attack in recent years. As a result, our merchant vessels and their voyages have been greatly affected.",
  ui_story_5070_50700302_16_dialog_content = "Ji, one of the eight vassal kingdoms with which I'm affiliated, was founded on commerce. As such, its prosperity depends almost entirely on safe waterways and robust transportation.",
  ui_story_5070_50700302_17_dialog_content = "The many guilds of Ji have long since requested that we rectify this issue.",
  ui_story_5070_50700302_18_dialog_content = "But the royal court has yet to find a lasting solution. No matter how many times we drive them back, more waves of Eclipsites take their place. This has driven many of our people from the coasts, leaving these areas susceptible to pirate occupation.",
  ui_story_5070_50700302_19_dialog_content = "Our merchants and shipping industry workers are under constant threat of attack, and our people are unable to lead peaceful lives.",
  ui_story_5070_50700302_20_dialog_content = "For this reason, our king decided to appoint and dispatch a noble emissary to Astra. In doing so, he hopes to find a breakthrough in our struggle against the Eclipsites.",
  ui_story_5070_50700302_21_dialog_content = "Convincing Lumopolis to allow an envoy to accompany me back to Longzhou for further talks was no easy feat...",
  ui_story_5070_50700302_22_dialog_content = "But now...",
  ui_story_5070_50700302_23_dialog_content = "I want off this ship right this instant.",
  ui_story_5070_50700302_24_dialog_content = "You promised that it was perfectly safe, didn't you? We haven't even left the harbor, and we've already fallen under attack!",
  ui_story_5070_50700302_25_dialog_content = "Is this what you people call safe?!",
  ui_story_5070_50700302_26_dialog_content = "No one told me those mechanical monsters were capable of attacking us!",
  ui_story_5070_50700302_27_dialog_content = "No one at all!",
  ui_story_5070_50700302_28_dialog_content = "I... I...",
  ui_story_5070_50700302_29_dialog_content = "... I can only dissuade the envoy for so long.",
  ui_story_5070_50700302_30_dialog_content = "If we can't fix the ship and send it on its way quickly, I fear things will change for the worse. If so, then my mission...",
  ui_story_5070_50700302_31_dialog_content = "Well...",
  ui_story_5070_50700302_32_dialog_content = "The princess makes a fine point, but we cannot afford to be reckless regardless of the circumstances.",
  ui_story_5070_50700302_33_dialog_content = "You would be putting your own life at risk as well.",
  ui_story_5070_50700302_34_dialog_content = "I believe we should wait, Your Highness.",
  ui_story_5070_50700302_35_dialog_content = "If the envoy is unwilling to make the voyage, I can always convince him in other ways.",
  ui_story_5070_50700302_36_dialog_content = "You've sacrificed much to get to this point. I refuse to let it all be in vain.",
  ui_story_5070_50700302_37_dialog_content = "Ahem, care to share your thoughts, Captain?",
  ui_story_5070_50700302_38_dialog_content = "...",
  ui_story_5070_50700302_39_dialog_content = "This voyage is undoubtedly a very important one. The ship carries more than just the princess and our merchandise.",
  ui_story_5070_50700302_40_dialog_content = "It also carries the future of the Lin Family.",
  ui_story_5070_50700302_41_dialog_content = "We've already incurred too many losses at sea... I'm afraid we won't be able to withstand yet another heavy blow.",
  ui_story_5070_50700302_42_dialog_content = "Which is all the more reason to be cautious—",
  ui_story_5070_50700302_43_dialog_content = "So, begin repairs on the ship's frame immediately.",
  ui_story_5070_50700302_44_dialog_content = "We set sail as soon as the Shadowind is in working condition.",
  ui_story_5070_50700302_45_dialog_content = "A-Ahem!",
  ui_story_5070_50700302_46_dialog_content = "Captain! H-How could you also...",
  ui_story_5070_50700302_47_dialog_content = "Huh? Wait... Captain Yuebai!",
  ui_story_5070_50700302_48_dialog_content = "Honestly, why are all the young people like this nowadays?!",
  ui_story_5070_50700302_49_dialog_content = "Exactly! You know what they say. \"Haste makes waste; slow and steady wins the race.\"",
  ui_story_5070_50700302_50_dialog_content = "Unfortunately, the current situation doesn't seem to grant us the luxury of time. Quite the predicament indeed!",
  ui_story_5070_50700302_51_dialog_content = "Huh? Who are you...?",
  ui_story_5070_50700302_52_dialog_content = "Interesting, I don't seem to recall a swindler being invited to this banquet?",
  ui_story_5070_50700302_53_dialog_content = "Oh, Your Highness.",
  ui_story_5070_50700302_54_dialog_content = "Given all that has happened here today, I fear very few people still have an appetite.",
  ui_story_5070_50700302_55_dialog_content = "It would be a shame to let all of this delicious food go to waste, don't you think? Thankfully, I happen to have a very healthy appetite tonight!",
  ui_story_5070_50700302_56_dialog_content = "Everything tastes exquisite, though I do find the melon to be a bit underwhelming.",
  ui_story_5070_50700302_57_dialog_content = "In their rush to provide for the banquet, it appears the farmers harvested these melons before they were perfectly ripe and sweet.",
  ui_story_5070_50700302_58_dialog_content = "I-I've had just about enough of your prattling...",
  ui_story_5070_50700302_59_dialog_content = "I was merely making an observation, nothing more. In the end, it falls to you to decide whether or not to wait for the right time.",
  ui_story_5070_50700302_60_dialog_content = "But sometimes, it's best to let nature take its course. Letting the melon ripen and fall off the vine is far more agreeable than forcing everyone to partake in bitter and unpleasant fruit.",
  ui_story_5070_50700302_61_dialog_content = "Wouldn't you agree?",
  ui_story_5070_50700401_1_dialog_content = "Hmm, give me a minute to think of a way to explain this technology so that you can understand.",
  ui_story_5070_50700401_2_dialog_content = "... I got it! I understand that Astra has conducted extensive research on the Four Forces...",
  ui_story_5070_50700401_3_dialog_content = "The Four Forces?",
  ui_story_5070_50700401_4_dialog_content = "The four different elements of Lumina.",
  ui_story_5070_50700401_5_dialog_content = "My field of technological expertise is concerned with combining different materials...",
  ui_story_5070_50700401_6_dialog_content = "And creating machines that are capable of harnessing Lumina, just like Aurorians and spirit beasts.",
  ui_story_5070_50700401_7_dialog_content = "Does that make any more sense to you?",
  ui_story_5070_50700401_8_dialog_content = "Sounds a lot like the Lumina technology we have over here, but the style is completely different.",
  ui_story_5070_50700401_9_dialog_content = "Of course. Our goals are one and the same; the difference merely lies in our worldviews.",
  ui_story_5070_50700401_10_dialog_content = "The people of Longzhou believe that all things in this world contain Lumina.",
  ui_story_5070_50700401_11_dialog_content = "A vast, circulatory network of Lumina can be observed from the smallest blade of grass to the tallest tree, and from the tiniest insect to the most savage of beasts.",
  ui_story_5070_50700401_12_dialog_content = "Our techniques allow us to infuse Lumina into the materials used to make components. We can then produce any number of effects by regulating the flow of that Lumina.",
  ui_story_5070_50700401_13_dialog_content = "With proper materials and precise structures, our technology can even create an entirely new world!",
  ui_story_5070_50700401_14_dialog_content = "Wow, talking about your technology is like talking about the philosophy of creation!",
  ui_story_5070_50700401_15_dialog_content = "Hahaha, well you're not wrong!",
  ui_story_5070_50700401_16_dialog_content = "Those fire crabs from before, as well as my copper dragonflies, are all manifestations of that very same philosophy.",
  ui_story_5070_50700401_17_dialog_content = "My Peculiar Parasol is no exception either.",
  ui_story_5070_50700401_18_dialog_content = "It has countless mechanisms, which is why it is capable of both attacking and defending.",
  ui_story_5070_50700401_19_dialog_content = "When properly understood, the principles of our technology can be applied to far more than just clockwork beasts.",
  ui_story_5070_50700401_20_dialog_content = "I had no idea it was so impressive... I guess the study of machinery isn't as simple as I thought.",
  ui_story_5070_50700401_21_dialog_content = "Of course it isn't. After all, this technology is the foundation of an entire vassal kingdom, as well as the reason the Lin Family was able to re-establish their trade routes.",
  ui_story_5070_50700401_22_dialog_content = "In the Ye Kingdom, the skies are full of clockwork birds carrying messages while wooden oxes haul our goods on the ground.",
  ui_story_5070_50700401_23_dialog_content = "If you're ever too lazy to put on clothes, wash your face, or prepare food, there's a mechanical creature to help you finish any task.",
  ui_story_5070_50700401_24_dialog_content = "If you ever find the time to visit, I'd be happy to show you the true extent of our technology.",
  ui_story_5070_50700401_25_dialog_content = "Sounds good to me!",
  ui_story_5070_50700401_26_dialog_content = "But...",
  ui_story_5070_50700401_27_dialog_content = "What exactly are we doing right now?",
  ui_story_5070_50700401_28_dialog_content = "Isn't it obvious? We're looking for a warehouse that was used recently.",
  ui_story_5070_50700401_29_dialog_content = "I'm well aware of that, considering we've already checked out a handful of warehouses.",
  ui_story_5070_50700401_30_dialog_content = "(Some of them were locked too, but I wasn't fast enough to stop Xuan Ji from picking their locks...)",
  ui_story_5070_50700401_31_dialog_content = "But shouldn't we be chasing after the enemy right now?",
  ui_story_5070_50700401_32_dialog_content = "I'm an artisan, remember? Working with machinery is my specialty, so leave the searching to the little informants I've scattered all over the city.",
  ui_story_5070_50700401_33_dialog_content = "A group of thugs hiding in the shadows somehow managed to get my blueprints from an unknown source...",
  ui_story_5070_50700401_34_dialog_content = "They turned my fire crabs into tools for hurting people, and stowed a bunch of them in the Shadowind's warehouse.",
  ui_story_5070_50700401_35_dialog_content = "That failed ambush just now was clearly not their real objective.",
  ui_story_5070_50700401_36_dialog_content = "I'm sure they have even more traps hidden around Twin Pavilions Bay.",
  ui_story_5070_50700401_37_dialog_content = "... I'm really worried for the Shadowind's safety.",
  ui_story_5070_50700401_38_dialog_content = "Normal people don't stand a chance against those fire crabs.",
  ui_story_5070_50700401_39_dialog_content = "The strong must not oppress the weak, the many must not oppress the few, and the rich must not oppress the poor...",
  ui_story_5070_50700401_40_dialog_content = "With machinery comes great power, and those who wield it must never use it to hurt others.",
  ui_story_5070_50700401_41_dialog_content = "The artisans of my land came together to create this code of conduct, and we are all sworn to uphold it.",
  ui_story_5070_50700401_42_dialog_content = "For that reason, if I ever manage to find the thief who stole my blueprints...",
  ui_story_5070_50700401_43_dialog_content = "(Her voice suddenly turned cold as ice...)",
  ui_story_5070_50700401_44_dialog_content = "That's right!",
  ui_story_5070_50700401_45_dialog_content = "The way you put it, these clockwork beasts can simulate the flow of Lumina in living organisms...",
  ui_story_5070_50700401_46_dialog_content = "This means I might be able to use my powers to sense the location of more fire crabs!",
  ui_story_5070_50700401_47_dialog_content = "What an interesting conclusion.",
  ui_story_5070_50700401_48_dialog_content = "Here goes—",
  ui_story_5070_50700401_49_dialog_content = "(I just have to imagine the fire crabs from earlier, and the same type of Lumina they gave out... There!)",
  ui_story_5070_50700401_50_dialog_content = "It's faint, but at least I can sense their direction! It's over here!",
  ui_story_5070_50700401_51_dialog_content = "I never would've expected to find this small warehouse in such an out-of-the-way location.",
  ui_story_5070_50700401_52_dialog_content = "That was quite an impressive feat! Thank you for your help, PlayerName.",
  ui_story_5070_50700401_53_dialog_content = "<color=#e8d9bb>Inside the dilapidated warehouses are all kinds of strange-looking crates, each containing—</color>",
  ui_story_5070_50700401_54_dialog_content = "Fire crabs, floating harriers, even long scorpions... And they're all made from the highest-quality materials.",
  ui_story_5070_50700401_55_dialog_content = "The owner of these warehouses must have plenty of money to spare.",
  ui_story_5070_50700401_56_dialog_content = "What are they planning to do with so many clockwork beasts?",
  ui_story_5070_50700401_57_dialog_content = "Think you can give me a hand again, PlayerName?",
  ui_story_5070_50700401_58_dialog_content = "We need to open all of these crates and check the clockwork beasts for any markings or symbols.",
  ui_story_5070_50700401_59_dialog_content = "Now that you mention it, you did the exact same thing with those fire crabs earlier.",
  ui_story_5070_50700401_60_dialog_content = "But I don't see any markings on the clockwork beasts in either of these warehouses.",
  ui_story_5070_50700401_61_dialog_content = "Like I said before, the Ye Kingdom strongly regulates the use of clockwork inventions, as well as their blueprints and shipment channels.",
  ui_story_5070_50700401_62_dialog_content = "Whether they're mass-produced in a workshop or custom-built by a single artisan...",
  ui_story_5070_50700401_63_dialog_content = "Every single clockwork machine must be inscribed with a unique marking upon completion.",
  ui_story_5070_50700401_64_dialog_content = "That way, someone can always be held accountable if problems arise with the machine.",
  ui_story_5070_50700401_65_dialog_content = "So if we can't find any markings, does that mean our investigation reached a dead end?",
  ui_story_5070_50700401_66_dialog_content = "No.",
  ui_story_5070_50700401_67_dialog_content = "At the very least, it proves that these machines weren't built in a Ye Kingdom workshop.",
  ui_story_5070_50700401_68_dialog_content = "Their components have been smuggled out of the country and assembled over here.",
  ui_story_5070_50700401_69_dialog_content = "There are other things being kept in these warehouses as well.",
  ui_story_5070_50700401_70_dialog_content = "There's a bunch of other merchandise mixed in with the clockwork beasts.",
  ui_story_5070_50700401_71_dialog_content = "Wait a minute, these markings... the Lin Guild?",
  ui_story_5070_50700401_72_dialog_content = "Precisely.",
  ui_story_5070_50700401_73_dialog_content = "A couple of days ago, when the Shadowind first arrived in port, I overheard some of the passengers talking about the same thing.",
  ui_story_5070_50700401_74_dialog_content = "Something about the Lin Family getting involved in smuggling operations back in Longzhou, and the head of the family being arrested by the Maritime Trade Offices...",
  ui_story_5070_50700401_75_dialog_content = "PlayerName, can I ask you for yet another favor?",
  ui_story_5070_50700401_76_dialog_content = "I need you to ask Captain Yuebai...",
  ui_story_5070_50700401_77_dialog_content = "If the Lin Family is indeed involved in smuggling.",
  ui_story_5070_50700401_78_dialog_content = "I've been searching warehouses ever since I got attacked by those fire crabs earlier.",
  ui_story_5070_50700401_79_dialog_content = "I wonder if the Shadowind's banquet is over yet?",
  ui_story_5070_50700401_80_dialog_content = "Huh? Did something happen aboard the ship?",
  ui_story_5070_50700401_81_dialog_content = "Surely you're aware of the mutual benefits that our cooperation would bring, Telema.",
  ui_story_5070_50700401_82_dialog_content = "Of course I'm aware of them. Don't insult my intelligence.",
  ui_story_5070_50700401_83_dialog_content = "But no matter how great Longzhou may be or how vital our mission is, what's the point if we can't reach your homeland safely?",
  ui_story_5070_50700401_84_dialog_content = "I've taken multiple precautions to ensure your safety every step of the way.",
  ui_story_5070_50700401_85_dialog_content = "As an honorable citizen of Lumopolis, I truly wish to believe you.",
  ui_story_5070_50700401_86_dialog_content = "But... With all that has happened, I'm afraid I must reconsider.",
  ui_story_5070_50700401_87_dialog_content = "Telema...",
  ui_story_5070_50700401_88_dialog_content = "(Isn't that the Lumopolis envoy that Dantang's been talking about? Why the sudden change of heart?)",
  ui_story_5070_50700401_89_dialog_content = "The last suspicious location left to search is this pharmacy.",
  ui_story_5070_50700401_90_dialog_content = "This feeling... There appears to be a powerful user of the Flame Force Arts inside.",
  ui_story_5070_50700401_91_dialog_content = "Now then, let's see who's hiding just behind this door.",
  ui_story_5070_50700401_92_dialog_content = "<size=45>Knock, knock, knock!</size>",
  ui_story_5070_50700401_93_dialog_content = "What is it?",
  ui_story_5070_50700401_94_dialog_content = "Pardon my intrusion, but I have some questions I would like to ask.",
  ui_story_5070_50700401_95_dialog_content = "Are you familiar with the owner of that warehouse over there?",
  ui_story_5070_50700401_96_dialog_content = "If not, then are you familiar with the Lin Family?",
  ui_story_5070_50700401_97_dialog_content = "...",
  ui_story_5070_50700401_98_dialog_content = "(The door's opening? Better get ready for a fight! Full—)",
  ui_story_5070_50700401_99_dialog_content = "...",
  ui_story_5070_50700401_100_dialog_content = "?",
  ui_story_5070_50700401_101_dialog_content = "Why is there a child answering the door? Sorry, but could I speak to an adult?",
  ui_story_5070_50700401_102_dialog_content = "Who says I'm a child?!",
  ui_story_5070_50700401_103_dialog_content = "Well, you're clearly a...",
  ui_story_5070_50700401_104_dialog_content = "<color=#e8d9bb>Ding—!</color>",
  ui_story_5070_50700401_105_dialog_content = "You're quick on your feet.",
  ui_story_5070_50700401_106_dialog_content = "I knew I should've checked the almanac before going out today. I'm sure it would've warned me about coming to a place where they welcome visitors by drawing their swords.",
  ui_story_5070_50700401_107_dialog_content = "<size=45>Graaah—</size>",
  ui_story_5070_50700401_108_dialog_content = "Oh? My, this is quite the unexpected welcoming committee.",
  ui_story_5070_50700402_1_dialog_content = "These guys just don't know when to give up, do they?",
  ui_story_5070_50700402_2_dialog_content = "We keep killing them, but they keep popping up out of nowhere...",
  ui_story_5070_50700402_3_dialog_content = "Huh? Hey! Aren't you gonna fight her, Zhong Xu?",
  ui_story_5070_50700402_4_dialog_content = "A metal parasol, a copper dragonfly, and such finely crafted clockwork creations.",
  ui_story_5070_50700402_5_dialog_content = "Are you perhaps... Ministress Armilla?",
  ui_story_5070_50700402_6_dialog_content = "Wait, you know her?",
  ui_story_5070_50700402_7_dialog_content = "We've never met, but I've heard much about her.",
  ui_story_5070_50700402_8_dialog_content = "A genius Ye Kingdom artisan belonging to the Qianyun sect.",
  ui_story_5070_50700402_9_dialog_content = "At the age of fifteen, she shocked the entire nation with her realistic, music-playing mechanical puppets.",
  ui_story_5070_50700402_10_dialog_content = "Shortly afterward, she became a strategic advisor for the king of Ye.",
  ui_story_5070_50700402_11_dialog_content = "My understanding is that the titles granted by the Ye Kingdom are based on famous inventions. For you to be given the title of \"Armilla\" means that your kingdom must truly recognize your ingenuity.",
  ui_story_5070_50700402_12_dialog_content = "Oh, I wouldn't go that far. Besides, I retired from the political scene long ago; I'm just a simple artisan now.",
  ui_story_5070_50700402_13_dialog_content = "But you? A master swordsman with red hair and a knowledge of Longzhou's politics...",
  ui_story_5070_50700402_14_dialog_content = "You must be Mr. Zhong Xu, the esteemed associate of the Lin Family who is known and respected by every guild in the Ji Kingdom.",
  ui_story_5070_50700402_15_dialog_content = "Your words are kinder than I deserve, my lady.",
  ui_story_5070_50700402_16_dialog_content = "Liqing.",
  ui_story_5070_50700402_17_dialog_content = "This young woman is not our enemy.",
  ui_story_5070_50700402_18_dialog_content = "Not necessarily.",
  ui_story_5070_50700402_19_dialog_content = "Hey! What's that supposed to mean? Don't you have any manners?!",
  ui_story_5070_50700402_20_dialog_content = "Hush, little one. The adults are talking right now.",
  ui_story_5070_50700402_21_dialog_content = "I told you I'm not a child!",
  ui_story_5070_50700402_22_dialog_content = "Half a year ago, the Ji Kingdom was tracking down a shipment of smuggled goods.",
  ui_story_5070_50700402_23_dialog_content = "After a thorough investigation, they discovered that the Lin Family's merchant ships were the only ones with access to their departure records.",
  ui_story_5070_50700402_24_dialog_content = "The Lin Guild was also unable to provide a valid explanation on the matter.",
  ui_story_5070_50700402_25_dialog_content = "So what? You think you can blame them based purely on coincidence?",
  ui_story_5070_50700402_26_dialog_content = "You have a point.",
  ui_story_5070_50700402_27_dialog_content = "Although the only suspects in the case are the Lin Family, many people still find the matter highly questionable.",
  ui_story_5070_50700402_28_dialog_content = "But after searching the nearby warehouses just now...",
  ui_story_5070_50700402_29_dialog_content = "I found a large quantity of Ye Kingdom clockwork beasts whose parts were most likely smuggled out of the country as well.",
  ui_story_5070_50700402_30_dialog_content = "I also found a fair amount of cargo bearing the Lin Guild's mark mixed in with the clockwork beasts.",
  ui_story_5070_50700402_31_dialog_content = "As a distinguished associate of the Lin Family, surely you must know something about this?",
  ui_story_5070_50700402_32_dialog_content = "Would you be so kind as to explain?",
  ui_story_5070_50700402_33_dialog_content = "...",
  ui_story_5070_50700402_34_dialog_content = "It's true. A Lin Family's merchant ship did indeed transport smuggled goods.",
  ui_story_5070_50700402_35_dialog_content = "(How could this Telema person be so stubborn? No matter how hard Dantang tries, she doesn't seem to be getting anywhere.)",
  ui_story_5070_50700402_36_dialog_content = "(What's gonna happen to her mission if this keeps up?)",
  ui_story_5070_50700402_37_dialog_content = "... I understand.",
  ui_story_5070_50700402_38_dialog_content = "I will respect and abide by your decision, Telema of Lumopolis.",
  ui_story_5070_50700402_39_dialog_content = "I'm glad you finally see things my way.",
  ui_story_5070_50700402_40_dialog_content = "I always knew that a beautiful and noble lady such as yourself could sympathize with the plights of others.",
  ui_story_5070_50700402_41_dialog_content = "Similarly, I must ask that you also understand my own situation, Telema.",
  ui_story_5070_50700402_42_dialog_content = "Huh?",
  ui_story_5070_50700402_43_dialog_content = "PlayerName.",
  ui_story_5070_50700402_44_dialog_content = "Would you be willing to take Telema's place as the emissary of Astra and return to Longzhou with me?",
  ui_story_5070_50700402_45_dialog_content = "... Me?!?",
  ui_story_5070_50700501_1_dialog_content = "N-No way! How could I possibly serve as an emissary?!",
  ui_story_5070_50700501_2_dialog_content = "And why not?",
  ui_story_5070_50700501_3_dialog_content = "Well, for starters, I don't represent a major power like Lumopolis or the Illumina Federation.",
  ui_story_5070_50700501_4_dialog_content = "Yes, but as a neutral party, don't you think you're in the best position to represent Astra's interests?",
  ui_story_5070_50700501_5_dialog_content = "Not only that, your experiences in this land are as vast as the network of allies you've built over time.",
  ui_story_5070_50700501_6_dialog_content = "You are more than knowledgeable about Astra's affairs, as well as its strategies for fending off Eclipsites.",
  ui_story_5070_50700501_7_dialog_content = "Doesn't that align with our goal of establishing a bridge of communication between our two continents?",
  ui_story_5070_50700501_8_dialog_content = "But this is...",
  ui_story_5070_50700501_9_dialog_content = "I agree!!",
  ui_story_5070_50700501_10_dialog_content = "PlayerName is famous in Astra! I've heard nothing but the highest praise for him, even before we had the chance to meet!",
  ui_story_5070_50700501_11_dialog_content = "As the official representative of Lumopolis, I am willing to place the responsibilities of this diplomatic mission to Longzhou in your hands!",
  ui_story_5070_50700501_12_dialog_content = "W-Wait... I still need to think about it!",
  ui_story_5070_50700501_13_dialog_content = "(Lumopolis, huh... Carleen did say she's always supported this exchange. I'm sure she'd be disappointed if it fell through.)",
  ui_story_5070_50700501_14_dialog_content = "(Dantang and her allies have been dealing with all kinds of trouble ever since they arrived in Astra too.)",
  ui_story_5070_50700501_15_dialog_content = "(Many people are placing their hopes on this mission, since it involves the future of two continents. If I'm the only person for the job right now, then...)",
  ui_story_5070_50700501_16_dialog_content = "I'll do my best.",
  ui_story_5070_50700501_17_dialog_content = "PlayerName... I'm so happy to hear that!!!",
  ui_story_5070_50700501_18_dialog_content = "Are you sure of this?",
  ui_story_5070_50700501_19_dialog_content = "Captain Yuebai? So you heard everything too?",
  ui_story_5070_50700501_20_dialog_content = "You can just call me Yuebai.",
  ui_story_5070_50700501_21_dialog_content = "Since it's already decided, then as captain of the Shadowind...",
  ui_story_5070_50700501_22_dialog_content = "I hereby welcome PlayerName aboard as the emissary of all of Astra.",
  ui_story_5070_50700501_23_dialog_content = "The voyage will be treacherous, so be prepared both physically and psychologically for it.",
  ui_story_5070_50700501_24_dialog_content = "I understand.",
  ui_story_5070_50700501_25_dialog_content = "Wait, Captain Yuebai... I mean Yuebai. Could I bother you for a minute?",
  ui_story_5070_50700501_26_dialog_content = "You see, a friend of mine asked me to ask you about the Lin Family.",
  ui_story_5070_50700501_27_dialog_content = "It's true. A Lin Family's merchant ship did indeed transport smuggled goods.",
  ui_story_5070_50700501_28_dialog_content = "Why are you telling her all of this, Zhong Xu?!",
  ui_story_5070_50700501_29_dialog_content = "She showed up on our doorstep with a bunch of half-baked accusations! Just say a few words and send her on her way!",
  ui_story_5070_50700501_30_dialog_content = "I heard that, you know!",
  ui_story_5070_50700501_31_dialog_content = "But for you to speak about these things so frankly... Don't tell me you intend to fight me, Mr. Zhong Xu?",
  ui_story_5070_50700501_32_dialog_content = "I have no intention of doing that.",
  ui_story_5070_50700501_33_dialog_content = "But if a single sentence was enough to make you waver, Ministress Armilla...",
  ui_story_5070_50700501_34_dialog_content = "Then perhaps you don't have the patience to hear the rest of the truth.",
  ui_story_5070_50700501_35_dialog_content = "Oh?",
  ui_story_5070_50700501_36_dialog_content = "So you're only willing to share your knowledge with those who are willing to listen? Is that it?",
  ui_story_5070_50700501_37_dialog_content = "Not at all, my lady.",
  ui_story_5070_50700501_38_dialog_content = "I simply mean that I am in poor health and get tired very easily. For this reason, I thought it best to give you a concise answer just now.",
  ui_story_5070_50700501_39_dialog_content = "I see. Then, by all means, give me the long version of the story.",
  ui_story_5070_50700501_40_dialog_content = "After all, it'd be rude of me not to listen when you're being so honest with me, Mr. Zhong Xu.",
  ui_story_5070_50700501_41_dialog_content = "Heh, so you are willing to listen to others every now and then.",
  ui_story_5070_50700501_42_dialog_content = "That's because I'm an adult, little one.",
  ui_story_5070_50700501_43_dialog_content = "Stop calling me that! Get it through your head already!",
  ui_story_5070_50700501_44_dialog_content = "So what exactly did the Lin Family's merchant ship encounter at sea half a year ago?",
  ui_story_5070_50700501_45_dialog_content = "Pirates.",
  ui_story_5070_50700501_46_dialog_content = "As usual, The Lin Family's ships set sail from the Ji Kingdom at the start of the quarter.",
  ui_story_5070_50700501_47_dialog_content = "But as they entered Astra's waters, the crew discovered a shipment of unmarked and unregistered goods hidden in the cargo hold.",
  ui_story_5070_50700501_48_dialog_content = "Soon afterward, a number of pirates were discovered among the ship's passengers.",
  ui_story_5070_50700501_49_dialog_content = "So, these were using the Lin Family's ship to smuggle contraband?",
  ui_story_5070_50700501_50_dialog_content = "Precisely.",
  ui_story_5070_50700501_51_dialog_content = "But their scheme was exposed along the way, so the pirates resorted to violence in order to hijack the merchant ship.",
  ui_story_5070_50700501_52_dialog_content = "In the end, the only two survivors were Liqing, who was serving as the ship's doctor at the time, and myself.",
  ui_story_5070_50700501_53_dialog_content = "Zhong Xu fell overboard after getting seriously wounded too. He almost didn't make it.",
  ui_story_5070_50700501_54_dialog_content = "It took all my strength just to keep him alive, so I wasn't able to save his legs. That's how he ended up like this.",
  ui_story_5070_50700501_55_dialog_content = "You have no reason to blame yourself, Liqing. I'm already eternally grateful to you for saving my life.",
  ui_story_5070_50700501_56_dialog_content = "If you're really that grateful, then you should listen to me and rest more.",
  ui_story_5070_50700501_57_dialog_content = "Any time our unwanted guests show up at our doorstep, you always rush out to fight them without worrying about yourself—",
  ui_story_5070_50700501_58_dialog_content = "Unwanted guests?",
  ui_story_5070_50700501_59_dialog_content = "Graaah—!",
  ui_story_5070_50700501_60_dialog_content = "Speak of the devil, here they are again!",
  ui_story_5070_50700501_61_dialog_content = "They always pop out the second we stop paying attention. It makes eating and sleeping a real pain!",
  ui_story_5070_50700501_62_dialog_content = "Full—",
  ui_story_5070_50700501_63_dialog_content = "To Ashes!",
  ui_story_5070_50700501_64_dialog_content = "...",
  ui_story_5070_50700501_65_dialog_content = "What did I just say, Zhong Xu?! This is exactly why you're taking so long to recover!",
  ui_story_5070_50700501_66_dialog_content = "What remains of my life is no longer important.",
  ui_story_5070_50700501_67_dialog_content = "But the Lin Guildmaster...",
  ui_story_5070_50700501_68_dialog_content = "I made a promise to him back then. How could I possibly leave him die prison when he was wrongfully arrested?",
  ui_story_5070_50700501_69_dialog_content = "That's why I cannot die. Not yet.",
  ui_story_5070_50700501_70_dialog_content = "I swear I will return to Longzhou and clear his good name before I draw my final breath.",
  ui_story_5070_50700501_71_dialog_content = "No wonder you two were so cautious of me when I first arrived.",
  ui_story_5070_50700501_72_dialog_content = "Have you been fighting off these clockwork beasts all along?",
  ui_story_5070_50700501_73_dialog_content = "There's been no shortage of western mercenaries after us either!",
  ui_story_5070_50700501_74_dialog_content = "It appears those pirates have the backing of even greater powers in the world.",
  ui_story_5070_50700501_75_dialog_content = "With so many assassins constantly hunting us down, I fear these powers wish to see us buried in these foreign lands, along with the truth.",
  ui_story_5070_50700501_76_dialog_content = "If they succeed, the Lin Family will never be exonerated of these false crimes.",
  ui_story_5070_50700501_77_dialog_content = "Even at a time like this, all you can think about is the Lin Family... I really don't know if that's a good or bad thing, Zhong Xu.",
  ui_story_5070_50700501_78_dialog_content = "Graaah—!",
  ui_story_5070_50700501_79_dialog_content = "Argh! Not again!",
  ui_story_5070_50700501_80_dialog_content = "Please forgive my rudeness just now, Ministress Armilla. I was unaware of your true identity.",
  ui_story_5070_50700501_81_dialog_content = "I do not wish for you to become implicated in our problems, so please escape while you can.",
  ui_story_5070_50700501_82_dialog_content = "You wouldn't worry about implicating me.",
  ui_story_5070_50700501_83_dialog_content = "If anything, I'm the perpetrator here.",
  ui_story_5070_50700501_84_dialog_content = "I was the one who designed these clockwork beasts...",
  ui_story_5070_50700501_85_dialog_content = "But they were never meant to be exploited and turned into weapons by villains cowering in the shadows!",
  ui_story_5070_50700501_86_dialog_content = "At first I was worried that I wouldn't find any more clues, but the fools have delivered them right into my hands.",
  ui_story_5070_50700501_87_dialog_content = "I should be thanking the two of you, in all honesty.",
  ui_story_5070_50700501_88_dialog_content = "You're in luck, Mr. Zhong Xu. We appear to have a common enemy.",
  ui_story_5070_50700501_89_dialog_content = "... So even after all of that, we were never enemies to begin with?!",
  ui_story_5070_50700501_90_dialog_content = "Our enemies probably laughed their heads off, watching us bicker back and forth all day!",
  ui_story_5070_50700501_91_dialog_content = "Don't be upset, little one. After we take care of these bad guys, I'll make you all sorts of fun toys to play with.",
  ui_story_5070_50700501_92_dialog_content = "How does a nice, shiny ball sound?",
  ui_story_5070_50700501_93_dialog_content = "I can also repair Mr. Zhong Xu's wheelchair and add some new functions to it, if you'd like?",
  ui_story_5070_50700501_94_dialog_content = "Your goodwill is most appreciated.",
  ui_story_5070_50700501_95_dialog_content = "But this wheelchair is just my means of conveyance. It doesn't require any unnecessary modifications.",
  ui_story_5070_50700501_96_dialog_content = "Hahaha! You may not be an artisan, Mr. Zhong Xu, but you definitely understand the true meaning of our craft.",
  ui_story_5070_50700501_97_dialog_content = "And that makes you a hundred times more powerful than the cowards pulling the strings of this entire conspiracy.",
  ui_story_5070_50700502_1_dialog_content = "And that... is what happened to the Lin Family.",
  ui_story_5070_50700502_2_dialog_content = "I heard rumors about the Lin Guild's involvement in a smuggling incident six months ago, as well as the damage it brought to their name. However, this is the first time I've been told the details of the matter.",
  ui_story_5070_50700502_3_dialog_content = "If what you say is true, the verdict in this case seems quite arbitrary.",
  ui_story_5070_50700502_4_dialog_content = "There is no conclusive proof of the Lin Family smuggling contraband, but everything else seems to indicate as much.",
  ui_story_5070_50700502_5_dialog_content = "This undoubtedly puts the Lin Family at a disadvantage. All they can do is bear the shame of this crime.",
  ui_story_5070_50700502_6_dialog_content = "This also explains why the Lin Family was so adamant about braving the seas in spite of losing their armillary sphere.",
  ui_story_5070_50700502_7_dialog_content = "They're desperate for an opportunity to re-establish their trade routes and revitalize their guild.",
  ui_story_5070_50700502_8_dialog_content = "*Sigh* The Shadowind's crew has been beset by problems from the very beginning.",
  ui_story_5070_50700502_9_dialog_content = "Which is why they're so eager to set sail and return to Longzhou.",
  ui_story_5070_50700502_10_dialog_content = "PlayerName.",
  ui_story_5070_50700502_11_dialog_content = "What is it, Dantang? And why do you look so serious?",
  ui_story_5070_50700502_12_dialog_content = "The sea is an unpredictable place. Since time immemorial, countless ships have failed to return safely from voyages as long as this.",
  ui_story_5070_50700502_13_dialog_content = "Aside from ever-shifting sea routes and enemy ambushes, the journey ahead will be full of other unseen dangers.",
  ui_story_5070_50700502_14_dialog_content = "If you are willing to board the Shadowind, you must also be willing to venture into the unknown.",
  ui_story_5070_50700502_15_dialog_content = "Yuebai is duty-bound to the Lin Guild's restoration, and I have my own responsibilities, which I cannot abandon.",
  ui_story_5070_50700502_16_dialog_content = "We all have our reasons for braving the sea, and have accepted the consequences of doing so.",
  ui_story_5070_50700502_17_dialog_content = "But you are different, PlayerName.",
  ui_story_5070_50700502_18_dialog_content = "... As Princess Zhuohua, dragging you into our problems was the only answer I could come up with at the time.",
  ui_story_5070_50700502_19_dialog_content = "But as your friend, Dantang... I worry about your safety.",
  ui_story_5070_50700502_20_dialog_content = "I would completely understand if you chose to refuse my offer.",
  ui_story_5070_50700502_21_dialog_content = "Honestly, I don't know what I was expecting you to say.",
  ui_story_5070_50700502_22_dialog_content = "Huh?",
  ui_story_5070_50700502_23_dialog_content = "You say that you \"dragged\" me into your problems.",
  ui_story_5070_50700502_24_dialog_content = "But whether I'm Astra's envoy, or the last of the Caelestites, or even just plain old me.",
  ui_story_5070_50700502_25_dialog_content = "I always take these situations into careful consideration before making any decisions.",
  ui_story_5070_50700502_26_dialog_content = "And as your friend, I naturally want to help you out too.",
  ui_story_5070_50700502_27_dialog_content = "PlayerName... If that's the case, then I swear I'll do everything in my power to protect you on this journey.",
  ui_story_5070_50700502_28_dialog_content = "I just pray that we don't face too many challenges along the way...",
  ui_story_5070_50700502_29_dialog_content = "Oh? Why hasn't the ship left yet? And why does everyone look like they're about to cry?",
  ui_story_5070_50700502_30_dialog_content = "...",
  ui_story_5070_50700502_31_dialog_content = "Just relax, everyone! I happened to find a grizzled combat veteran and a legendary doctor to bring on the trip.",
  ui_story_5070_50700502_32_dialog_content = "And if worse comes to worst, I'll be around too!",
  ui_story_5070_50700502_33_dialog_content = "I may not be an advisor to the king of Ye anymore, but I would brave a mountain of blades and a sea of flames if the princess ordered it.",
  ui_story_5070_50700502_34_dialog_content = "Your Highness, Lady Xuan Ji has returned!",
  ui_story_5070_50700502_35_dialog_content = "Yes, I could tell from all the noise that it was her.",
  ui_story_5070_50700502_36_dialog_content = "Your words are as eccentric as ever, Ministress Armilla.",
  ui_story_5070_50700502_37_dialog_content = "Be careful, or I may just place you in that kind of dangerous dilemma.",
  ui_story_5070_50700502_38_dialog_content = "Hahahaha! Alright, that's enough joking for now.",
  ui_story_5070_50700502_39_dialog_content = "I heard the Shadowind was attacked earlier, so I need to inspect its hull one more time.",
  ui_story_5070_50700502_40_dialog_content = "I never thought that my fire crabs would be used to attack a ship someday.",
  ui_story_5070_50700502_41_dialog_content = "Looks like I'll have to reinforce or modify the power supply and navigation systems as well.",
  ui_story_5070_50700502_42_dialog_content = "Don't worry, I'll do my best to make this ship as safe as possible before we head out to sea!",
  ui_story_5070_50700601_1_dialog_content = "(Dear Vice and Carleen.)",
  ui_story_5070_50700601_2_dialog_content = "(Sorry for replying so late. In the blink of an eye, our day of departure finally arrived.)",
  ui_story_5070_50700601_3_dialog_content = "(We're in the middle of making our final preparations for the voyage, so everyone's been really busy lately.)",
  ui_story_5070_50700601_4_dialog_content = "Shipwright Li! Have your team apply a fire-resistant coating to the critical sections of the hull!",
  ui_story_5070_50700601_5_dialog_content = "We need to be prepared for unexpected fires as well as fire crab attacks!",
  ui_story_5070_50700601_6_dialog_content = "I'm going to inspect the ship for any signs of leakage.",
  ui_story_5070_50700601_7_dialog_content = "Also, does anyone know where the captain is? I need to convince her to buy a few more energy storage devices before we leave Astra.",
  ui_story_5070_50700601_8_dialog_content = "Anything can happen out at sea, and having spare energy reserves will help us stay prepared.",
  ui_story_5070_50700601_9_dialog_content = "Mr. Zhong Xu?",
  ui_story_5070_50700601_10_dialog_content = "Forgive me for not speaking with you sooner. The last few days have been very busy...",
  ui_story_5070_50700601_11_dialog_content = "Thank you for telling me the truth about the smuggling incident. With this information, the Lin Family's good name can finally be restored.",
  ui_story_5070_50700601_12_dialog_content = "I'm certain that the Lin Guildmaster will be all the more emboldened by your safe return as well. We should have no trouble overcoming these obstacles by then.",
  ui_story_5070_50700601_13_dialog_content = "I'm simply doing my duty... After all, I was the one who failed to protect him.",
  ui_story_5070_50700601_14_dialog_content = "Still, there's no telling when the pirates will strike next.",
  ui_story_5070_50700601_15_dialog_content = "During our encounter six months ago, I was able to roughly discern their method of attack.",
  ui_story_5070_50700601_16_dialog_content = "We can use this information to formulate our countermeasures.",
  ui_story_5070_50700601_17_dialog_content = "Sandalwood, powdergrass, mint, arrowroot...",
  ui_story_5070_50700601_18_dialog_content = "Do you have these herbs in stock? If so, I'll take everything you have!",
  ui_story_5070_50700601_19_dialog_content = "That's quite a big order, young man.",
  ui_story_5070_50700601_20_dialog_content = "Hey, I didn't choose to be responsible for an entire ship's health.",
  ui_story_5070_50700601_21_dialog_content = "I need to stock up on anything that can be used to treat things like chills and seasickness. The more, the better!",
  ui_story_5070_50700601_22_dialog_content = "They're all busy doing who-knows-what, so someone has to make sure we have ample medical supplies for the trip, right?",
  ui_story_5070_50700601_23_dialog_content = "Now I just need to buy enough food to keep everyone in good health while we're out at sea!",
  ui_story_5070_50700601_24_dialog_content = "Have you finished writing your farewell letters yet, Jiu?",
  ui_story_5070_50700601_25_dialog_content = "Yes, Your Highness. Truth be told, I don't need to say goodbye to very many people.",
  ui_story_5070_50700601_26_dialog_content = "But do you really need to send this many letters?",
  ui_story_5070_50700601_27_dialog_content = "We made plenty of friends and met many important people during our time here, after all.",
  ui_story_5070_50700601_28_dialog_content = "We must maintain our good relations if we are to work together in the future.",
  ui_story_5070_50700601_29_dialog_content = "This reminds me that I still need to write a letter to the Twin Pavilions Bay Guild Association.",
  ui_story_5070_50700601_30_dialog_content = "Pirate accomplices have turned up in the city, and they need to be rounded up as soon as possible.",
  ui_story_5070_50700601_31_dialog_content = "(Even I had to make a couple of trips to Umbraton to help everyone buy things that can only be found in Astra.)",
  ui_story_5070_50700601_32_dialog_content = "(Honestly, it made me feel a lot more like a real emissary of Astra.)",
  ui_story_5070_50700601_33_dialog_content = "(Once I mail this letter, the Shadowind will set sail soon afterward.)",
  ui_story_5070_50700601_34_dialog_content = "(I hope I can live up to everyone's expectations and complete my mission without too many problems.)",
  ui_story_5070_50700601_35_dialog_content = "(When I come back, I'll be sure to bring lots of stories from Longzhou for everyone to hear!)",
  ui_story_5070_50700601_36_dialog_content = "Well if it isn't PlayerName!",
  ui_story_5070_50700601_37_dialog_content = "Hey, you're that fortune-teller from before!",
  ui_story_5070_50700601_38_dialog_content = "Not another word, my friend! My powers of divination tell me that you just mailed a letter. Is that correct?",
  ui_story_5070_50700601_39_dialog_content = "...",
  ui_story_5070_50700601_40_dialog_content = "What are you talking about? You clearly just saw me walk out of the Courier Union.",
  ui_story_5070_50700601_41_dialog_content = "Heheh, I'm only joking.",
  ui_story_5070_50700601_42_dialog_content = "Much like yourself, I'm also a passenger aboard the Shadowind.",
  ui_story_5070_50700601_43_dialog_content = "Would you care to return to the ship with me?",
  ui_story_5070_50700601_44_dialog_content = "I guess not. Were you sending out a letter too?",
  ui_story_5070_50700601_45_dialog_content = "It's best if we don't discuss that.",
  ui_story_5070_50700601_46_dialog_content = "I wanted to savor one last meal in Astra before returning home, but I haven't been too lucky today.",
  ui_story_5070_50700601_47_dialog_content = "Despite roaming around town for half a day, I haven't had the fortune of running into any wealthy people.",
  ui_story_5070_50700601_48_dialog_content = "A shame, really.",
  ui_story_5070_50700601_49_dialog_content = "What do rich people have to do with you eating a meal?",
  ui_story_5070_50700601_50_dialog_content = "You may not be aware of this, but despite my homely appearance...",
  ui_story_5070_50700601_51_dialog_content = "I'm actually even poorer than I look. In fact, I don't have a single Nightium to my name!",
  ui_story_5070_50700601_52_dialog_content = "And you... chose to travel the world in spite of that?",
  ui_story_5070_50700601_53_dialog_content = "Well I am quite different from the other passengers. I don't have any special motives to speak of, per se.",
  ui_story_5070_50700601_54_dialog_content = "My curiosity to see distant lands is what compels me to travel. For me, the journey is what I enjoy the most.",
  ui_story_5070_50700601_55_dialog_content = "It makes no difference if I'm traveling to another continent or to the other side of a pond.",
  ui_story_5070_50700601_56_dialog_content = "... Okay then.",
  ui_story_5070_50700601_57_dialog_content = "(Even though I barely understood anything he said, it somehow makes sense.)",
  ui_story_5070_50700601_58_dialog_content = "You find me a tad bit verbose, don't you, my friend?",
  ui_story_5070_50700601_59_dialog_content = "Then why don't I give you an honest-to-goodness divination?",
  ui_story_5070_50700601_60_dialog_content = "My Heavenly Hexagram Divination includes rats, oxes, tigers, rabbits, and every other zodiac animal, and divides them into yin and yang.",
  ui_story_5070_50700601_61_dialog_content = "With it, I can discern the very secrets of the heavens and predict the future. I can't guarantee you'll have another opportunity like this!",
  ui_story_5070_50700601_62_dialog_content = "Rats and oxes? But aren't those just animals? What can they possibly show you?",
  ui_story_5070_50700601_63_dialog_content = "A wealth of knowledge, my friend.",
  ui_story_5070_50700601_64_dialog_content = "Let us take the Shadowind as an example. Come, we can walk as we talk.",
  ui_story_5070_50700601_65_dialog_content = "Are you aware that the twelve animals of the zodiac are aboard the ship?",
  ui_story_5070_50700601_66_dialog_content = "Well, rats on a ship aren't anything new, but I haven't seen any oxes yet.",
  ui_story_5070_50700601_67_dialog_content = "The people of Longzhou are very particular about imagery. In fact, certain things are named after the images they resemble.",
  ui_story_5070_50700601_68_dialog_content = "See that wedge used to stabilize the ship's mast? In our lands, it's known as a \"rat bridge.\"",
  ui_story_5070_50700601_69_dialog_content = "And the guard rails along the edges of the deck? Those are called \"ox fences.\"",
  ui_story_5070_50700601_70_dialog_content = "The boards on the deck are called \"horse faces,\" while the frame of the ship is referred to as the \"dragon's skeleton.\" Need I explain more?",
  ui_story_5070_50700601_71_dialog_content = "I didn't realize they had such imaginative names.",
  ui_story_5070_50700601_72_dialog_content = "Indeed, and just like this ship, my hexagrams echo all of existence, allowing me to see the future.",
  ui_story_5070_50700601_73_dialog_content = "Then can you see what's going to happen to this ship during our voyage?",
  ui_story_5070_50700601_74_dialog_content = "Again... It's best if you don't ask. Just know that I also made a prediction when the Shadowind was attacked earlier.",
  ui_story_5070_50700601_75_dialog_content = "The result was the yin ox and the yin horse.",
  ui_story_5070_50700601_X75_dialog_content = "\"The dead ox does not move, and the dead horse does not neigh.\" At first, I took it to mean that the ship would not be able to leave port...",
  ui_story_5070_50700601_76_dialog_content = "But the Shadowind is about to depart!",
  ui_story_5070_50700601_77_dialog_content = "Indeed, this means my prediction requires further interpretation. Perhaps I can draw more inspiration from the horse faces and ox fences aboard the ship?",
  ui_story_5070_50700601_78_dialog_content = "It's wise not to listen to the ramblings of a liar, PlayerName.",
  ui_story_5070_50700601_79_dialog_content = "Come now, Your Highness. My art is but a means for me to feed myself, nothing more.",
  ui_story_5070_50700601_80_dialog_content = "Pay him no heed, PlayerName. Most of the passengers are already on the ship, so please climb aboard.",
  ui_story_5070_50700601_81_dialog_content = "... Allow me to go over the passenger list one last time.",
  ui_story_5070_50700601_82_dialog_content = "Mr. Zhong Xu, Doctor Liqing, Princess Dantang, Miss Jiu, and PlayerName.",
  ui_story_5070_50700601_83_dialog_content = "Li, Sun, and Lady Xuan Ji will also be joining our voyage to Longzhou as the Shadowind's technicians.",
  ui_story_5070_50700601_84_dialog_content = "Everyone is now present and accounted for.",
  ui_story_5070_50700601_85_dialog_content = "...",
  ui_story_5070_50700601_86_dialog_content = "As captain of the ship, I should be the last person adding to the worries of its passengers.",
  ui_story_5070_50700601_87_dialog_content = "But given the special circumstances of our voyage, I feel I must make something very clear to everyone.",
  ui_story_5070_50700601_88_dialog_content = "Without our armillary sphere, the Shadowind's location can't be ascertained while sailing the high seas.",
  ui_story_5070_50700601_89_dialog_content = "It falls to us to determine the ship's course.",
  ui_story_5070_50700601_90_dialog_content = "Sudden storms, vicious Eclipsites, and even unseen enemies are also to be expected out there.",
  ui_story_5070_50700601_91_dialog_content = "The dangers lying ahead will be far greater than anything we've faced in previous voyages.",
  ui_story_5070_50700601_92_dialog_content = "If anyone wishes to leave the ship, now is the time to do so.",
  ui_story_5070_50700601_93_dialog_content = "(As expected, no one is moving a muscle. They're all determined to make the trip back.)",
  ui_story_5070_50700601_94_dialog_content = "Since all of you have chosen to place your trust in the Shadowind, then as captain of the ship, I swear to lead us safely to Longzhou's shores.",
  ui_story_5070_50700601_95_dialog_content = "The Shadowind sets sail now!",
  ui_story_5070_50700701_1_dialog_content = "<color=#e8d9bb>Splash... Splash...</color>",
  ui_story_5070_50700701_2_dialog_content = "(It's been a few days since we set out. This is the first time I've left Astra by ship.)",
  ui_story_5070_50700701_3_dialog_content = "(The blue sky, rolling waves, refreshing sea breeze, and unknown destination... Plus, a little loneliness.)",
  ui_story_5070_50700701_4_dialog_content = "You're so fixated. What's on your mind?",
  ui_story_5070_50700701_5_dialog_content = "Oh, Xuan Ji!",
  ui_story_5070_50700701_6_dialog_content = "I was just thinking that the feeling of crossing the ocean by ship is totally different from riding a Colossus.",
  ui_story_5070_50700701_7_dialog_content = "Oh? How is it on the Colossus?",
  ui_story_5070_50700701_8_dialog_content = "It's rare that you would bring up the topic. Generally speaking, Colossus is a machine, right?",
  ui_story_5070_50700701_9_dialog_content = "Isn't that a little broad?",
  ui_story_5070_50700701_10_dialog_content = "That's not the point.",
  ui_story_5070_50700701_11_dialog_content = "The point is, you can really control that larger-than-Shadowind behemoth by yourself?",
  ui_story_5070_50700701_12_dialog_content = "How fast is it? What's the fuel consumption? How do the materials handle changing seasons?",
  ui_story_5070_50700701_13_dialog_content = "As a flying machine, other than propulsion, its shape also affects aerodynamics and lifts...",
  ui_story_5070_50700701_14_dialog_content = "You never quite explained those to me before.",
  ui_story_5070_50700701_15_dialog_content = "W-Wait a second... Did I just open a can of worms...?",
  ui_story_5070_50700701_16_dialog_content = "Well, if it's confidential, we should keep it that way!",
  ui_story_5070_50700701_17_dialog_content = "Not confidential. It's just that even I can't offer an appropriate answer to some questions.",
  ui_story_5070_50700701_18_dialog_content = "Think about it! The Shadowind's taffrail, rudder, mast...",
  ui_story_5070_50700701_19_dialog_content = "Yuebai and that lot have to handle everything on the ship manually.",
  ui_story_5070_50700701_20_dialog_content = "If there is any wind speed or direction change, they have to decide how to modify the ship immediately.",
  ui_story_5070_50700701_21_dialog_content = "But the information in its database allows Soroz to handle all these kinds of things.",
  ui_story_5070_50700701_22_dialog_content = "It's only at critical moments that I need to guide it with words or melodies.",
  ui_story_5070_50700701_23_dialog_content = "So it goes beyond simple control, but letting it perform logical routines and just execute commands.",
  ui_story_5070_50700701_24_dialog_content = "That's like a myth come true.",
  ui_story_5070_50700701_25_dialog_content = "Myth? Longzhou?",
  ui_story_5070_50700701_26_dialog_content = "Correct. Ancient history books talked about djinns big enough to block out the sun.",
  ui_story_5070_50700701_27_dialog_content = "Operated by people called \"Djinn Attendants\" to traverse the land and sea in conquests.",
  ui_story_5070_50700701_28_dialog_content = "Wow, that's incredible... Soroz can't block out the sun.",
  ui_story_5070_50700701_29_dialog_content = "However high you fly, the sky and moon always seem out of reach...",
  ui_story_5070_50700701_30_dialog_content = "I'm not sure about that.",
  ui_story_5070_50700701_31_dialog_content = "Huh?",
  ui_story_5070_50700701_32_dialog_content = "I came on deck to measure the sun's altitude.",
  ui_story_5070_50700701_33_dialog_content = "That's not the name for something, is it? The sun above us?",
  ui_story_5070_50700701_34_dialog_content = "There's an ancient school of astrology in Longzhou.",
  ui_story_5070_50700701_35_dialog_content = "All you need is an astrolabe to figure out the distance between the sun, the moon, or even any two stars.",
  ui_story_5070_50700701_36_dialog_content = "Given that we can calculate the altitude and trajectory...",
  ui_story_5070_50700701_37_dialog_content = "It won't be hard to tweak the frame for your Colossus to block out the sun!",
  ui_story_5070_50700701_38_dialog_content = "It's obviously hyperbole, but coming from you, it didn't sound like a joke at all...",
  ui_story_5070_50700701_39_dialog_content = "Then I shall be grateful for your trust in me then.",
  ui_story_5070_50700701_40_dialog_content = "But I do know the principle of slow and steady wins the race, building a gadget one piece at a time.",
  ui_story_5070_50700701_41_dialog_content = "Although we can't get there right now...",
  ui_story_5070_50700701_42_dialog_content = "But we can still do a lot knowing the sun's position, angle, and other data.",
  ui_story_5070_50700701_43_dialog_content = "Such as complementing Lin's charts to figure out Shadowind's current coordinates.",
  ui_story_5070_50700701_44_dialog_content = "As long as you're always aware of your position, you'll never get lost at sea!",
  ui_story_5070_50700701_45_dialog_content = "Easier said than done. The sea is too unpredictable for artificial estimation to remain consistent and accurate.",
  ui_story_5070_50700701_46_dialog_content = "That's why the armillary sphere, capable of showing constellations and pinpoint locations, is cherished as Lin's treasure.",
  ui_story_5070_50700701_47_dialog_content = "It makes it impossible to even deliberately steer a ship off-course with a competent astronomer aboard.",
  ui_story_5070_50700701_48_dialog_content = "Too bad though...",
  ui_story_5070_50700701_49_dialog_content = "Armillary sphere... I remember it was on that Lin Family ship which was hijacked by pirates, vanishing along with the ship.",
  ui_story_5070_50700701_50_dialog_content = "Yes, that's why I'm filling in.",
  ui_story_5070_50700701_51_dialog_content = "It's all been done by gadgets in the past, so how shocking it is for an artisan to stand in for the machine.",
  ui_story_5070_50700701_52_dialog_content = "But in this way, Xuan Ji could also be considered the Shadowind's navigator.",
  ui_story_5070_50700701_53_dialog_content = "Only temporarily.",
  ui_story_5070_50700701_54_dialog_content = "Do not sell yourself short, Ministress Armilla.",
  ui_story_5070_50700701_55_dialog_content = "The name Xuan Ji means Armilla, which is another name for the armillary sphere.",
  ui_story_5070_50700701_56_dialog_content = "Armilla is the perfect title for you.",
  ui_story_5070_50700701_57_dialog_content = "It is only proper then, for Xuan Ji to replace the sphere.",
  ui_story_5070_50700701_58_dialog_content = "Am I imagining things? How come it seems to be saying that Xuan Ji wasn't doing a proper job before?",
  ui_story_5070_50700701_59_dialog_content = "A key counselor vacates a vital position without permission, leaving only a letter behind.",
  ui_story_5070_50700701_60_dialog_content = "A prominent renowned artisan forsaking her workshop and plethora of wondrous items, in favor of traveling alone with but a parasol in hand.",
  ui_story_5070_50700701_61_dialog_content = "How would you explain the propriety of that, Ministress Armilla?",
  ui_story_5070_50700701_62_dialog_content = "Your Highness...",
  ui_story_5070_50700701_63_dialog_content = "Your Highness, I'm sure Lady Xuan Ji has her reasons.",
  ui_story_5070_50700701_64_dialog_content = "...",
  ui_story_5070_50700701_65_dialog_content = "Come on, it's not that complicated.",
  ui_story_5070_50700701_66_dialog_content = "A design draft got stolen, and my school just happened to ask me to retrieve an artifact from Astra.",
  ui_story_5070_50700701_67_dialog_content = "It happened so fast, I didn't have time to say the proper goodbye.",
  ui_story_5070_50700701_68_dialog_content = "You're not still mad because I refused to teach you about gadgets, are you, Princess?",
  ui_story_5070_50700701_69_dialog_content = "I was young myself and stupid back then, so why don't you just forgive me, Your Highness?",
  ui_story_5070_50700701_70_dialog_content = "What do you mean by \"back then\"? I don't see that changing...",
  ui_story_5070_50700701_71_dialog_content = "Pff—Ah, sorry.",
  ui_story_5070_50700701_72_dialog_content = "It's rare for Dantang to show this kind of expression. It feels like I'm seeing a different side than usual.",
  ui_story_5070_50700701_73_dialog_content = "Oh my, you as well...",
  ui_story_5070_50700701_74_dialog_content = "Pardon me, please excuse my faux pas.",
  ui_story_5070_50700701_75_dialog_content = "This is not the time or place for me to chat.",
  ui_story_5070_50700701_76_dialog_content = "Ministress Armilla is tasked with navigation duties...",
  ui_story_5070_50700701_77_dialog_content = "But as a guest, you took the initiative to survey the ocean surface, PlayerName.",
  ui_story_5070_50700701_78_dialog_content = "I feel ashamed and guilty enough already, much less interrupting you both.",
  ui_story_5070_50700701_79_dialog_content = "Don't worry. After all, I can sense the approach of Eclipsites, so accepting this task...",
  ui_story_5070_50700701_80_dialog_content = "Wait!",
  ui_story_5070_50700701_81_dialog_content = "You may not wish to intrude, Princess.",
  ui_story_5070_50700701_82_dialog_content = "But certain things out there aren't as polite as you.",
  ui_story_5070_50700701_83_dialog_content = "They're coming to bother PlayerName as we speak.",
  ui_story_5070_50700702_1_dialog_content = "Phew, finally taken care of! I wasn't expecting so many Eclipsites to suddenly pop up.",
  ui_story_5070_50700702_2_dialog_content = "That's a good omen, actually.",
  ui_story_5070_50700702_3_dialog_content = "Active Eclipsites is good news?!",
  ui_story_5070_50700702_4_dialog_content = "That means we're close enough to Astra where Eclipsites roam.",
  ui_story_5070_50700702_5_dialog_content = "Instruments don't lie, but not so with our eyes.",
  ui_story_5070_50700702_6_dialog_content = "According to calculations, we should be near Astra, but it's hard to verify that on the vast sea.",
  ui_story_5070_50700702_7_dialog_content = "Them throwing themselves at us proves we're on the right course.",
  ui_story_5070_50700702_8_dialog_content = "They didn't just sacrifice themselves but offered me proof.",
  ui_story_5070_50700702_9_dialog_content = "I killed them with absolute gratitude in mind.",
  ui_story_5070_50700702_10_dialog_content = "I've got no idea how those Eclipsites will feel when they hear your thoughts...",
  ui_story_5070_50700702_11_dialog_content = "Since the calculations are correct, that means Shadowind is right on course.",
  ui_story_5070_50700702_12_dialog_content = "The wind is pushing the ship from the right angle, so we can save on fuel.",
  ui_story_5070_50700702_13_dialog_content = "Get yourself to work, Sun the Skillful!",
  ui_story_5070_50700702_14_dialog_content = "... Although that's what Lady Xuan Ji said, we should be on our guard since those wicked spirits just won't give up.",
  ui_story_5070_50700702_15_dialog_content = "Your Highness, please stay close to me.",
  ui_story_5070_50700702_16_dialog_content = "Wicked spirits are far more common around Astra than in Longzhou.",
  ui_story_5070_50700702_17_dialog_content = "Wicked spirit? I've heard that before, is that the Longzhou term?",
  ui_story_5070_50700702_18_dialog_content = "Indeed. The creatures called Eclipsites in Astra are called wicked spirits in Longzhou.",
  ui_story_5070_50700702_19_dialog_content = "Mr. Zhong Xu...",
  ui_story_5070_50700702_20_dialog_content = "Is it okay not to rest in the cabin? I just saw Liqing yelling for you to bring medicine.",
  ui_story_5070_50700702_21_dialog_content = "Liqing has always poured his heart into treating his patients.",
  ui_story_5070_50700702_22_dialog_content = "Although I can't walk anymore, I can still use my sword, so I'll be fine.",
  ui_story_5070_50700702_23_dialog_content = "...",
  ui_story_5070_50700702_24_dialog_content = "Zhong Xu... Sir.",
  ui_story_5070_50700702_25_dialog_content = "Princess Dantang, you don't need to be so careful around a vagabond like me. You should all relax a little.",
  ui_story_5070_50700702_26_dialog_content = "Young friend, you should get some rest and leave the lookout duty to me.",
  ui_story_5070_50700702_27_dialog_content = "Eh? Don't worry about me, as these waters are so dangerous, it's always good to have more people on guard.",
  ui_story_5070_50700702_28_dialog_content = "Thank you for your vigilance. Things will get better around the coast of Longzhou.",
  ui_story_5070_50700702_29_dialog_content = "After all, those creatures of darkness are far less active in Longzhou than in Astra.",
  ui_story_5070_50700702_30_dialog_content = "The empire organizes a grand ritual regularly to suppress the wicked spirits. The vassal kingdoms also have their own ways of dealing with them.",
  ui_story_5070_50700702_31_dialog_content = "The wicked spirits usually hide in the mountains, appearing only when their survival is at risk to capture those who are traveling alone.",
  ui_story_5070_50700702_32_dialog_content = "You probably are not aware that the wicked spirits in many places have been restless in recent months.",
  ui_story_5070_50700702_33_dialog_content = "Raids on civilians are occurring with greater frequency. Some of these wicked spirits even infiltrated cities and wreaked havoc.",
  ui_story_5070_50700702_34_dialog_content = "The defenses of the various states responded tirelessly, yet in vain.",
  ui_story_5070_50700702_35_dialog_content = "Now, the people live in fear, not knowing if it is the Fiendling or other elements...",
  ui_story_5070_50700702_36_dialog_content = "You don't like Fiendlings?",
  ui_story_5070_50700702_37_dialog_content = "What? No, I'm just worried, that is all...",
  ui_story_5070_50700702_38_dialog_content = "Hang on, what's a Fiendling?",
  ui_story_5070_50700702_39_dialog_content = "You grew up in Astra, so the name is unfamiliar to you. They are similar to the demi-humans of Astra.",
  ui_story_5070_50700702_40_dialog_content = "The only difference is that demi-humans naturally have animal characteristics.",
  ui_story_5070_50700702_41_dialog_content = "Whereas Fiendlings gained their demi-human forms after learning the Force Arts.",
  ui_story_5070_50700702_42_dialog_content = "Some are disgusted with Fiendlings, but others like them because of their abilities and what they stand for.",
  ui_story_5070_50700702_43_dialog_content = "For example, the seafaring folk are eager to open their doors to any docile fish-shaped Fiendling who appears.",
  ui_story_5070_50700702_44_dialog_content = "... Although I've had many adventures at sea, I don't get along well with fish, so I'll never receive their blessings.",
  ui_story_5070_50700702_45_dialog_content = "Big fish are dangerous, so I hope we won't encounter any.",
  ui_story_5070_50700702_46_dialog_content = "Ah, got it.",
  ui_story_5070_50700702_47_dialog_content = "It's just like in Astra, where some people believe that certain animals bring good luck, while others herald doom.",
  ui_story_5070_50700702_48_dialog_content = "Exactly, but the claim that Fiendlings grant blessings isn't completely unfounded.",
  ui_story_5070_50700702_49_dialog_content = "In the past, some Fiendlings have actively protected the peace in certain areas after perfecting their demi-human forms.",
  ui_story_5070_50700702_50_dialog_content = "Even the imperial court was willing to acknowledge them with imperial edicts and allowed the people to build temples to worship them.",
  ui_story_5070_50700702_51_dialog_content = "Wow, I don't know if I'll have a chance to see these Fiendlings.",
  ui_story_5070_50700702_52_dialog_content = "You know a lot about this, Zhong Xu.",
  ui_story_5070_50700702_53_dialog_content = "Whether it is banishing demons or conducting rituals...",
  ui_story_5070_50700702_54_dialog_content = "No one on board can rival him in terms of knowledge and experience.",
  ui_story_5070_50700702_55_dialog_content = "You can inquire Sir Zhong Xu for anything more you wish to know, PlayerName.",
  ui_story_5070_50700702_56_dialog_content = "I only hope the wicked spirits at sea act slowly as to afford us time to coordinate.",
  ui_story_5070_50700702_57_dialog_content = "(A shame that the Eclipsites weren't that smart, as it took us several more battles before we could finally pass through the area.)",
  ui_story_5070_50700702_58_dialog_content = "(I didn't yet realize.)",
  ui_story_5070_50700702_59_dialog_content = "(But Eclipsites were far from the only dangers in the ocean.)",
  ui_story_5070_50700801_1_dialog_content = "<color=#e8d9bb>Rumble—!</color>",
  ui_story_5070_50700801_2_dialog_content = "<color=#e8d9bb>Splash—!</color>",
  ui_story_5070_50700801_3_dialog_content = "PlayerName! PlayerName! Wake up!",
  ui_story_5070_50700801_4_dialog_content = "Uh... Xuan Ji?",
  ui_story_5070_50700801_5_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5070_50700801_6_dialog_content = "Whoa... What's the matter?",
  ui_story_5070_50700801_7_dialog_content = "The fire is spreading fast! Quick, get those water bags up here!",
  ui_story_5070_50700801_8_dialog_content = "Ugh! Evacuation's not done! Stop shoving! Don't cram into the cabin!",
  ui_story_5070_50700801_9_dialog_content = "Shut it! Protect the fuel vault; if it burns here, we're done for!",
  ui_story_5070_50700801_10_dialog_content = "What a ruckus... What's happening on the ship?",
  ui_story_5070_50700801_11_dialog_content = "We entered the far sea not that long ago, where the weather became evermore unpredictable.",
  ui_story_5070_50700801_12_dialog_content = "Luck's not on our side either. We drew the shortest straw possible.",
  ui_story_5070_50700801_13_dialog_content = "—Thunderstorm.",
  ui_story_5070_50700801_14_dialog_content = "We could handle ordinary storms with no problem, but a bolt of lightning just struck the ship and caused an explosion.",
  ui_story_5070_50700801_15_dialog_content = "Now we have firefighting and evacuations going on.",
  ui_story_5070_50700801_16_dialog_content = "Lightning, explosions?",
  ui_story_5070_50700801_17_dialog_content = "Didn't we check lightning and fire protection before we left? How is this possible?",
  ui_story_5070_50700801_18_dialog_content = "They're only good against natural fires.",
  ui_story_5070_50700801_19_dialog_content = "The problem is, that might not be the only problem we're having.",
  ui_story_5070_50700801_20_dialog_content = "Huh?",
  ui_story_5070_50700801_21_dialog_content = "This is not the time to explain, not that I know exactly what's going on with the lightning and fire anyway.",
  ui_story_5070_50700801_22_dialog_content = "Can I help with anything?",
  ui_story_5070_50700801_23_dialog_content = "Well, the idea was to get you somewhere safe, but now you've become an extra pair of helping hands.",
  ui_story_5070_50700801_24_dialog_content = "So we're putting you to work.",
  ui_story_5070_50700801_25_dialog_content = "Follow me.",
  ui_story_5070_50700801_26_dialog_content = "Why isn't the fire under control yet? What are you all doing?!",
  ui_story_5070_50700801_27_dialog_content = "Try it yourself! We're already risking our lives to stop the fire from spreading outward!",
  ui_story_5070_50700801_28_dialog_content = "Damn it, why is the fire starting from below? The cabin's all wood; it can't hold up!",
  ui_story_5070_50700801_29_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5070_50700801_30_dialog_content = "<color=#e8d9bb>The loud blast is right up ahead this time; the front cabin door bursts open, flames surging in!</color>",
  ui_story_5070_50700801_31_dialog_content = "<color=#e8d9bb>Swoosh—</color>",
  ui_story_5070_50700801_32_dialog_content = "<color=#e8d9bb>The burning wood piece stops just inches before the shipwright, shattering into multiple fragments in the air.</color>",
  ui_story_5070_50700801_33_dialog_content = "Both fire and water are merciless. The last thing you should do when something unexpected happens is to panic.",
  ui_story_5070_50700801_34_dialog_content = "It's okay to be afraid, but don't let your companions pay the price of your fear.",
  ui_story_5070_50700801_35_dialog_content = "Mr. Zhong Xu! T-Thank you, sir, for saving us!",
  ui_story_5070_50700801_36_dialog_content = "Truth be told, I can't handle the issues on this ship alone. I need your support, sir.",
  ui_story_5070_50700801_37_dialog_content = "Please tell us, what should we do now?",
  ui_story_5070_50700801_38_dialog_content = "On this ship, you should be following the orders of the captain, not me.",
  ui_story_5070_50700801_39_dialog_content = "Mr. Zhong Xu, thank you for helping us.",
  ui_story_5070_50700801_40_dialog_content = "Captain, sorry for making you deal with our issues while steering the ship...",
  ui_story_5070_50700801_41_dialog_content = "Say no more. A captain who doesn't shoulder the most responsibilities on the ship isn't a worthy captain.",
  ui_story_5070_50700801_42_dialog_content = "I've checked the ship's condition. We should be able to stop this fire if we take action now.",
  ui_story_5070_50700801_43_dialog_content = "Yes!",
  ui_story_5070_50700801_44_dialog_content = "The storm is still fierce... Dr. Liqing, please take the evacuees farther away!",
  ui_story_5070_50700801_45_dialog_content = "Everyone else should prepare linen bags and break off burning objects with fire hooks.",
  ui_story_5070_50700801_46_dialog_content = "Reinforcements will be coming later.",
  ui_story_5070_50700801_47_dialog_content = "*Coughs* The air here is getting hotter. We won't be able to stay here much longer.",
  ui_story_5070_50700801_48_dialog_content = "I brought over some other stuff, Xuan Ji. Is there anything we can use?",
  ui_story_5070_50700801_49_dialog_content = "The wood the cabin is made out of won't be resilient enough, given the water pressure...",
  ui_story_5070_50700801_50_dialog_content = "Xuan Ji?",
  ui_story_5070_50700801_51_dialog_content = "Back with the stuff so soon, PlayerName?",
  ui_story_5070_50700801_52_dialog_content = "Actually quite a while, but you were so focused that you didn't notice.",
  ui_story_5070_50700801_53_dialog_content = "While you did ask me to find useful materials...",
  ui_story_5070_50700801_54_dialog_content = "All I could find nearby were empty boxes and discarded parts.",
  ui_story_5070_50700801_55_dialog_content = "You really think we can make something to extinguish the fire with just this stuff?",
  ui_story_5070_50700801_56_dialog_content = "We'll have to. The fire sealed off the passage to the cargo hold, so that leaves improvisation our only option.",
  ui_story_5070_50700801_57_dialog_content = "But for artisans, it's not necessary to use predetermined or best components.",
  ui_story_5070_50700801_58_dialog_content = "We can make the wood harder with coating, replace missing nails with mortise and tenon, and modify the structure to make the whole thing stronger.",
  ui_story_5070_50700801_59_dialog_content = "Combine everything we've seen and learned to make whatever you need.",
  ui_story_5070_50700801_60_dialog_content = "Flexible adaptation is the true essence of gadgetry.",
  ui_story_5070_50700801_61_dialog_content = "Done! We can go help now.",
  ui_story_5070_50700801_62_dialog_content = "Captain! The fire above is finally under control, but inside the cabin...",
  ui_story_5070_50700801_63_dialog_content = "It's fine.",
  ui_story_5070_50700801_64_dialog_content = "Sorry to keep you waiting—",
  ui_story_5070_50700801_65_dialog_content = "It took some time to cobble together a makeshift, but satisfaction is guaranteed!",
  ui_story_5070_50700801_66_dialog_content = "Lady Xuan Ji, what is this... thing?",
  ui_story_5070_50700801_67_dialog_content = "You can turn that on now, PlayerName.",
  ui_story_5070_50700801_68_dialog_content = "Alright!",
  ui_story_5070_50700801_69_dialog_content = "<color=#e8d9bb>Snap, snap.</color>",
  ui_story_5070_50700801_70_dialog_content = "<color=#e8d9bb>The once scattered and loose wood strips and metal plates spontaneously twist, join, and fit together.</color>",
  ui_story_5070_50700801_71_dialog_content = "<color=#e8d9bb>With one end hanging into the seawater from the ship's side and the other standing on the deck, it resembles a mechanical dragon proudly rising from the sea.</color>",
  ui_story_5070_50700801_72_dialog_content = "Even though it's made of box strips and junked parts, it's still enough to put out the fire.",
  ui_story_5070_50700801_73_dialog_content = "We'll just call it the Water Dragon!",
  ui_story_5070_50700801_74_dialog_content = "<color=#e8d9bb>Powerful water jets from the dragon's mouth and white smoke billow in the cabin, extinguishing the once ferocious flames in large patches.</color>",
  ui_story_5070_50700801_75_dialog_content = "Don't just stand there. Get moving now.",
  ui_story_5070_50700801_76_dialog_content = "Xuan Ji, you're in charge here.",
  ui_story_5070_50700801_77_dialog_content = "I won't let you down!",
  ui_story_5070_50700801_78_dialog_content = "Especially with PlayerName here too... PlayerName?",
  ui_story_5070_50700801_79_dialog_content = "Got a funny feeling.",
  ui_story_5070_50700801_80_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5070_50700801_81_dialog_content = "<color=#e8d9bb>The previously quelled flames flare up once again.</color>",
  ui_story_5070_50700801_82_dialog_content = "No, this is never going to end.",
  ui_story_5070_50700801_83_dialog_content = "I'll use my psychic ability to find the source of the explosion. Maybe I'll be able to find a solution too.",
  ui_story_5070_50700801_84_dialog_content = "Force Boost!",
  ui_story_5070_50700801_85_dialog_content = "(Not here. Need to keep going down.)",
  ui_story_5070_50700801_86_dialog_content = "(The source is... The hold? What's in there...?)",
  ui_story_5070_50700801_87_dialog_content = "Whoa!",
  ui_story_5070_50700801_88_dialog_content = "<size=45>Graaah!!</size>",
  ui_story_5070_50700801_89_dialog_content = "<color=#e8d9bb>The deck beneath is struck by the clockwork beast, splitting open and revealing a sea of flames below.</color>",
  ui_story_5070_50700801_90_dialog_content = "PlayerName!",
  ui_story_5070_50700801_91_dialog_content = "(Fallen in—!)",
  ui_story_5070_50700801_92_dialog_content = "To Ashes!",
  ui_story_5070_50700801_93_dialog_content = "!",
  ui_story_5070_50700801_94_dialog_content = "Ouch... My back really hurts. But...",
  ui_story_5070_50700801_95_dialog_content = "I've clearly fallen right into where the fire started, but how come the flames aren't the slightest bit hot?",
  ui_story_5070_50700801_96_dialog_content = "Young friend, how are your injuries?",
  ui_story_5070_50700801_97_dialog_content = "Zhong Xu?! Why did you follow me down here?! It's too dangerous. Are you okay...?",
  ui_story_5070_50700801_98_dialog_content = "Fortunately, Ministress Armilla modified my wheelchair. It's still fine after taking that impact.",
  ui_story_5070_50700801_99_dialog_content = "That's not the question...",
  ui_story_5070_50700801_100_dialog_content = "I'm also quite skilled in the Flame Force Arts and can control the wildfire on this ship.",
  ui_story_5070_50700801_101_dialog_content = "You won't be burned by the flames at all.",
  ui_story_5070_50700801_102_dialog_content = "Amazing! Doesn't this mean you can move freely in the fire?",
  ui_story_5070_50700801_103_dialog_content = "By the way, this place is close to the hold. With Zhong Xu's ability, we might even be able to deal with the source of the fire directly!",
  ui_story_5070_50700801_104_dialog_content = "Wait a minute.",
  ui_story_5070_50700801_105_dialog_content = "You have some special powers, but your physical fitness is lacking. You should go somewhere safe first.",
  ui_story_5070_50700801_106_dialog_content = "How could such a random opportunity be passed up?",
  ui_story_5070_50700801_107_dialog_content = "That's not your responsibility.",
  ui_story_5070_50700801_108_dialog_content = "As an envoy from another land, you are very important and should value your own safety first. No one will criticize you harshly for doing that.",
  ui_story_5070_50700801_109_dialog_content = "There's no need to put yourself in danger.",
  ui_story_5070_50700801_110_dialog_content = "I know you're just concerned for me, but if you're always worrying about things that haven't even happened yet...",
  ui_story_5070_50700801_111_dialog_content = "Would you ever be able to get anything done?",
  ui_story_5070_50700801_112_dialog_content = "Also, the Zhong Xu who just jumped down with me said this... Isn't that a little unconvincing?",
  ui_story_5070_50700801_113_dialog_content = "Zhong Xu is not responsible for saving me, no?",
  ui_story_5070_50700801_114_dialog_content = "...",
  ui_story_5070_50700801_115_dialog_content = "Hahaha, you make a good point.",
  ui_story_5070_50700801_116_dialog_content = "I never thought that I would be telling someone else to be careful.",
  ui_story_5070_50700801_117_dialog_content = "You're quite an amazing person.",
  ui_story_5070_50700801_118_dialog_content = "Let's go together.",
  ui_story_5070_50700801_119_dialog_content = "I'll confirm the location of the source of the fire.",
  ui_story_5070_50700801_120_dialog_content = "Force Boost!",
  ui_story_5070_50700801_121_dialog_content = "Hang on, there's something weird about this fire source. And...",
  ui_story_5070_50700801_122_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5070_50700801_123_dialog_content = "<size=45>Look out!</size>",
  ui_story_5070_50700801_124_dialog_content = "<color=#e8d9bb>A sudden burst of flames engulfs everything.</color>",
  ui_story_5070_50700802_1_dialog_content = "*Cough* *cough*... There's smoke everywhere.",
  ui_story_5070_50700802_2_dialog_content = "I can barely breathe and it's hard to focus... but I swear I sensed someone here just now...",
  ui_story_5070_50700802_3_dialog_content = "...",
  ui_story_5070_50700802_4_dialog_content = "*Cough* Who ARE you...?",
  ui_story_5070_50700802_5_dialog_content = "<color=#e8d9bb>A peculiar white light flashes by in the midst of the smoke.</color>",
  ui_story_5070_50700802_6_dialog_content = "Young friend!",
  ui_story_5070_50700802_7_dialog_content = "Zhong Xu... *cough*...",
  ui_story_5070_50700802_8_dialog_content = "Give me your hand!",
  ui_story_5070_50700802_9_dialog_content = "Wait, over there...",
  ui_story_5070_50700802_10_dialog_content = "<color=#e8d9bb>A ball of fire explodes in front.</color>",
  ui_story_5070_50700802_11_dialog_content = "Let's get out of here first.",
  ui_story_5070_50700802_12_dialog_content = "How's PlayerName, Mr. Zhong Xu? Is he alright?",
  ui_story_5070_50700802_13_dialog_content = "Hey! Out of the way! All of you!",
  ui_story_5070_50700802_14_dialog_content = "Let the doctor pass!",
  ui_story_5070_50700901_1_dialog_content = "Urgh...",
  ui_story_5070_50700901_2_dialog_content = "Meow!",
  ui_story_5070_50700901_3_dialog_content = "... Why's there a cat on my bed?",
  ui_story_5070_50700901_4_dialog_content = "A-Aren't you that cat who's always around Doctor Liqing... Tinytail, right?",
  ui_story_5070_50700901_5_dialog_content = "Meow!",
  ui_story_5070_50700901_6_dialog_content = "What are you doing here?",
  ui_story_5070_50700901_7_dialog_content = "Oh yeah, I've gotta ask about the fire yesterday... Is everyone okay?!",
  ui_story_5070_50700901_8_dialog_content = "Meow! Meow!",
  ui_story_5070_50700901_9_dialog_content = "Hey... Out of the way, Tinytail. That's dangerous.",
  ui_story_5070_50700901_10_dialog_content = "Oh, I just went to get some herbs and you're already up?",
  ui_story_5070_50700901_11_dialog_content = "Lie down this instant.",
  ui_story_5070_50700901_12_dialog_content = "Meow...",
  ui_story_5070_50700901_13_dialog_content = "Well done, Tinytail!",
  ui_story_5070_50700901_14_dialog_content = "I knew PlayerName would be a difficult patient like Zhong Xu.",
  ui_story_5070_50700901_15_dialog_content = "It was really you who had Tinytail get in my way?",
  ui_story_5070_50700901_16_dialog_content = "Of course, don't underestimate that smoke you choked on.",
  ui_story_5070_50700901_17_dialog_content = "You would be in deep trouble if the poisonous smoke entered your lungs.",
  ui_story_5070_50700901_18_dialog_content = "Lie down and wait.",
  ui_story_5070_50700901_19_dialog_content = "4.5g of fritillaria, 3g of trichosanthes, and 2.4g each of pollen, wolfiporia, mandarin orange, and platycodon.",
  ui_story_5070_50700901_20_dialog_content = "What's this?",
  ui_story_5070_50700901_21_dialog_content = "It's the recipe for an anti-inflammatory that will detoxify your lungs.",
  ui_story_5070_50700901_22_dialog_content = "Don't forget to increase your water intake, get more rest, and breathe in more fresh air. As for your food, eat light.",
  ui_story_5070_50700901_23_dialog_content = "Come see me immediately if you experience a cough, phlegm, or a stuffy chest. Got it?",
  ui_story_5070_50700901_24_dialog_content = "Why are you looking at me like that?",
  ui_story_5070_50700901_25_dialog_content = "Liqing seems pretty reliable right now.",
  ui_story_5070_50700901_26_dialog_content = "Basically, it's like... How would it be phrased in Longzhou? Mighty doctor style!",
  ui_story_5070_50700901_27_dialog_content = "Really?! Ahem... I mean, isn't that expected?",
  ui_story_5070_50700901_28_dialog_content = "All right, here's your medicine. Take it while it's still hot.",
  ui_story_5070_50700901_29_dialog_content = "Tss... Q-quite a complex flavor.",
  ui_story_5070_50700901_30_dialog_content = "Master Bu says, \"Good medicine is bitter. It is the price you pay for recovery.\"",
  ui_story_5070_50700901_31_dialog_content = "... Is it really that bad?",
  ui_story_5070_50700901_32_dialog_content = "It's not exactly unpleasant, it's just the first time I've tasted something so layered...",
  ui_story_5070_50700901_33_dialog_content = "I'm not really used to it",
  ui_story_5070_50700901_34_dialog_content = "What am I going to do with you young ones?",
  ui_story_5070_50700901_35_dialog_content = "Here, take this candied fruit. It'll help after you've taken your medicine.",
  ui_story_5070_50700901_36_dialog_content = "But you'll only get this one. I only managed to hide a single bag while boarding the ship.",
  ui_story_5070_50700901_37_dialog_content = "Thank you, Liqing. That's very considerate of you.",
  ui_story_5070_50700901_38_dialog_content = "It can't be helped, I'm a great doctor after all!",
  ui_story_5070_50700901_39_dialog_content = "Rest well. I have to see the others.",
  ui_story_5070_50700901_40_dialog_content = "Is anyone else injured?",
  ui_story_5070_50700901_41_dialog_content = "Stay down. Your condition was the most serious yesterday, so forget about everyone else!",
  ui_story_5070_50700901_42_dialog_content = "Don't worry, it'll be fine.",
  ui_story_5070_50700901_43_dialog_content = "I have to give everyone some cooling and detoxifying medicine as a precaution.",
  ui_story_5070_50700901_44_dialog_content = "Speaking of the others...",
  ui_story_5070_50700901_45_dialog_content = "Many came to visit while you were asleep. Now that you're awake, I can call them all over.",
  ui_story_5070_50700901_46_dialog_content = "No, no, no. I know everyone is right as rain, so no need to worry...",
  ui_story_5070_50700901_47_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5070_50700901_48_dialog_content = "No formality necessary!",
  ui_story_5070_50700901_49_dialog_content = "*Gasp*",
  ui_story_5070_50700901_50_dialog_content = "Dantang?",
  ui_story_5070_50700901_51_dialog_content = "Lady Xuan Ji, please don't push Her Highness like that.",
  ui_story_5070_50700901_52_dialog_content = "Aren't you a little overprotective, Jiu? Relax, Her Highness is precious, but not fragile either.",
  ui_story_5070_50700901_53_dialog_content = "Xuan Ji? Jiu? Why are you all here?",
  ui_story_5070_50700901_54_dialog_content = "To see yesterday's hero, of course.",
  ui_story_5070_50700901_55_dialog_content = "I'm glad you weren't seriously hurt, or I wouldn't know how to make it up to you.",
  ui_story_5070_50700901_56_dialog_content = "There's no reason for you to apologize. No one would have thought I'd slip up just then.",
  ui_story_5070_50700901_57_dialog_content = "And everyone's alright, which proves that your contraption succeeded in putting out the fire...",
  ui_story_5070_50700901_58_dialog_content = "Well, you're healthy enough to be long-winded, so you must be fine.",
  ui_story_5070_50700901_59_dialog_content = "So how's it feel to actually see the recovering PlayerName yourself, Princess Dantang?",
  ui_story_5070_50700901_60_dialog_content = "Much better than snooping around, right?",
  ui_story_5070_50700901_61_dialog_content = "You must have mistaken someone else for me, Ministress Armilla.",
  ui_story_5070_50700901_62_dialog_content = "It is my duty to be concerned about the health of an important envoy such as PlayerName.",
  ui_story_5070_50700901_63_dialog_content = "I have no need to, as you said, snoop.",
  ui_story_5070_50700901_64_dialog_content = "Yes, yes, I believe all that smoke from yesterday is still messing with my eyes.",
  ui_story_5070_50700901_65_dialog_content = "I shall leave you to your duty then, Princess Dantang. Please continue your concern for PlayerName!",
  ui_story_5070_50700901_66_dialog_content = "I...",
  ui_story_5070_50700901_67_dialog_content = "It's okay, Dantang. I'm perfectly health right now, and there's nothing to worry about.",
  ui_story_5070_50700901_68_dialog_content = "There's nothing bothering me either, um... Excpet for that medicinal smell. It's really something...",
  ui_story_5070_50700901_69_dialog_content = "Medicine? I do have a solution for that.",
  ui_story_5070_50700901_70_dialog_content = "When you are out of immediate danger, healing through food is the superior option.",
  ui_story_5070_50700901_71_dialog_content = "Given Liqing is also present, I would like to prepare a delicious medicinal meal for everyone. What do you think of the idea?",
  ui_story_5070_50700901_72_dialog_content = "Make it tasty?! No problem!",
  ui_story_5070_50700901_73_dialog_content = "I know the recipe for many tonics, and I even especially purchased ingredients for this voyage.",
  ui_story_5070_50700901_74_dialog_content = "Lotus root promotes health, winter melon nourishes the skin, wolfiporia nurtures the mind...",
  ui_story_5070_50700901_75_dialog_content = "I can make so many things!",
  ui_story_5070_50700901_76_dialog_content = "...",
  ui_story_5070_50700901_77_dialog_content = "Isn't Xuan Ji coming to eat something...? Xuan Ji?",
  ui_story_5070_50700901_78_dialog_content = "Yes? Anything for me to help with?",
  ui_story_5070_50700901_79_dialog_content = "Nope. You seem a little distracted, and haven't said anything for quite a while.",
  ui_story_5070_50700901_80_dialog_content = "Is that so obvious?",
  ui_story_5070_50700901_81_dialog_content = "Guess I still gotta work on my composure. Note to self: Make a mask that can help keep the desired facial expression.",
  ui_story_5070_50700901_82_dialog_content = "Actually, I've been thinking about last night.",
  ui_story_5070_50700901_83_dialog_content = "When Mr. Zhong Xu got you out of the smoke...",
  ui_story_5070_50700901_84_dialog_content = "You kept mumbling about fires and figures.",
  ui_story_5070_50700901_85_dialog_content = "What did you see?",
  ui_story_5070_50700901_86_dialog_content = "It's not really seeing per se, more like sensing.",
  ui_story_5070_50700901_87_dialog_content = "There seemed to be something really weird in the hold, like fire, but I couldn't feel the heat flames should give off.",
  ui_story_5070_50700901_88_dialog_content = "It had no heat, but still seemed more substantial than all the surrounding flames combined.",
  ui_story_5070_50700901_89_dialog_content = "It was like... A miniature sun.",
  ui_story_5070_50700901_90_dialog_content = "... I know my description is a little strange.",
  ui_story_5070_50700901_91_dialog_content = "Anyway, I suspect the lightning strike was just the catalyst, and this thing was the real cause of the blaze.",
  ui_story_5070_50700901_92_dialog_content = "As for the figure, I didn't get a good enough look, but it stayed near the hold the whole time...",
  ui_story_5070_50700901_93_dialog_content = "It's all a little odd.",
  ui_story_5070_50700901_94_dialog_content = "Got it.",
  ui_story_5070_50700901_95_dialog_content = "But let's curb the urge next time, PlayerName.",
  ui_story_5070_50700901_96_dialog_content = "Stop mind-scanning anything unusual that you picked up...",
  ui_story_5070_50700901_97_dialog_content = "I can't bail you out of danger all the time even if I wanted to.",
  ui_story_5070_50700901_98_dialog_content = "Sorry... I'll pay attention.",
  ui_story_5070_50700901_99_dialog_content = "Well, gotta run now.",
  ui_story_5070_50700901_100_dialog_content = "Hang on.",
  ui_story_5070_50700901_101_dialog_content = "Did something else bad happen while I was asleep?",
  ui_story_5070_50700901_102_dialog_content = "...",
  ui_story_5070_50700901_103_dialog_content = "Well, guess I really have to make the expression mask an agenda.",
  ui_story_5070_50700901_104_dialog_content = "Assuming I make it back to my workshop in Longzhou.",
  ui_story_5070_50700901_105_dialog_content = "Is something wrong with the voyage?",
  ui_story_5070_50700901_106_dialog_content = "There's a saying in seafaring:",
  ui_story_5070_50700901_X106_dialog_content = "\"Navigate by the stars by night, the sun by day, the gloom by compass, and leave the area as soon as possible when none of that works.\"",
  ui_story_5070_50700901_107_dialog_content = "Star- and sun-gazing? Do you mean determining a ship's direction by the stars, like before Xuan Ji?",
  ui_story_5070_50700901_108_dialog_content = "Right. If there's no star or moon, you still have a compass for direction.",
  ui_story_5070_50700901_109_dialog_content = "But if even the instruments fail, you have no way to know where you're going.",
  ui_story_5070_50700901_110_dialog_content = "If you don't get out soon enough, you'll be lost at sea.",
  ui_story_5070_50700901_111_dialog_content = "Following the ruckus last night, I tried everything to get our bearings in the storm.",
  ui_story_5070_50700901_112_dialog_content = "...Nothing is effective?",
  ui_story_5070_50700901_113_dialog_content = "<color=#e8d9bb>Xuan Ji nods slightly.</color>",
  ui_story_5070_50700901_114_dialog_content = "Nothing has worked, even now.",
  ui_story_5070_50700901_115_dialog_content = "That wouldn't happen to Shadowind in a normal voyage.",
  ui_story_5070_50700901_116_dialog_content = "But we're so far out and without a comprehensive chart, that we can't even rely on the sun even when it comes out.",
  ui_story_5070_50700901_117_dialog_content = "So I'm pretty sure at this very moment...",
  ui_story_5070_50700901_118_dialog_content = "The Shadowind is off course.",
  ui_story_5070_50700902_1_dialog_content = "We're lost and still gotta deal with the Eclipsites... The trip's been very eventful.",
  ui_story_5070_50700902_2_dialog_content = "We gotta get our bearings as soon as we can.",
  ui_story_5070_50700902_3_dialog_content = "I understand the reasoning, but what's the connection with moving the Water Dragon?",
  ui_story_5070_50700902_4_dialog_content = "We'd give a purpose to every gadget we made, but that didn't mean it was the only thing they were good for.",
  ui_story_5070_50700902_5_dialog_content = "<color=#e8d9bb>In a thunderous rumble, seawater is pumped into pre-prepared wooden barrels through brass pipes.</color>",
  ui_story_5070_50700902_6_dialog_content = "See, other than seawater, we also caught a bunch of fish and prawns.",
  ui_story_5070_50700902_7_dialog_content = "The sea might be big, but it has different creatures living in different parts.",
  ui_story_5070_50700902_8_dialog_content = "So if we can catch some sealife iconic to the region...",
  ui_story_5070_50700902_9_dialog_content = "We should get an educated clue to roughly where we are by comparing them to the pictures in the guidebook.",
  ui_story_5070_50700902_10_dialog_content = "So even this angle can be considered.",
  ui_story_5070_50700902_11_dialog_content = "Catch anything special?",
  ui_story_5070_50700902_12_dialog_content = "Unfortunately, just plain creatures good only for the medicinal meals the princess wanted to make.",
  ui_story_5070_50700902_13_dialog_content = "A disclaimer though, that there's risk involved in this.",
  ui_story_5070_50700902_14_dialog_content = "The sailors catch fish for us every day, so what's the risk?",
  ui_story_5070_50700902_15_dialog_content = "Actually, I only mentioned half of it.",
  ui_story_5070_50700902_16_dialog_content = "While gadgets can be adapted for many things, they weren't designed for that.",
  ui_story_5070_50700902_17_dialog_content = "So it's possible for something unexpected to happen...",
  ui_story_5070_50700902_18_dialog_content = "Take the Fire Crab, for example. It's great for welding.",
  ui_story_5070_50700902_19_dialog_content = "But awful for grilling meat.",
  ui_story_5070_50700902_20_dialog_content = "Do you have any idea how nasty charcoaled meat tastes?",
  ui_story_5070_50700902_21_dialog_content = "I'd rather not know. Ever.",
  ui_story_5070_50700902_22_dialog_content = "And when exactly would you ever use fire crabs to cook?",
  ui_story_5070_50700902_23_dialog_content = "Very similar to using a pump to catch fish right now.",
  ui_story_5070_50700902_24_dialog_content = "It's a dire emergency.",
  ui_story_5070_50700902_25_dialog_content = "Even though I'm not that familiar with Longzhou sayings.",
  ui_story_5070_50700902_26_dialog_content = "But something tells me that roasting with fire crabs doesn't fit the word.",
  ui_story_5070_50700902_27_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5070_50700902_28_dialog_content = "What did the ship hit?",
  ui_story_5070_50700902_29_dialog_content = "Turn the Water Dragon off.",
  ui_story_5070_50700902_30_dialog_content = "The pumping action is so intense, it has probably attracted something huge in the ocean.",
  ui_story_5070_50700902_31_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5070_50700902_32_dialog_content = "The ship's tilting! Everyone, grab onto something and hold tight!",
  ui_story_5070_50700902_33_dialog_content = "I... I did it.",
  ui_story_5070_50700902_34_dialog_content = "I finally came to the deck for some fresh air, and I just had to run into something like this!",
  ui_story_5070_50700902_35_dialog_content = "Thank goodness I didn't stray from the ox fences. Don't tell me that divination really meant... Ouch!",
  ui_story_5070_50700902_36_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5070_50700902_37_dialog_content = "The tilt's getting worse. We can't do anything like this.",
  ui_story_5070_50700902_38_dialog_content = "Everyone, move to the other side! We gotta balance the ship!",
  ui_story_5070_50700902_39_dialog_content = "I'll use the Fire Crab to push Shadowind's burner. Just hold on and we'll gain speed soon.",
  ui_story_5070_50700902_40_dialog_content = "Success! The shadow in the sea has been left behind.",
  ui_story_5070_50700902_41_dialog_content = "I've been attacked by fire crabs so many times that it's odd to be saved by them on this occasion.",
  ui_story_5070_50700902_42_dialog_content = "What did I tell you? A gadget is as good or evil as those who operate it.",
  ui_story_5070_50700902_43_dialog_content = "It's up to the user to use it to save a life or end it.",
  ui_story_5070_50700902_44_dialog_content = "Maybe I should change my mind about those \"big, scary crabs\"...",
  ui_story_5070_50700902_45_dialog_content = "This is the first time the Shadowind has moved at such speed. Is it sustainable?",
  ui_story_5070_50700902_46_dialog_content = "Only in your dreams.",
  ui_story_5070_50700902_47_dialog_content = "We get the power we have now all because of the Flame Force inside the Fire Crab.",
  ui_story_5070_50700902_48_dialog_content = "It will run out very quickly if we don't replenish it, then...",
  ui_story_5070_50700902_49_dialog_content = "Lady Xuan Ji! The guy by the boiler told me that all the fire crabs aren't moving anymore!",
  ui_story_5070_50700902_50_dialog_content = "Like just now?",
  ui_story_5070_50700902_51_dialog_content = "Well, it died faster than I anticipated.",
  ui_story_5070_50700902_52_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5070_50700902_53_dialog_content = "Force Boost!",
  ui_story_5070_50700902_54_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5070_50700902_55_dialog_content = "Did it work?",
  ui_story_5070_50700902_56_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5070_50700902_57_dialog_content = "Please, desist. We're neither food, nor toys!",
  ui_story_5070_50700902_58_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5070_50700902_59_dialog_content = "No. I can only get it to stop for a while. We'll still be overtaken unless the Shadowind increases the distance.",
  ui_story_5070_50700902_60_dialog_content = "And what I sensed of its body underwater is many times larger than the shadow on the surface...",
  ui_story_5070_50700902_61_dialog_content = "How much bigger is it, exactly?",
  ui_story_5070_50700902_62_dialog_content = "What?",
  ui_story_5070_50700902_63_dialog_content = "We can gauge the silhouette in the water.",
  ui_story_5070_50700902_X63_dialog_content = "And then calculate its size based on your mind link, PlayerName.",
  ui_story_5070_50700902_64_dialog_content = "Finally, figure out its threat range according to the Shadowind's weight and the tilt angle of the impact...",
  ui_story_5070_50700902_65_dialog_content = "I know what's under the water!",
  ui_story_5070_50700902_66_dialog_content = "Can you keep it at bay for a while, PlayerName? I gotta get something from my cabin that could probably draw it away.",
  ui_story_5070_50700902_67_dialog_content = "Okay. Leave it to me.",
  ui_story_5070_50700902_68_dialog_content = "Force Boost!",
  ui_story_5070_50700902_69_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5070_50700902_70_dialog_content = "Force Boost!",
  ui_story_5070_50700902_71_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5070_50700902_72_dialog_content = "(Tss... How many times?? You have to be joking. And isn't Xuan Ji better?)",
  ui_story_5070_50700902_73_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5070_50700902_74_dialog_content = "Force Boost...!",
  ui_story_5070_50700902_75_dialog_content = "I'm back, PlayerName!",
  ui_story_5070_50700902_76_dialog_content = "Brilliant—",
  ui_story_5070_50700902_77_dialog_content = "<color=#e8d9bb>Bang!!!</color>",
  ui_story_5070_50700902_78_dialog_content = "(The most violent impact yet occurred, and I was thrown bodily into the air.)",
  ui_story_5070_50700902_79_dialog_content = "Grab my parasol!",
  ui_story_5070_50700902_80_dialog_content = "(No! I won't be able to distract the sea monster now...!)",
  ui_story_5070_50700902_81_dialog_content = "Xuan Ji! Give me what you're holding!",
  ui_story_5070_50700902_82_dialog_content = "?!",
  ui_story_5070_50700902_83_dialog_content = "Just what kind of a daredevil are you... Okay, here it comes!",
  ui_story_5070_50700902_84_dialog_content = "(One advantage to being aloft is you can throw further!)",
  ui_story_5070_50700902_85_dialog_content = "Stop chasing! This is a more suitable toy for you!",
  ui_story_5070_50700902_86_dialog_content = "<color=#e8d9bb>Plop!</color>",
  ui_story_5070_50700902_87_dialog_content = "<color=#e8d9bb>The stone taken from Xuan Ji falls into the sea.</color>",
  ui_story_5070_50700902_88_dialog_content = "(I sensed the sea monster turning, and saw Xuan Ji open the umbrella to try to catch me.)",
  ui_story_5070_50700902_89_dialog_content = "(There's no time, but it doesn't matter because... That person's still down there!)",
  ui_story_5070_50700902_90_dialog_content = "To Ashes!",
  ui_story_5070_50700902_91_dialog_content = "<color=#e8d9bb>With scarlet flames surging skyward and the engine resonating with a full-speed hum, the Shadowind accelerates once more.</color>",
  ui_story_5070_50700902_92_dialog_content = "(I tumbled into quiet, calm flames.)",
  ui_story_5070_50700902_93_dialog_content = "Phew, this time, we lost the sea monster for good. It's finally over...",
  ui_story_5070_50700902_94_dialog_content = "Young friend.",
  ui_story_5070_50700902_95_dialog_content = "I really admire your great bravery.",
  ui_story_5070_50700902_96_dialog_content = "But don't you think it was too reckless to put yourself in danger like that?",
  ui_story_5070_50700902_97_dialog_content = "(Wh-what a serious tone!)",
  ui_story_5070_50700902_98_dialog_content = "I'm... Sorry for worrying everyone. However, I'm actually pretty certain.",
  ui_story_5070_50700902_99_dialog_content = "Because I saw Zhong Xu here.",
  ui_story_5070_50700902_100_dialog_content = "Thank you so much.",
  ui_story_5070_50700902_101_dialog_content = "... It's alright. You should thank Ministress Armilla instead of me.",
  ui_story_5070_50700902_102_dialog_content = "Without the modifications she made to my wheelchair, I wouldn't be able to move around freely on this unstable ship.",
  ui_story_5070_50700902_103_dialog_content = "PlayerName!",
  ui_story_5070_50700902_104_dialog_content = "I knew you were lucky! You can achieve anything as long as you try.",
  ui_story_5070_50700902_105_dialog_content = "Haha, thanks for believing me. But, how could a lump of rock lure away the sea monster?",
  ui_story_5070_50700902_106_dialog_content = "Because that's no ordinary rock but a glowstone, the darker it is around it, the brighter it gets.",
  ui_story_5070_50700902_107_dialog_content = "No much has been written about that monster, except they dwelled in the deep sea.",
  ui_story_5070_50700902_108_dialog_content = "And creatures like that are always attracted to light.",
  ui_story_5070_50700902_109_dialog_content = "So I figured it would make an excellent lure.",
  ui_story_5070_50700902_110_dialog_content = "Luckily, it worked.",
  ui_story_5070_50700902_111_dialog_content = "Is everyone okay?",
  ui_story_5070_50700902_112_dialog_content = "We're good, other than seconds away from being monster food.",
  ui_story_5070_50700902_113_dialog_content = "Sailing the ocean is really hard...",
  ui_story_5070_50700902_114_dialog_content = "Lucky these sorts of things aren't in the sky, otherwise Soroz and I would also be in danger.",
  ui_story_5070_50700902_115_dialog_content = "Well, we oughtta be safe for a while after that harrowing encounter.",
  ui_story_5070_50700902_116_dialog_content = "It's rare to run across such behemoths at sea, after all.",
  ui_story_5070_50700902_117_dialog_content = "At least there won't be another attack to worry about until we've left its territory.",
  ui_story_5070_50700902_118_dialog_content = "So are you saying that we can now use as many Water Dragons as we want?",
  ui_story_5070_50700902_119_dialog_content = "To the max, even.",
  ui_story_5070_50700902_120_dialog_content = "Get everyone who isn't busy to come here. Let's take this chance to try our best to work together and catch more fish.",
  ui_story_5070_50700902_121_dialog_content = "We've been sailing for a while now, and it's time to replenish our rations on the Shadowind.",
  ui_story_5070_50700902_122_dialog_content = "Okay... okay, coming right up.",
  ui_story_5070_50700902_123_dialog_content = "Oops.",
  ui_story_5070_50700902_124_dialog_content = "My bad. Sorry, I didn't mean to bump into you...",
  ui_story_5070_50700902_125_dialog_content = "Sun the Skillful? It's fine, I just didn't see you arrive either.",
  ui_story_5070_50700902_126_dialog_content = "What are you holding? It smells good.",
  ui_story_5070_50700902_127_dialog_content = "It's bait. The captain told us to catch some fish.",
  ui_story_5070_50700902_128_dialog_content = "With an aroma that delicious, it must be easy to catch some big fish.",
  ui_story_5070_50700902_129_dialog_content = "... Where is she?",
  ui_story_5070_50700902_130_dialog_content = "Captain! Come take a look at what we've fished up!",
  ui_story_5070_50700902_131_dialog_content = "What are you doing, PlayerName?",
  ui_story_5070_50700902_132_dialog_content = "Just now... Sun the Skillful?",
  ui_story_5070_50700902_133_dialog_content = "...",
  ui_story_5070_50700902_134_dialog_content = "Never mind, forget it.",
  ui_story_5070_50700902_135_dialog_content = "<size=25>As long as the bait remains, the fish will come up no matter how deep it swims.</size>",
  ui_story_5070_50700902_136_dialog_content = "What did you say?",
  ui_story_5070_50700902_137_dialog_content = "Nothing! Come, let's check out the party over there.",
  ui_story_5070_50700902_138_dialog_content = "Fine then... Eh? How come you caught so much wood?",
  ui_story_5070_50700902_139_dialog_content = "These are debris of sunken ships.",
  ui_story_5070_50700902_140_dialog_content = "But the type of wood, paint, and degree of corrosion are all different. It's obvious that they're from different ships.",
  ui_story_5070_50700902_141_dialog_content = "I'm afraid there's a concentration of shipwrecks somewhere around here.",
  ui_story_5070_50700902_142_dialog_content = "It could even be a ship graveyard.",
  ui_story_5070_50701001_1_dialog_content = "<color=#e8d9bb>Plop!</color>",
  ui_story_5070_50701001_2_dialog_content = "Yuebai?!",
  ui_story_5070_50701001_3_dialog_content = "Yuebai just jumped head first into the sea?!",
  ui_story_5070_50701001_4_dialog_content = "Worry not. Yuebai is a stronger swimmer than everybody on this ship combined.",
  ui_story_5070_50701001_5_dialog_content = "We as passengers, should trust the captain, so just wait and see.",
  ui_story_5070_50701001_6_dialog_content = "(There are many kinds of danger at sea. Rocks, whirlpools, ferocious sea beasts...)",
  ui_story_5070_50701001_7_dialog_content = "(But they all have one thing in common. They are all responsible for destroying countless ships in various waters.)",
  ui_story_5070_50701001_8_dialog_content = "(After a ship sinks, its wreckage will be pushed by the ocean current and end up at the same place under the water, forming a ship graveyard.)",
  ui_story_5070_50701001_9_dialog_content = "(Is this the place?)",
  ui_story_5070_50701001_10_dialog_content = "(I never thought that I would sail a ship to a graveyard like this one day.)",
  ui_story_5070_50701001_11_dialog_content = "(The skeletons of broken ships are stacked in a pile, gradually covered by corals and seaweeds, eroding, and rotting away.)",
  ui_story_5070_50701001_12_dialog_content = "(It's like the sea is holding a funeral to send off these ships.)",
  ui_story_5070_50701001_13_dialog_content = "(... That ship!)",
  ui_story_5070_50701001_14_dialog_content = "In a moment, Ministress Armilla, young friend, can you salvage more of these ship fragments for me?",
  ui_story_5070_50701001_15_dialog_content = "These fragments look a little familiar to me.",
  ui_story_5070_50701001_16_dialog_content = "As far as I can tell, there's no difference at all between these bits of wood.",
  ui_story_5070_50701001_17_dialog_content = "Anything can tell you something if you look closely enough.",
  ui_story_5070_50701001_18_dialog_content = "I might not be as good as Zhong Xu, but I can still get a lot out of it.",
  ui_story_5070_50701001_19_dialog_content = "See, this piece has the name of the ship on it.",
  ui_story_5070_50701001_20_dialog_content = "And this one here has Fortune Holes.",
  ui_story_5070_50701001_21_dialog_content = "Isn't this just some broken gap?",
  ui_story_5070_50701001_22_dialog_content = "No, these were drilled deliberately.",
  ui_story_5070_50701001_23_dialog_content = "To house lucky charms like coins or mirrors inside.",
  ui_story_5070_50701001_24_dialog_content = "It's meant to ensure a smooth sailing.",
  ui_story_5070_50701001_25_dialog_content = "But since it's found in a shipwreck, the crew and passengers are likely gone... Fickle is the fate.",
  ui_story_5070_50701001_26_dialog_content = "The more debris gets fished out, the more I feel this place is really dangerous...",
  ui_story_5070_50701001_27_dialog_content = "What's that expression for, Zhong Xu...? What do you see?",
  ui_story_5070_50701001_28_dialog_content = "One of these ships belonged to pirates.",
  ui_story_5070_50701001_29_dialog_content = "Pirates?!",
  ui_story_5070_50701001_30_dialog_content = "I've had many dealings with them, so I believe I'm right.",
  ui_story_5070_50701001_31_dialog_content = "But pirates wander on the sea all year round and are far more wary of dangerous waters than ordinary people.",
  ui_story_5070_50701001_32_dialog_content = "I wonder if they were blown here by the wind or chased here by something.",
  ui_story_5070_50701001_33_dialog_content = "That sounds a little frightening... We've already felt the pressure from Eclipsites, storms, and sea monsters!",
  ui_story_5070_50701001_34_dialog_content = "And now we need to worry about what destroyed the pirate's ship, and whether or not it's a threat to us?!",
  ui_story_5070_50701001_35_dialog_content = "<color=#e8d9bb>Splash...</color>",
  ui_story_5070_50701001_36_dialog_content = "It's Yuebai! She's surfaced!",
  ui_story_5070_50701001_37_dialog_content = "I know where this is.",
  ui_story_5070_50701001_38_dialog_content = "Below us is an ocean-going fishing ship that was wrecked several years ago.",
  ui_story_5070_50701001_39_dialog_content = "Judging from the route it should have taken, this should be a junction between the waters of the ocean and Longzhou.",
  ui_story_5070_50701001_40_dialog_content = "So doesn't that mean...",
  ui_story_5070_50701001_41_dialog_content = "Yes, that means we're not far from Longzhou.",
  ui_story_5070_50701001_42_dialog_content = "That's great!",
  ui_story_5070_50701001_43_dialog_content = "It's too early to relax.",
  ui_story_5070_50701001_44_dialog_content = "This place is famous for being a place of death in the sea. There are no corresponding sea charts for these waters, and it's not along Shadowind's established route.",
  ui_story_5070_50701001_45_dialog_content = "Even if we know its approximate location, we won't be able to determine which way we should be sailing.",
  ui_story_5070_50701001_46_dialog_content = "We're also running out of food, so we don't have time to waste.",
  ui_story_5070_50701001_47_dialog_content = "Could you ask Zhong Xu and Xuan Ji to set the engine to full steam ahead, and we can get out of here?",
  ui_story_5070_50701001_48_dialog_content = "No. There are many whirlpools around here. One mistake and we could end up resting in the ship graveyard at the bottom of the sea.",
  ui_story_5070_50701001_49_dialog_content = "Even if they are here, our situation will still be a desperate one. Unless...",
  ui_story_5070_50701001_50_dialog_content = "Unless...?",
  ui_story_5070_50701001_51_dialog_content = "Unless someone noticed that the Shadowind had gone off course a while ago and already planned a countermeasure.",
  ui_story_5070_50701001_52_dialog_content = "The first person to notice the yaw... Xuan Ji?",
  ui_story_5070_50701001_53_dialog_content = "...",
  ui_story_5070_50701001_54_dialog_content = "Hey, don't look at me like that.",
  ui_story_5070_50701001_55_dialog_content = "I do have an idea, but...",
  ui_story_5070_50701001_56_dialog_content = "It's do-or-die.",
  ui_story_5070_50701001_57_dialog_content = "Even though we're in a pickle, we can still inch forward on Shadowind.",
  ui_story_5070_50701001_58_dialog_content = "But if we try this and fail, the whole ship goes down in flame.",
  ui_story_5070_50701001_59_dialog_content = "And we become fish food.",
  ui_story_5070_50701001_60_dialog_content = "It's too risky unless it's the last resort.",
  ui_story_5070_50701001_61_dialog_content = "Captain! Captain! Bad news, fog up ahead!",
  ui_story_5070_50701001_62_dialog_content = "Can't see much around us now; what should we do?",
  ui_story_5070_50701001_63_dialog_content = "Trying to sail in a fog this thick is like walking towards a certain death with your eyes closed.",
  ui_story_5070_50701001_64_dialog_content = "But we no longer have a choice.",
  ui_story_5070_50701001_65_dialog_content = "Fine.",
  ui_story_5070_50701001_66_dialog_content = "I stashed something special in the hold when I came on board.",
  ui_story_5070_50701001_67_dialog_content = "It can power every and all gadgets.",
  ui_story_5070_50701001_68_dialog_content = "Fire Crab, Water Dragon, even the burner that drives the Shadowind...",
  ui_story_5070_50701001_69_dialog_content = "All can perform like never before under its power.",
  ui_story_5070_50701001_70_dialog_content = "But it's unstable and very challenging to control.",
  ui_story_5070_50701001_71_dialog_content = "It's been recorded that in several tests, the output was so excessive...",
  ui_story_5070_50701001_72_dialog_content = "The target wasn't durable enough and self-destructed.",
  ui_story_5070_50701001_73_dialog_content = "So even if we decide to use it, I have to test it out underwater first.",
  ui_story_5070_50701001_74_dialog_content = "The Shadowind will have to undergo modifications as well for it to at least withstand the operational impact.",
  ui_story_5070_50701001_75_dialog_content = "Otherwise, it won't be our last hope but the death of us.",
  ui_story_5070_50701001_76_dialog_content = "I'll give you a list of the materials on the Shadowind later. Just do what you need to do.",
  ui_story_5070_50701001_77_dialog_content = "I'll also let the shipwrights know that they are to follow your orders.",
  ui_story_5070_50701001_78_dialog_content = "Maybe my Flame Force Arts will come in handy too.",
  ui_story_5070_50701001_79_dialog_content = "Why don't I go deal with the fish we just caught then, and prepare it in a way you will find novel?",
  ui_story_5070_50701001_80_dialog_content = "But I... What can I do?",
  ui_story_5070_50701001_81_dialog_content = "I have to go look for stuff in the hold, PlayerName.",
  ui_story_5070_50701001_82_dialog_content = "Would you mind finding the little one and getting some potions to resist toxic fumes?",
  ui_story_5070_50701001_83_dialog_content = "Are you telling me Xuan Ji brought a Flame Sprite onboard?!",
  ui_story_5070_50701001_84_dialog_content = "I was wondering why I kept smelling one onboard! I almost thought there was something wrong with my nose!",
  ui_story_5070_50701001_85_dialog_content = "So she's behind it. Such a dangerous thing to do...",
  ui_story_5070_50701001_86_dialog_content = "According to Master Bu, an ancient sentient being like that could control yin and yang, and change day to night!",
  ui_story_5070_50701001_87_dialog_content = "Sigh, this is going to be a pain.",
  ui_story_5070_50701001_88_dialog_content = "Take this medicine and tell her not to blow this ship up.",
  ui_story_5070_50701001_89_dialog_content = "I've got the medicine, Xuan Ji.",
  ui_story_5070_50701001_90_dialog_content = "But what exactly are you talking about?",
  ui_story_5070_50701001_91_dialog_content = "I just recounted your description, and Liqing immediately started making a fuss.",
  ui_story_5070_50701001_92_dialog_content = "Everyone else seemed to understand. Is it just me who feels completely in the dark?",
  ui_story_5070_50701001_93_dialog_content = "Well, that's not for you to say, PlayerName.",
  ui_story_5070_50701001_94_dialog_content = "I'm not certain I know more about it than you do on this ship.",
  ui_story_5070_50701001_95_dialog_content = "Me?",
  ui_story_5070_50701001_96_dialog_content = "You'll know once I take it out.",
  ui_story_5070_50701001_97_dialog_content = "Take it out? From where?",
  ui_story_5070_50701001_98_dialog_content = "Speaking of which, I've wanted to ask for a while now... Why are there so many wooden cows in the hold?",
  ui_story_5070_50701001_99_dialog_content = "They're wooden oxen, the most common contraption in Longzhou and have been around for generations.",
  ui_story_5070_50701001_100_dialog_content = "They're mainly used to transport goods, though fine for hauling luggage too.",
  ui_story_5070_50701001_101_dialog_content = "Just open it like this and you can get stuff out.",
  ui_story_5070_50701001_102_dialog_content = "It's pretty spacious inside. You could probably fit a person in there.",
  ui_story_5070_50701001_103_dialog_content = "Wanna try it?",
  ui_story_5070_50701001_104_dialog_content = "No way! I have no interest in becoming a commodity.",
  ui_story_5070_50701001_105_dialog_content = "That's what I thought too.",
  ui_story_5070_50701001_106_dialog_content = "Let's check out the star of today's show then.",
  ui_story_5070_50701001_107_dialog_content = "This little box?",
  ui_story_5070_50701001_108_dialog_content = "Don't underestimate this.",
  ui_story_5070_50701001_109_dialog_content = "Qianyun, my school, is a top gadget maker in Ye, and even the entire Longzhou.",
  ui_story_5070_50701001_110_dialog_content = "It boasts a legacy of secret techniques and artifacts for centuries.",
  ui_story_5070_50701001_111_dialog_content = "But you can put all of that together and they still might not compare to this.",
  ui_story_5070_50701001_112_dialog_content = "One of the biggest reasons for me to visit Astra is...",
  ui_story_5070_50701001_113_dialog_content = "To find the priceless treasure lost abroad many years ago...",
  ui_story_5070_50701001_114_dialog_content = "The Zhuyin Flame.",
  ui_story_5070_50701001_115_dialog_content = "From Astra's perspective, it is also a precious ancient relic.",
  ui_story_5070_50701001_116_dialog_content = "Ancient relic?!",
  ui_story_5070_50701001_117_dialog_content = "Wanna see how powerful it is?",
  ui_story_5070_50701001_118_dialog_content = "It's a little risky on the Shadowind. Let's test it out on a dinghy far away.",
  ui_story_5070_50701001_119_dialog_content = "See the true magnum opus from ages past that powered everything.",
  ui_story_5070_50701002_1_dialog_content = "It sure fits the bill for an ancient relic. It's even more powerful than I expected.",
  ui_story_5070_50701002_2_dialog_content = "You felt it with your psychic powers too, right, PlayerName? How does it feel?",
  ui_story_5070_50701002_3_dialog_content = "Pretty awesome.",
  ui_story_5070_50701002_4_dialog_content = "Not only can it endlessly drive Clockwork Beasts, which have already run out of power, but it can also...",
  ui_story_5070_50701002_5_dialog_content = "It also evaporates all surrounding moisture, creating a vacuum.",
  ui_story_5070_50701002_6_dialog_content = "In response, it seems more substantial than all other flames, even like...",
  ui_story_5070_50701002_7_dialog_content = "A miniature sun?",
  ui_story_5070_50701002_8_dialog_content = "Totally... Hang on, isn't that my own description?",
  ui_story_5070_50701002_9_dialog_content = "The Zhuyin Flame... That could have caused the explosion in the ship that day!",
  ui_story_5070_50701002_10_dialog_content = "Oops, busted.",
  ui_story_5070_50701002_11_dialog_content = "Didn't you agree for me to take a look by using my ability? I just obeyed!",
  ui_story_5070_50701002_12_dialog_content = "Seeing is believing, after all. It tells you more than I can ever explain!",
  ui_story_5070_50701002_13_dialog_content = "No wonder Liqing had such a strong reaction.",
  ui_story_5070_50701002_14_dialog_content = "Who could have thought there'd be something so dangerous on board?",
  ui_story_5070_50701002_15_dialog_content = "I sealed it carefully before bringing it on board so it would be safe.",
  ui_story_5070_50701002_16_dialog_content = "But someone intentionally opened it on the day of the fire.",
  ui_story_5070_50701002_17_dialog_content = "I brought it aboard in secret.",
  ui_story_5070_50701002_18_dialog_content = "Even Yuebai didn't know what it was, and I even gave her a heads-up about it.",
  ui_story_5070_50701002_19_dialog_content = "But somebody knew about it and tried to get close.",
  ui_story_5070_50701002_20_dialog_content = "Could that figure I saw earlier be...?!",
  ui_story_5070_50701002_21_dialog_content = "I'm afraid so.",
  ui_story_5070_50701002_22_dialog_content = "For this kind of thing... We need to notify the others immediately.",
  ui_story_5070_50701002_23_dialog_content = "It just so happens that the test of the Zhuyin Flame was successful, so the Shadowind can get out of here right away.",
  ui_story_5070_50701002_24_dialog_content = "Seize the moment to catch that malevolent guy—",
  ui_story_5070_50701002_25_dialog_content = "I don't recall declaring the test successful.",
  ui_story_5070_50701002_26_dialog_content = "What? Haven't all these Clockwork Beasts activated smoothly?",
  ui_story_5070_50701002_27_dialog_content = "There's no doubt about Zhuyin Flame being a power source, but didn't you see what happened to the clockwork beasts?",
  ui_story_5070_50701002_28_dialog_content = "... Shattered into pieces and fell into the sea.",
  ui_story_5070_50701002_29_dialog_content = "The beasts weren't big, and even then that was all I could manage with any sort of certainty.",
  ui_story_5070_50701002_30_dialog_content = "So even if you fortify Shadowind with every last material you can scrounge up...",
  ui_story_5070_50701002_31_dialog_content = "It's not gonna stand up to the Zhuyin Flame at full power.",
  ui_story_5070_50701002_32_dialog_content = "Could Xuan Ji really be unable to solve it too?",
  ui_story_5070_50701002_33_dialog_content = "That's not entirely true.",
  ui_story_5070_50701002_34_dialog_content = "But until then, I have a request, PlayerName.",
  ui_story_5070_50701002_35_dialog_content = "Please keep the failed experiment and someone eyeing the Flame a secret.",
  ui_story_5070_50701002_36_dialog_content = "Maybe... But what should we do now?",
  ui_story_5070_50701002_37_dialog_content = "Just wait.",
  ui_story_5070_50701002_38_dialog_content = "<color=#e8d9bb>The next day...</color>",
  ui_story_5070_50701002_39_dialog_content = "Everyone, come and get a copy of the blueprint. Follow the markings, and start working in your assigned spots.",
  ui_story_5070_50701002_40_dialog_content = "What kind of blueprint is this?",
  ui_story_5070_50701002_41_dialog_content = "Eh... this blueprint...",
  ui_story_5070_50701002_42_dialog_content = "I have been dealing with ships my entire life, and I've never seen something like this on a ship...",
  ui_story_5070_50701002_43_dialog_content = "Ignoring the large hole on the deck is one thing, but deliberately making it bigger?",
  ui_story_5070_50701002_44_dialog_content = "It's almost exposing the core of the Shadowind. That's just too bizarre... Sun, what do you think of it?",
  ui_story_5070_50701002_45_dialog_content = "I... I don't get it either...",
  ui_story_5070_50701002_46_dialog_content = "Why bother with all that? Lady Xuan Ji is way more skilled than we are, right?",
  ui_story_5070_50701002_47_dialog_content = "Let's get to work now; once it's done, we can definitely get out of here.",
  ui_story_5070_50701002_48_dialog_content = "<color=#e8d9bb>Day Three</color>",
  ui_story_5070_50701002_49_dialog_content = "Guys, join me for some fishing.",
  ui_story_5070_50701002_50_dialog_content = "Ugh, how many days have we been surviving on fish? And now, even the seasoning is running out. They taste... Words can't even describe it.",
  ui_story_5070_50701002_51_dialog_content = "Just hold on for a few days. Things will be better once the ship's remodeling is done.",
  ui_story_5070_50701002_52_dialog_content = "<color=#e8d9bb>Day Five</color>",
  ui_story_5070_50701002_53_dialog_content = "The fog on our fishing spot is getting thicker; we can hardly catch any fish now.",
  ui_story_5070_50701002_54_dialog_content = "Didn't we finish the renovation of the Shadowind? Why hasn't Lady Xuan Ji given us any further instructions...",
  ui_story_5070_50701002_55_dialog_content = "Li, don't tell anyone, but I heard from Sun the Skillful that our efforts in this renovation are pointless.",
  ui_story_5070_50701002_56_dialog_content = "Haven't you noticed that Lady Xuan Ji goes out in a small boat every day? He says it's for exploration, but it seems like he's trying to hide how clueless he is!",
  ui_story_5070_50701002_57_dialog_content = "What nonsense are you all talking about? And you, Sun, don't let Captain Yuebai catch you spreading baseless rumors...",
  ui_story_5070_50701002_58_dialog_content = "Hey! PlayerName! PlayerName!",
  ui_story_5070_50701002_59_dialog_content = "You've been going out with Lady Xuan Ji these past few days. Have you heard anything about how we're going to get out of here?",
  ui_story_5070_50701002_60_dialog_content = "Well, all I can say is there is a way... I-I have to give something to Xuan Ji, so I'm off!",
  ui_story_5070_50701002_61_dialog_content = "Phew...",
  ui_story_5070_50701002_62_dialog_content = "Come quickly, PlayerName. I made similar structural modifications according to your description of the Colossus.",
  ui_story_5070_50701002_63_dialog_content = "What? You look like you went another round with the crew.",
  ui_story_5070_50701002_64_dialog_content = "Haha... After all, we've been here several days. Everyone's a little on edge, and wants to get out of here as soon as possible.",
  ui_story_5070_50701002_65_dialog_content = "This model, well, compared with the Colossus, it seems more like Shadowind with wings. Let me see...",
  ui_story_5070_50701002_66_dialog_content = "Don't you have any questions for me, PlayerName?",
  ui_story_5070_50701002_67_dialog_content = "What?",
  ui_story_5070_50701002_68_dialog_content = "I asked you to keep a secret without giving you a solid explanation.",
  ui_story_5070_50701002_69_dialog_content = "Then, I instructed others to make so many modifications only to stay in a dinghy myself all day and avoid all questions.",
  ui_story_5070_50701002_70_dialog_content = "Even I'd suspect I was up to something no good.",
  ui_story_5070_50701002_71_dialog_content = "Why did you trust me, PlayerName?",
  ui_story_5070_50701002_72_dialog_content = "I don't really believe you.",
  ui_story_5070_50701002_73_dialog_content = "I thought so...",
  ui_story_5070_50701002_74_dialog_content = "But I do believe in machinery.",
  ui_story_5070_50701002_75_dialog_content = "Huh?",
  ui_story_5070_50701002_76_dialog_content = "For sure, it wasn't exactly relaxing dealing with those Clockwork Beasts that came out of nowhere.",
  ui_story_5070_50701002_77_dialog_content = "But the first time we met, a dragonfly helped me pick up the letter.",
  ui_story_5070_50701002_78_dialog_content = "Fire Crabs to drive the engine, Water Dragons to put out fires...",
  ui_story_5070_50701002_79_dialog_content = "I've been helped by mechanical creatures again and again.",
  ui_story_5070_50701002_80_dialog_content = "You said it yourself, Xuan Ji: Machinery isn't some ever-changing, omnipotent technology.",
  ui_story_5070_50701002_81_dialog_content = "I believe in machinery, about which you'd never lie.",
  ui_story_5070_50701002_82_dialog_content = "So I also believe that you'll find a way to bring us safely to Longzhou.",
  ui_story_5070_50701002_83_dialog_content = "It is.",
  ui_story_5070_50701002_84_dialog_content = "Well, I can't refute that at all.",
  ui_story_5070_50701002_85_dialog_content = "Given what you said, PlayerName...",
  ui_story_5070_50701002_86_dialog_content = "I'd be remiss as an artisan to not show you the potential of my trade.",
  ui_story_5070_50701002_87_dialog_content = "I'm looking forward to it. But I'd be lying if I said I wasn't curious.",
  ui_story_5070_50701002_88_dialog_content = "What exactly are you waiting for, Xuan Ji?",
  ui_story_5070_50701002_89_dialog_content = "Well, actually...",
  ui_story_5070_50701002_90_dialog_content = "<color=#e8d9bb>Blast of whistle</color>",
  ui_story_5070_50701002_91_dialog_content = "What's that sound from the Shadowind? Why's the horn blowing?",
  ui_story_5070_50701002_92_dialog_content = "That's the signal for communication between ships at sea.",
  ui_story_5070_50701002_93_dialog_content = "Could there be another ship?!",
  ui_story_5070_50701002_94_dialog_content = "<color=#e8d9bb>A little while ago</color>",
  ui_story_5070_50701002_95_dialog_content = "Jiu, Yuebai, come check this out.",
  ui_story_5070_50701002_96_dialog_content = "Is that a ship out there?",
  ui_story_5070_50701002_97_dialog_content = "Your Highness, please step back from the side of the ship.",
  ui_story_5070_50701002_98_dialog_content = "That's not what you should be concerned about, Jiu.",
  ui_story_5070_50701002_99_dialog_content = "Your safety is of utmost importance, so we should take all due care.",
  ui_story_5070_50701002_100_dialog_content = "I can't see what's happening on the ship, but some merchant ships are coming towards us.",
  ui_story_5070_50701002_101_dialog_content = "I never thought we would encounter other ships in these waters.",
  ui_story_5070_50701002_102_dialog_content = "Shall we make contact with them? I wonder if they have plenty of supplies. If they don't...",
  ui_story_5070_50701002_103_dialog_content = "It's probably too late to avoid them now anyway.",
  ui_story_5070_50701002_104_dialog_content = "Sound the horn and see how they react.",
  ui_story_5070_50701002_105_dialog_content = "<color=#e8d9bb>Blast of whistle</color>",
  ui_story_5070_50701002_106_dialog_content = "<color=#e8d9bb>Blast of whistle</color>",
  ui_story_5070_50701002_107_dialog_content = "Response received!",
  ui_story_5070_50701002_108_dialog_content = "Is it a ship that's stuck here too? Perfect, we can think of a way out together.",
  ui_story_5070_50701002_109_dialog_content = "Maybe we can trade some food and water with them too.",
  ui_story_5070_50701002_110_dialog_content = "Then, let's get back to the ship and figure it out.",
  ui_story_5070_50701002_111_dialog_content = "I've got eyes on them. They're clearly approaching the Shadowind.",
  ui_story_5070_50701002_112_dialog_content = "Uh... Aren't they going a little fast?",
  ui_story_5070_50701002_113_dialog_content = "They're not just failing to decelerate, but actually speeding up?!",
  ui_story_5070_50701002_114_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5070_50701002_115_dialog_content = "How... How could that ship just ram the Shadowind?!",
  ui_story_5070_50701002_116_dialog_content = "Oh no...",
  ui_story_5070_50701002_117_dialog_content = "It's a pirate boat!",
  ui_story_5070_50701002_118_dialog_content = "Hurry, PlayerName, Shadowind's in trouble!",
  ui_story_5070_50701101_1_dialog_content = "Why you insolent hoodlums! How dare you do to Jiu...",
  ui_story_5070_50701101_2_dialog_content = "Wait!",
  ui_story_5070_50701101_3_dialog_content = "<color=#e8d9bb>Swoosh—</color>",
  ui_story_5070_50701101_4_dialog_content = "<color=#e8d9bb>The deck at Dantang's feet is hit, burning a large hole.</color>",
  ui_story_5070_50701101_5_dialog_content = "...",
  ui_story_5070_50701101_6_dialog_content = "Your Highness, I know it's not my place to say this; I venture to remind you...",
  ui_story_5070_50701101_7_dialog_content = "It might feel good winning a verbal fight, but at sea, it's better to be safe than sorry.",
  ui_story_5070_50701101_8_dialog_content = "It seems like Dantang's being attacked! Let's get up there quickly—",
  ui_story_5070_50701101_9_dialog_content = "Wait, they know who we are, so I don't think anything bad will happen to the princess and Jiu.",
  ui_story_5070_50701101_10_dialog_content = "But we don't know what they're up to yet, so we'll only get captured if we go up now.",
  ui_story_5070_50701101_11_dialog_content = "Just stay hidden and figure out the situation before making a move.",
  ui_story_5070_50701101_12_dialog_content = "Hmm... The voice of whoever was just speaking to Dantang seemed a little familiar?",
  ui_story_5070_50701101_13_dialog_content = "That's Sun the Skillful.",
  ui_story_5070_50701101_14_dialog_content = "Him?!",
  ui_story_5070_50701101_15_dialog_content = "Shhh.",
  ui_story_5070_50701101_16_dialog_content = "Keep listening.",
  ui_story_5070_50701101_17_dialog_content = "You're not the real Sun the Skillful, right?",
  ui_story_5070_50701101_18_dialog_content = "Heh, Sun the Skillful is nothing but a facade.",
  ui_story_5070_50701101_19_dialog_content = "But for lowly folks like you, you only get to know me as Sun the Skillful.",
  ui_story_5070_50701101_20_dialog_content = "You... Can't believe you actually colluded with pirates!",
  ui_story_5070_50701101_21_dialog_content = "Have you forgotten the Lin family's favor to us? You treacherous traitor...",
  ui_story_5070_50701101_22_dialog_content = "Shut it!",
  ui_story_5070_50701101_23_dialog_content = "Keep it down if you don't want to get drowned down there alongside Miss Jiu.",
  ui_story_5070_50701101_24_dialog_content = "Keep in mind: the most skilled warrior on this ship has already kicked the bucket.",
  ui_story_5070_50701101_25_dialog_content = "I reckon there's not much room for a struggle on your end.",
  ui_story_5070_50701101_26_dialog_content = "That's because you resorted to deplorable tactics!",
  ui_story_5070_50701101_27_dialog_content = "Jiu wouldn't be at a disadvantage without that peculiar ray!",
  ui_story_5070_50701101_28_dialog_content = "Resorting to insults, huh? Princess, I really suggest you watch your tongue.",
  ui_story_5070_50701101_29_dialog_content = "That's a marvelous mechanical creation on par with... No, it totally outshines the Shadowind!",
  ui_story_5070_50701101_30_dialog_content = "Anybody can brag.",
  ui_story_5070_50701101_31_dialog_content = "How honorable can you be to hide in your boat and only waylaid from afar?",
  ui_story_5070_50701101_32_dialog_content = "(That's right, Princess Dantang. Keep aggravating him intentionally.)",
  ui_story_5070_50701101_33_dialog_content = "(We need to obtain as much information as we can before Jiu and the others return.)",
  ui_story_5070_50701101_34_dialog_content = "Other than launching a sneak attack, all your men have done after boarding our ship is capture Zhong Xu and Liqing.",
  ui_story_5070_50701101_35_dialog_content = "You're a group of cowards who only dare to target a disabled man and a child.",
  ui_story_5070_50701101_36_dialog_content = "Let's split up.",
  ui_story_5070_50701101_37_dialog_content = "That creation obviously has a powerful output to project the lethal ray.",
  ui_story_5070_50701101_38_dialog_content = "I gotta go take a closer look.",
  ui_story_5070_50701101_39_dialog_content = "Me?",
  ui_story_5070_50701101_40_dialog_content = "Stay on the boat and keep an eye out on Shadowind.",
  ui_story_5070_50701101_41_dialog_content = "Be sure to keep yourself hidden. I gotta go—",
  ui_story_5070_50701101_42_dialog_content = "This isn't called division of labor.",
  ui_story_5070_50701101_43_dialog_content = "?",
  ui_story_5070_50701101_44_dialog_content = "This is just leaving me somewhere safe, while you take the risks.",
  ui_story_5070_50701101_45_dialog_content = "Somehow...",
  ui_story_5070_50701101_46_dialog_content = "But time is precious.",
  ui_story_5070_50701101_47_dialog_content = "I want to go back to the Shadowind. While I can't fight like you...",
  ui_story_5070_50701101_48_dialog_content = "There must be something I can do up there.",
  ui_story_5070_50701101_49_dialog_content = "Even if you're discovered, I might be able to buy you some time.",
  ui_story_5070_50701101_50_dialog_content = "THIS is called division of labor.",
  ui_story_5070_50701101_51_dialog_content = "What if I reject that idea?",
  ui_story_5070_50701101_52_dialog_content = "So I'll wait for you to go, then sneak onto the ship.",
  ui_story_5070_50701101_53_dialog_content = "Don't tell me going headlong into danger is a Caelestite trait.",
  ui_story_5070_50701101_54_dialog_content = "Is wanting to protect everyone behind them, and do everything themselves, an artisan thing?",
  ui_story_5070_50701101_55_dialog_content = "I guess that makes us one and the same.",
  ui_story_5070_50701101_56_dialog_content = "You trust me, PlayerName...",
  ui_story_5070_50701101_57_dialog_content = "So if I don't trust you in return, PlayerName, that's rather unfair.",
  ui_story_5070_50701101_58_dialog_content = "Well then, good luck.",
  ui_story_5070_50701102_1_dialog_content = "Force Boost! Thought of something you forgot—",
  ui_story_5070_50701102_2_dialog_content = "Hey! Has the boss forgotten about my bounty? Gotta go remind him...",
  ui_story_5070_50701102_3_dialog_content = "<color=#e8d9bb>Thud, thud, thud!</color>",
  ui_story_5070_50701102_4_dialog_content = "(Great, these Longzhou pirates don't have any knowledge or experience of Caelestite's telepathic abilities.)",
  ui_story_5070_50701102_5_dialog_content = "(So I can quietly nudge like this, suggesting that those who are worried could get out of there for a while...)",
  ui_story_5070_50701102_6_dialog_content = "Why's the guy at the door gone? Are we still patrolling or what?",
  ui_story_5070_50701102_7_dialog_content = "It's all right. It won't mess with our task anyway.",
  ui_story_5070_50701102_8_dialog_content = "We're just keeping an eye on a cripple and a kid, both in cages. Do you really have to be so on edge?",
  ui_story_5070_50701102_9_dialog_content = "(So many pirates! And in the mechanical cage... Zhong Xu and Liqing?!)",
  ui_story_5070_50701102_10_dialog_content = "(Eh? What's Liqing doing?)",
  ui_story_5070_50701102_11_dialog_content = "*Sniffs...*",
  ui_story_5070_50701102_12_dialog_content = "(This smells like... PlayerName!)",
  ui_story_5070_50701102_13_dialog_content = "(Here! Look over here—! Our eyes met!)",
  ui_story_5070_50701102_14_dialog_content = "Meow...",
  ui_story_5070_50701102_15_dialog_content = "What are you doing? Trying to meow like a cat?",
  ui_story_5070_50701102_16_dialog_content = "I'm bored. You can't let me go out for a walk now, can you?",
  ui_story_5070_50701102_17_dialog_content = "(What does Liqing mean?)",
  ui_story_5070_50701102_18_dialog_content = "Meow...",
  ui_story_5070_50701102_19_dialog_content = "(Tinytail! And next to Zhong Xu... That's Yixin, Yimeng, and Yinuo, right?)",
  ui_story_5070_50701102_20_dialog_content = "(Where did they come from?)",
  ui_story_5070_50701102_21_dialog_content = "Do you hear it?! Is there something going on at the door?",
  ui_story_5070_50701102_22_dialog_content = "Nah, you probably misheard.",
  ui_story_5070_50701102_23_dialog_content = "First, you said the red-haired cripple seemed familiar, and now you're saying something is going on at the door. Come on, can you give me a break?",
  ui_story_5070_50701102_24_dialog_content = "I'll go check it out.",
  ui_story_5070_50701102_25_dialog_content = "(!!!)",
  ui_story_5070_50701102_26_dialog_content = "(No time to hide. I only get one shot at this!)",
  ui_story_5070_50701102_27_dialog_content = "Please, help me buy some time!",
  ui_story_5070_50701102_28_dialog_content = "Meow!",
  ui_story_5070_50701102_29_dialog_content = "What is that?!",
  ui_story_5070_50701102_30_dialog_content = "Where the heck did this wild cat come from? Get lost! Hiss... and it actually bites!",
  ui_story_5070_50701102_31_dialog_content = "(Now's the time, for everyone in the room...)",
  ui_story_5070_50701102_32_dialog_content = "Provoke them with Force Boost!",
  ui_story_5070_50701102_33_dialog_content = "Ah—why is my head suddenly throbbing in pain?!",
  ui_story_5070_50701102_34_dialog_content = "Cat—! A cat is scratching my face!",
  ui_story_5070_50701102_35_dialog_content = "PlayerName! Rescue Zhong Xu first!",
  ui_story_5070_50701102_36_dialog_content = "Meow...",
  ui_story_5070_50701102_37_dialog_content = "You brought the key? Thanks, Tinytail.",
  ui_story_5070_50701102_38_dialog_content = "Hang on, Zhong Xu. I'm unlocking it right now.",
  ui_story_5070_50701102_39_dialog_content = "Thanks, but you don't need to rush because I'm fine.",
  ui_story_5070_50701102_40_dialog_content = "You may not be worried, but I am! You're too slow, PlayerName! I'll do it!",
  ui_story_5070_50701102_41_dialog_content = "Liqing?! How'd you get out?",
  ui_story_5070_50701102_42_dialog_content = "The gaps in this cage are so huge! Can't you just squeeze through sideways?!",
  ui_story_5070_50701102_43_dialog_content = "Is that something ordinary Aurorians can do...?",
  ui_story_5070_50701102_44_dialog_content = "Normal Aurorians can't, but I'm not an ordinary Aurorian.",
  ui_story_5070_50701102_45_dialog_content = "Not ordinary?!",
  ui_story_5070_50701102_46_dialog_content = "Didn't I tell you?",
  ui_story_5070_50701102_47_dialog_content = "I'm a cat.",
  ui_story_5070_50701102_48_dialog_content = "?!",
  ui_story_5070_50701102_49_dialog_content = "To be precise, I'm a cat Fiendling. Tinytail over there is my older sibling.",
  ui_story_5070_50701102_50_dialog_content = "B-Brother...",
  ui_story_5070_50701102_51_dialog_content = "PlayerName? What's wrong?",
  ui_story_5070_50701102_52_dialog_content = "There are no Fiendlings in Astra, so I can see why you're so shocked.",
  ui_story_5070_50701102_53_dialog_content = "Zhong Xu...",
  ui_story_5070_50701102_54_dialog_content = "What is it?",
  ui_story_5070_50701102_55_dialog_content = "You've got three cats around you, but... you can't be a Fiendling, right?",
  ui_story_5070_50701102_56_dialog_content = "You're not suddenly gonna turn into a cat too?",
  ui_story_5070_50701102_57_dialog_content = "Hahaha! I really am just an ordinary person, so I'm afraid you'll be disappointed.",
  ui_story_5070_50701102_58_dialog_content = "No, no! Better to say it's great... And it's still the same old ordinary, reliable Zhong Xu.",
  ui_story_5070_50701102_59_dialog_content = "Ugh... you, you all...",
  ui_story_5070_50701102_60_dialog_content = "PlayerName, these scoundrels are back to their senses.",
  ui_story_5070_50701102_61_dialog_content = "And it's not just them. A group is approaching the entrance. They should be coming from the deck.",
  ui_story_5070_50701102_62_dialog_content = "Surround them!",
  ui_story_5070_50701102_63_dialog_content = "The only capable fighter here is the cripple, but he's only skilled with Flame Force Arts.",
  ui_story_5070_50701102_64_dialog_content = "As long as we stifle his flames, he's useless.",
  ui_story_5070_50701102_65_dialog_content = "These guys!",
  ui_story_5070_50701102_66_dialog_content = "Wait, Zhong Xu. Make sure you're safe first, while Liqing and I come up with a plan.",
  ui_story_5070_50701102_67_dialog_content = "Huh? PlayerName, you didn't know? Actually...",
  ui_story_5070_50701102_68_dialog_content = "I appreciate your good intentions.",
  ui_story_5070_50701102_69_dialog_content = "The Lin Guildsmaster... He was weak and frail, but he always protected me like this.",
  ui_story_5070_50701102_70_dialog_content = "I've had dealings with these people for many years now, so I guess it's fate that I've been captured here.",
  ui_story_5070_50701102_71_dialog_content = "Maybe even the heavens believe it's time for me to settle things with these pirates once and for all.",
  ui_story_5070_50701102_72_dialog_content = "So can you please wait a moment and leave these enemies to me?",
  ui_story_5070_50701102_73_dialog_content = "Okay. I'll do my best to support—",
  ui_story_5070_50701102_74_dialog_content = "That won't be necessary. Your strange powers are probably more helpful to Princess Dantang and Ministress Armilla.",
  ui_story_5070_50701102_75_dialog_content = "As for me, I only know one way to fight, and I only need this one way of fighting.",
  ui_story_5070_50701102_76_dialog_content = "If you really want to help me, then hand me my sword that was taken earlier.",
  ui_story_5070_50701102_77_dialog_content = "Alright, it's this one, isn't it...? It's heavy!",
  ui_story_5070_50701102_78_dialog_content = "Thanks.",
  ui_story_5070_50701102_79_dialog_content = "(The instant he took the sword, Zhong Xu's eyes seemed to change.)",
  ui_story_5070_50701102_80_dialog_content = "Hah, what's this cripple blabbering about? He actually thinks he can handle us all on his own!?",
  ui_story_5070_50701102_81_dialog_content = "He's in way over his head—",
  ui_story_5070_50701102_82_dialog_content = "<color=#e8d9bb>Swish!</color>",
  ui_story_5070_50701102_83_dialog_content = "Ugh...",
  ui_story_5070_50701102_84_dialog_content = "<color=#e8d9bb>The arrogant smile had yet to fade from his face, but the pirate's body had already fallen to the ground.</color>",
  ui_story_5070_50701102_85_dialog_content = "What... what did he just do?",
  ui_story_5070_50701102_86_dialog_content = "Don't panic! He's just quick with his sword! There are so many of us—Ah!",
  ui_story_5070_50701102_87_dialog_content = "Instead of giving me this unseemly compliment, I would prefer it if you just fell over.",
  ui_story_5070_50701102_88_dialog_content = "Hey! Who said everything would be fine as long as we keep his fire in check?",
  ui_story_5070_50701102_89_dialog_content = "This guy... He didn't even use his fire at all!",
  ui_story_5070_50701102_90_dialog_content = "The momentum of the pirates was suppressed by Zhong Xu alone.",
  ui_story_5070_50701102_91_dialog_content = "Of course, we're talking about Zhong Xu here!",
  ui_story_5070_50701102_92_dialog_content = "Go... GO TO HELL!",
  ui_story_5070_50701102_93_dialog_content = "Zhong Xu! Behind you!",
  ui_story_5070_50701102_94_dialog_content = "<color=#e8d9bb>Swish!</color>",
  ui_story_5070_50701102_95_dialog_content = "Ahhh!",
  ui_story_5070_50701102_96_dialog_content = "My worry was in vain, as Zhong Xu drew his sword faster than I could shout.",
  ui_story_5070_50701102_97_dialog_content = "See? Even in a wheelchair, this ragtag bunch is nothing to Zhong Xu.",
  ui_story_5070_50701102_98_dialog_content = "The shipwreck took my legs from me.",
  ui_story_5070_50701102_99_dialog_content = "<color=#e8d9bb>Swish!</color>",
  ui_story_5070_50701102_100_dialog_content = "And you can also try to suppress my blazing flames.",
  ui_story_5070_50701102_101_dialog_content = "<color=#e8d9bb>Swish!</color>",
  ui_story_5070_50701102_102_dialog_content = "But as long as I still have an arm and a sword.",
  ui_story_5070_50701102_103_dialog_content = "<color=#e8d9bb>Swish!</color>",
  ui_story_5070_50701102_104_dialog_content = "I will continue to swing my sword and kill enemies.",
  ui_story_5070_50701102_105_dialog_content = "This is the only way of fighting that I know.",
  ui_story_5070_50701102_106_dialog_content = "Monster... A freakin' monster—!",
  ui_story_5070_50701102_107_dialog_content = "People often called me that many years ago.",
  ui_story_5070_50701102_108_dialog_content = "You... Wait, don't tell me...",
  ui_story_5070_50701102_109_dialog_content = "I remember now!",
  ui_story_5070_50701102_110_dialog_content = "Red hair and a long robe.",
  ui_story_5070_50701102_111_dialog_content = "With only a sword, he can clear out a ship full of pirates single-handedly.",
  ui_story_5070_50701102_112_dialog_content = "The general who wiped out the last group of pirates dominating the waters around the Ji Kingdom... it's you!",
  ui_story_5070_50701102_113_dialog_content = "The Grand General personally honored by the Emperor!",
  ui_story_5070_50701102_114_dialog_content = "That's all in the past now.",
  ui_story_5070_50701102_115_dialog_content = "<color=#e8d9bb>Swish—</color>",
  ui_story_5070_50701102_116_dialog_content = "<color=#e8d9bb>The last enemy collapses to the ground.</color>",
  ui_story_5070_50701102_117_dialog_content = "I'm just a wanderer now...",
  ui_story_5070_50701102_118_dialog_content = "Or a middle-aged man who can provide some help to youngsters.",
  ui_story_5070_50701201_1_dialog_content = "<color=#e8d9bb>Meanwhile in the enemy ship</color>",
  ui_story_5070_50701201_2_dialog_content = "(This ship is built like the Shadowind?!)",
  ui_story_5070_50701201_3_dialog_content = "<color=#e8d9bb>Whoosh—</color>",
  ui_story_5070_50701201_4_dialog_content = "!",
  ui_story_5070_50701201_5_dialog_content = "I should feel honored to be greeted in such a way.",
  ui_story_5070_50701201_6_dialog_content = "It's obviously a scorpion stinger, yet it's not shooting toxins...",
  ui_story_5070_50701201_7_dialog_content = "But Lumina ray of the Astra people?",
  ui_story_5070_50701201_8_dialog_content = "Graagh!",
  ui_story_5070_50701201_9_dialog_content = "The tail is a lance, the pincers are blades, with thick metal for carapace...",
  ui_story_5070_50701201_10_dialog_content = "Full activation!",
  ui_story_5070_50701201_11_dialog_content = "<color=#e8d9bb>Ding—</color>",
  ui_story_5070_50701201_12_dialog_content = "Sounds like stone yet light as jade.",
  ui_story_5070_50701201_13_dialog_content = "No sign of damage from the barrage. I guess it's made of rare materials.",
  ui_story_5070_50701201_14_dialog_content = "You know...",
  ui_story_5070_50701201_15_dialog_content = "Clickity-clack...",
  ui_story_5070_50701201_16_dialog_content = "This thing must consume a lot of power.",
  ui_story_5070_50701201_17_dialog_content = "But it hasn't gotten weaker and even grew stronger after all this fighting.",
  ui_story_5070_50701201_18_dialog_content = "How amazing its core must be... There can't be more than a few in the world.",
  ui_story_5070_50701201_19_dialog_content = "What a coincidence though, that there's another one on Shadowind.",
  ui_story_5070_50701201_20_dialog_content = "If I take this monster apart, will I find the power source...",
  ui_story_5070_50701201_21_dialog_content = "To be another Zhuyin Flame?",
  ui_story_5070_50701201_22_dialog_content = "You probably can't even break it apart.",
  ui_story_5070_50701201_23_dialog_content = "Ah, finally showing yourself.",
  ui_story_5070_50701201_24_dialog_content = "First, you impersonated Sun, then you sent this big ugly oaf at me.",
  ui_story_5070_50701201_25_dialog_content = "I was starting to think you only did things when you had something to hide behind.",
  ui_story_5070_50701201_26_dialog_content = "Heh, I won't bother squabbling with you.",
  ui_story_5070_50701201_27_dialog_content = "After all, the loser's sharp words only mean powerlessness.",
  ui_story_5070_50701201_28_dialog_content = "Loser? You got it the other way around.",
  ui_story_5070_50701201_29_dialog_content = "The reason is that you were certain of your inferiority and convinced yourself that you were the loser.",
  ui_story_5070_50701201_30_dialog_content = "You planned and schemed to get what belonged to other people.",
  ui_story_5070_50701201_31_dialog_content = "You first stole the blueprint for the Fire Crab.",
  ui_story_5070_50701201_32_dialog_content = "Then moved on to smuggling parts and led the pirates to plunder the Lin trader.",
  ui_story_5070_50701201_33_dialog_content = "Now you used the same trick to pilfer the Zhuyin Flame for your grotesque patchwork.",
  ui_story_5070_50701201_34_dialog_content = "I do have a question though.",
  ui_story_5070_50701201_35_dialog_content = "Let's hear it.",
  ui_story_5070_50701201_36_dialog_content = "Qianyun has always taken pride in being upright and having a sterling reputation.",
  ui_story_5070_50701201_37_dialog_content = "So when did it promote theft and underhanded tactics like this?",
  ui_story_5070_50701201_38_dialog_content = "Ha...",
  ui_story_5070_50701201_39_dialog_content = "Oh, you've recognized me.",
  ui_story_5070_50701201_40_dialog_content = "But all you ever care about is mechanics. I wonder if my face still rings a bell.",
  ui_story_5070_50701201_41_dialog_content = "It's been a while, Xuan Ji... my junior sister.",
  ui_story_5070_50701201_42_dialog_content = "Zhui Hu.",
  ui_story_5070_50701201_43_dialog_content = "Can't even address me as \"senior sister,\" huh? The illustrious Ministress Armilla is indeed different from the past.",
  ui_story_5070_50701201_44_dialog_content = "You've long been expelled and not fit to call yourself anything.",
  ui_story_5070_50701201_45_dialog_content = "Heh, sharp words again... You know what? I'll let it slide this time.",
  ui_story_5070_50701201_46_dialog_content = "After all, you've been considered a genius by the sect since childhood, always having things go your way. But now, you have no way to handle the works of an abandoned disciple...",
  ui_story_5070_50701201_47_dialog_content = "It must sting a little.",
  ui_story_5070_50701201_48_dialog_content = "But it's okay. While you may not care about our old times, I do.",
  ui_story_5070_50701201_49_dialog_content = "So, given our shared past growing up in the sect, if you honestly admit defeat, I'm willing to let you go.",
  ui_story_5070_50701201_50_dialog_content = "Junior sister, you might not know this... but the era of the strategists is about to dawn!",
  ui_story_5070_50701201_51_dialog_content = "In the ever-changing political landscape of the eight vassal kingdoms in the future, talents like you will always find a foothold.",
  ui_story_5070_50701201_52_dialog_content = "This ship beneath your feet. Consider it my parting gift to you. How about that?",
  ui_story_5070_50701201_53_dialog_content = "Of course.",
  ui_story_5070_50701201_54_dialog_content = "You're not just after the Zhuyin Flame but Shadowind too.",
  ui_story_5070_50701201_55_dialog_content = "It's not like you wouldn't just strand me at sea to die.",
  ui_story_5070_50701201_56_dialog_content = "Truly, I can't hide anything from your discerning eyes.",
  ui_story_5070_50701201_57_dialog_content = "Since this ship is a copy of the Shadowind, though only in appearance and nowhere comparable.",
  ui_story_5070_50701201_58_dialog_content = "After all, the core of the Shadowind was created through the combined efforts of many experts. It's hard for me to replicate it alone.",
  ui_story_5070_50701201_59_dialog_content = "Actually, my original mission was just to acquire the blueprints of the Shadowind.",
  ui_story_5070_50701201_60_dialog_content = "But since there's a chance to take the whole ship, why not?",
  ui_story_5070_50701201_61_dialog_content = "Although the current Shadowind is messed up due to your whimsical alterations...",
  ui_story_5070_50701201_62_dialog_content = "But I don't mind taking on this mess.",
  ui_story_5070_50701201_63_dialog_content = "(Mission, you said...)",
  ui_story_5070_50701201_64_dialog_content = "Compared to chatting with those stubborn local youngsters in the dungeon, this way of doing things is much more satisfying.",
  ui_story_5070_50701201_65_dialog_content = "So you masterminded the Lin ship robbery too?",
  ui_story_5070_50701201_66_dialog_content = "Quick on the uptake, aren't you?",
  ui_story_5070_50701201_67_dialog_content = "With this convenient technique of disguise and mimicry...",
  ui_story_5070_50701201_68_dialog_content = "It was just a piece of cake to pose as a passenger or a shipworker and break down the ship's defenses from the inside.",
  ui_story_5070_50701201_69_dialog_content = "I've made meticulous preparations in the Twin Pavilions Bay, hoping to reenact what happened on the Shadowind...",
  ui_story_5070_50701201_70_dialog_content = "Until I discovered that there was something special hidden in the cabin.",
  ui_story_5070_50701201_71_dialog_content = "I never expected that you, my dear junior sister, could actually find the legendary Zhuyin Flame.",
  ui_story_5070_50701201_72_dialog_content = "And since I crafted this clockwork beast, a pinnacle creation incorporating the strengths of all schools, I haven't been able to find a suitable power source.",
  ui_story_5070_50701201_73_dialog_content = "It may look like a coincidence, but to me, it's the favor of fate!",
  ui_story_5070_50701201_74_dialog_content = "Sigh...",
  ui_story_5070_50701201_75_dialog_content = "... What do you mean by that?",
  ui_story_5070_50701201_76_dialog_content = "You've never changed.",
  ui_story_5070_50701201_77_dialog_content = "At this point, why are you still trying to act like the genius of our sect and the master of machinery?",
  ui_story_5070_50701201_78_dialog_content = "Haven't you come to terms with reality yet, junior sister?",
  ui_story_5070_50701201_79_dialog_content = "Not even you can leave a scratch on my clockwork beast, my greatest creation!",
  ui_story_5070_50701201_80_dialog_content = "\"Your\" clockwork beast?",
  ui_story_5070_50701201_81_dialog_content = "You merely copied the design, stole the core and put powerful parts together.",
  ui_story_5070_50701201_82_dialog_content = "Is there anything original in that work of \"yours\"?",
  ui_story_5070_50701201_83_dialog_content = "Why are you sounding just like those rigid old-timers from the sect?",
  ui_story_5070_50701201_84_dialog_content = "The art of machinery is just a technical skill; as long as the creation itself is strong enough, there's no need to worry about anything else.",
  ui_story_5070_50701201_85_dialog_content = "Even if it's them, in the face of my perfected Stinger, they'll have no choice but to bow down in defeat!",
  ui_story_5070_50701201_86_dialog_content = "That's why our masters said you never grasped the meaning of gadgetry.",
  ui_story_5070_50701201_87_dialog_content = "If they saw you now, they'd probably regret the fact they can't kick you out for a second time.",
  ui_story_5070_50701201_88_dialog_content = "...I shouldn't have wasted so much time trying to talk sense into you.",
  ui_story_5070_50701201_89_dialog_content = "Crush her, Stinger. Show her the true power a Clockwork Beast should have!",
  ui_story_5070_50701201_90_dialog_content = "The pirates on the Shadowind have finally been dealt with. Is everyone alright?",
  ui_story_5070_50701201_91_dialog_content = "We're basically okay, but some of our shipwrights are injured and some of our passengers are missing.",
  ui_story_5070_50701201_92_dialog_content = "Jiu fell overboard from her wounds and still no signs of her yet...",
  ui_story_5070_50701201_93_dialog_content = "Your Highness! Are you all right?",
  ui_story_5070_50701201_94_dialog_content = "Jiu! Why are you worried about me? How hurt are you?",
  ui_story_5070_50701201_95_dialog_content = "I just accidentally swallowed a few mouthfuls of water.",
  ui_story_5070_50701201_96_dialog_content = "But I failed my duty as your bodyguard by leaving your side at this time. Please punish me.",
  ui_story_5070_50701201_97_dialog_content = "Stop it. You could have evaded the ray if not for protecting me...",
  ui_story_5070_50701201_98_dialog_content = "How can I even berate you? Come examine Jiu, Liqing...",
  ui_story_5070_50701201_99_dialog_content = "Thank you.",
  ui_story_5070_50701201_100_dialog_content = "With Jiu back, that leaves only Ministress Armilla...",
  ui_story_5070_50701201_101_dialog_content = "Xuan Ji's probably on that ship opposite.",
  ui_story_5070_50701201_102_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5070_50701201_103_dialog_content = "It's that peculiar glow again...",
  ui_story_5070_50701201_104_dialog_content = "Alright, let's see.",
  ui_story_5070_50701201_105_dialog_content = "What is she even fighting?! Why is she just dodging without counterattacking?!",
  ui_story_5070_50701201_106_dialog_content = "I can't take this anymore! Zhong Xu, let's give her some help.",
  ui_story_5070_50701201_107_dialog_content = "If I save her in the nick of time, she would be too ashamed to call me tiny again!",
  ui_story_5070_50701201_108_dialog_content = "Perhaps it won't be necessary.",
  ui_story_5070_50701201_109_dialog_content = "No way... Did she offend you too? You're really planning to let her die?",
  ui_story_5070_50701201_110_dialog_content = "What I'm saying is that Ministress Armilla doesn't need our help.",
  ui_story_5070_50701201_111_dialog_content = "Yep. She didn't seem to be running around everywhere just to hide.",
  ui_story_5070_50701201_112_dialog_content = "I think she was intentionally using the attacks from the opposite side to wreck her surroundings.",
  ui_story_5070_50701201_113_dialog_content = "She wants to destroy that Clockwork Beast's shelter!",
  ui_story_5070_50701201_114_dialog_content = "But why would she do that?",
  ui_story_5070_50701201_115_dialog_content = "I don't know... Actually, maybe I do.",
  ui_story_5070_50701201_116_dialog_content = "So even if you fortify Shadowind with every last material you can scrounge up...",
  ui_story_5070_50701201_117_dialog_content = "It's not gonna stand up to the Zhuyin Flame at full power.",
  ui_story_5070_50701201_118_dialog_content = "Ignoring the large hole on the deck is one thing, but deliberately making it bigger?",
  ui_story_5070_50701201_119_dialog_content = "It's almost exposing the core of the Shadowind. That's just too bizarre... Sun, what do you think of it?",
  ui_story_5070_50701201_120_dialog_content = "Please keep the failed experiment and someone eyeing the Flame a secret.",
  ui_story_5070_50701201_121_dialog_content = "Maybe... But what should we do now?",
  ui_story_5070_50701201_122_dialog_content = "Just wait.",
  ui_story_5070_50701201_123_dialog_content = "(...No way.)",
  ui_story_5070_50701201_124_dialog_content = "(If it's what I think it is, Xuan Ji, you've got no right to call me reckless anymore.)",
  ui_story_5070_50701201_125_dialog_content = "(You'd be the biggest daredevil on board!)",
  ui_story_5070_50701201_126_dialog_content = "What are you looking at, PlayerName? Is there something within that huge hole on deck?",
  ui_story_5070_50701201_127_dialog_content = "Not right now.",
  ui_story_5070_50701201_128_dialog_content = "But there will be imminently.",
  ui_story_5070_50701201_129_dialog_content = "Everyone! Give me a hand!",
  ui_story_5070_50701201_130_dialog_content = "We need to lure those Clockwork Beasts onto the Shadowind!",
  ui_story_5070_50701201_131_dialog_content = "Lightning Flash—",
  ui_story_5070_50701201_132_dialog_content = "Told you it's pointless, didn't I?",
  ui_story_5070_50701201_133_dialog_content = "Every part of Stinger is crafted with the top-notch designs I found all around the world.",
  ui_story_5070_50701201_134_dialog_content = "All your attacks are futile!",
  ui_story_5070_50701201_135_dialog_content = "I'm not sure about that.",
  ui_story_5070_50701201_136_dialog_content = "?!",
  ui_story_5070_50701201_137_dialog_content = "PlayerName? If you can mindlink my way, you must have done well on your end.",
  ui_story_5070_50701201_138_dialog_content = "Haha... Thanks, Zhong Xu. But we can discuss this later.",
  ui_story_5070_50701201_139_dialog_content = "I heard what you were saying just now. Turns out the explosion that day was caused by this imposter Sun the Skillful.",
  ui_story_5070_50701201_140_dialog_content = "Struck by lightning for stealing. People from Longzhou would call that divine retribution.",
  ui_story_5070_50701201_141_dialog_content = "She actually thinks it's fate? I wouldn't want that kind of lightning strike.",
  ui_story_5070_50701201_142_dialog_content = "Not me either!",
  ui_story_5070_50701201_143_dialog_content = "Besides, her clockwork beast is too ugly. All that twisting around is just disgusting!",
  ui_story_5070_50701201_144_dialog_content = "I did say it was one big ugly mess.",
  ui_story_5070_50701201_145_dialog_content = "... I never thought that the Shadowind would be compared with something like that.",
  ui_story_5070_50701201_146_dialog_content = "... That's enough!",
  ui_story_5070_50701201_147_dialog_content = "Stinger! Head to the Shadowind and take out all these ignorant fools!",
  ui_story_5070_50701202_1_dialog_content = "My... most powerful clockwork beast... How could this happen...",
  ui_story_5070_50701202_2_dialog_content = "You—!",
  ui_story_5070_50701202_3_dialog_content = "Gonna keep this up? I don't recall you being a good fighter.",
  ui_story_5070_50701202_4_dialog_content = "Ha... Haha, hahaha!",
  ui_story_5070_50701202_5_dialog_content = "Don't get too excited yet! Senior Sister, you shouldn't have forgotten what powers my Stinger, right?",
  ui_story_5070_50701202_6_dialog_content = "Zhuyin Flame! It's the true art of craftsmanship that provides endless energy to mechanical creations!",
  ui_story_5070_50701202_7_dialog_content = "Get up, Stinger! The battle isn't over yet!",
  ui_story_5070_50701202_8_dialog_content = "Watch out, everyone! The big guy's moving again!",
  ui_story_5070_50701202_9_dialog_content = "So things aren't over yet. Your Highness, please step back.",
  ui_story_5070_50701202_10_dialog_content = "You're the one celebrating prematurely.",
  ui_story_5070_50701202_11_dialog_content = "That look again... Don't you ever give me that superior look! I—",
  ui_story_5070_50701202_12_dialog_content = "PlayerName, try to hold her still! I just need a bit of time!",
  ui_story_5070_50701202_13_dialog_content = "Force Boost!",
  ui_story_5070_50701202_14_dialog_content = "Ugh—!",
  ui_story_5070_50701202_15_dialog_content = "I'll make her briefly dizzy, and you guys push the beast inside now!",
  ui_story_5070_50701202_16_dialog_content = "Push it? Push it where? The hole on deck?!",
  ui_story_5070_50701202_17_dialog_content = "That's not just a hole.",
  ui_story_5070_50701202_18_dialog_content = "I made that just for it.",
  ui_story_5070_50701202_19_dialog_content = "One... Two... Three!",
  ui_story_5070_50701202_20_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5070_50701202_21_dialog_content = "We did it! That guy was really heavy.",
  ui_story_5070_50701202_22_dialog_content = "I'll take over from here.",
  ui_story_5070_50701202_23_dialog_content = "With some modifications, we can hook it up to the Shadowind.",
  ui_story_5070_50701202_24_dialog_content = "Ugh... Wh-what are you going to do...!",
  ui_story_5070_50701202_25_dialog_content = "I'm sure you saw my draft of changes for the Shadowind in your Sun disguise, right?",
  ui_story_5070_50701202_26_dialog_content = "Don't joke around... It's not even possible...",
  ui_story_5070_50701202_27_dialog_content = "To support a sizeable ship like Shadowind with such a structure...",
  ui_story_5070_50701202_28_dialog_content = "It requires a core with the same power level as the Zhuyin Flame in full throttle.",
  ui_story_5070_50701202_29_dialog_content = "With the materials of the Shadowind alone, it can't even withstand the impact...",
  ui_story_5070_50701202_30_dialog_content = "You're right, it's a pipe dream on that alone.",
  ui_story_5070_50701202_31_dialog_content = "But in order to create the most powerful clockwork beast...",
  ui_story_5070_50701202_32_dialog_content = "Didn't you use materials that could withstand the Zhuyin Flame at full power?",
  ui_story_5070_50701202_33_dialog_content = "Wait, you mean... Are you crazy?! It's absolutely...",
  ui_story_5070_50701202_34_dialog_content = "That's why I said you're too occupied with designs to understand gadgetry.",
  ui_story_5070_50701202_35_dialog_content = "As long as materials are available, gadgetry is limitless in what it can create.",
  ui_story_5070_50701202_36_dialog_content = "What are you talking about?",
  ui_story_5070_50701202_37_dialog_content = "Sit tight, little one. You'll find out soon.",
  ui_story_5070_50701202_38_dialog_content = "Immerse yourself with all your senses in this once-in-a-lifetime experience.",
  ui_story_5070_50701202_39_dialog_content = "I'm about to use the beast as the power source to regulate the Zhuyin Flame output.",
  ui_story_5070_50701202_X39_dialog_content = "And make the Shadowind...",
  ui_story_5070_50701202_40_dialog_content = "Take a short flight!",
  ui_story_5070_50701202_41_dialog_content = "<color=#e8d9bb>Blast of whistle</color>",
  ui_story_5070_50701202_42_dialog_content = "<color=#e8d9bb>Under Xuan Ji's command, those still able to move temporarily take on the duties of the shipwrights.</color>",
  ui_story_5070_50701202_43_dialog_content = "<color=#e8d9bb>With the sound of the whistle, all modified mechanisms on the Shadowind spring into action at once.</color>",
  ui_story_5070_50701202_44_dialog_content = "<color=#e8d9bb>The ship shakes, gears inside clashing and extending... Beams of Lumina unfurl on both sides of the ship like a multitude of wings!</color>",
  ui_story_5070_50701202_45_dialog_content = "Would you do the honor, PlayerName?",
  ui_story_5070_50701202_46_dialog_content = "Force Boost!",
  ui_story_5070_50701202_47_dialog_content = "(Sense the Zhuyin Flame and stimulate its power to the max! And then...)",
  ui_story_5070_50701202_48_dialog_content = "(Shadowind, move!)",
  ui_story_5070_50701202_49_dialog_content = "No way... No freakin' way!",
  ui_story_5070_50701202_50_dialog_content = "Damn... it's just a momentary stroke of luck! We... it's not over yet!",
  ui_story_5070_50701202_51_dialog_content = "<color=#e8d9bb>Plop!</color>",
  ui_story_5070_50701202_52_dialog_content = "She jumped into the sea!",
  ui_story_5070_50701202_53_dialog_content = "Never mind her.",
  ui_story_5070_50701202_54_dialog_content = "The wings can only support the ship for a limited time. We gotta take this opportunity and get out of here.",
  ui_story_5070_50701202_55_dialog_content = "<color=#e8d9bb>Creak—</color>",
  ui_story_5070_50701202_56_dialog_content = "(The Shadowind only stayed in the air briefly, and I could already hear the sound of overloaded machinery.)",
  ui_story_5070_50701202_57_dialog_content = "(With a final push, the thick light began to dissipate in mid-air.)",
  ui_story_5070_50701202_58_dialog_content = "(That will do.)",
  ui_story_5070_50701202_59_dialog_content = "The sun, a light breeze, and calm waves... We made it out!",
  ui_story_5070_50701202_60_dialog_content = "<color=#e8d9bb>Bang!!!</color>",
  ui_story_5070_50701202_61_dialog_content = "<color=#e8d9bb>The Shadowind crashes heavily back into the sea.</color>",
  ui_story_5070_50701202_62_dialog_content = "<color=#e8d9bb>But this time, the surroundings are calm, with no more whirlpools or hidden currents.</color>",
  ui_story_5070_50701202_63_dialog_content = "We did it!",
  ui_story_5070_50701202_64_dialog_content = "You're amazing, Xuan Ji!",
  ui_story_5070_50701202_65_dialog_content = "It's gadgetry that's great.",
  ui_story_5070_50701202_66_dialog_content = "But this time, I'll shelf the humility and accept your compliment.",
  ui_story_5070_50701202_67_dialog_content = "Speaking of which, while it may not have lasted long, the Shadowind had indeed soared across the sky.",
  ui_story_5070_50701202_68_dialog_content = "And this time, Xuan Ji had legitimately become the navigator of the Shadowind.",
  ui_story_5070_50701202_69_dialog_content = "I did, didn't I?",
  ui_story_5070_50701202_70_dialog_content = "I'll never forget that feeling.",
  ui_story_5070_50701202_71_dialog_content = "(After crossing the ocean, Xuan Ji quickly used the astrolabe and other equipment to help the Shadowind get back on course.)",
  ui_story_5070_50701202_72_dialog_content = "(The next day, we found the wreckage of Zhui Hu's ship not far away.)",
  ui_story_5070_50701202_73_dialog_content = "It sank in the sea just like the Lin Guild's ship that sunk due to her schemes. Cause and effect is at play here.",
  ui_story_5070_50701202_74_dialog_content = "But people like Zhui Hu and her supporters won't die so easily. Nor will they give up so easily.",
  ui_story_5070_50701202_75_dialog_content = "No one knows what other plans they'll hatch.",
  ui_story_5070_50701202_76_dialog_content = "Anyway, we'll find a way to deal with it. There's always a counter for any kind of enemy.",
  ui_story_5070_50701202_77_dialog_content = "Even if not, we can improvise on the spot.",
  ui_story_5070_50701202_78_dialog_content = "Wasn't Zhui Hu once your teacher, Xuan Ji?",
  ui_story_5070_50701202_79_dialog_content = "Even if she was expelled, she had at least been the disciple of a great sect.",
  ui_story_5070_50701202_80_dialog_content = "He had to be a lot stronger than normal people to come up with something like that.",
  ui_story_5070_50701202_81_dialog_content = "How could he have been hired to act as a pirate or smuggler?",
  ui_story_5070_50701202_82_dialog_content = "I have a clue.",
  ui_story_5070_50701202_83_dialog_content = "But I don't know whether it's good or bad to pursue that line of thinking.",
  ui_story_5070_50701202_84_dialog_content = "Zhui Hu learned a lot of techniques but never realized what gadgetry truly is.",
  ui_story_5070_50701202_85_dialog_content = "We're talking about the result of centuries of practice and determination.",
  ui_story_5070_50701202_86_dialog_content = "That can't be comprehended through subterfuge and thievery.",
  ui_story_5070_50701202_87_dialog_content = "I brought everything you asked for, Xuan Ji.",
  ui_story_5070_50701202_88_dialog_content = "But we only have these few envelopes for communicating with my great uncle left on this ship.",
  ui_story_5070_50701202_89_dialog_content = "What purpose do you have for them?",
  ui_story_5070_50701202_90_dialog_content = "Well, I'll figure it out when I see them.",
  ui_story_5070_50701202_91_dialog_content = "Oh, how is Jiu doing?",
  ui_story_5070_50701202_92_dialog_content = "I see you still care.",
  ui_story_5070_50701202_93_dialog_content = "Liqing examined her and she should fully recover in a few days.",
  ui_story_5070_50701202_94_dialog_content = "(The tone of the conversation changed back to its usual light and lively nature.)",
  ui_story_5070_50701202_95_dialog_content = "(I saw Xuan Ji carefully tuck away those letters...)",
  ui_story_5070_50701202_X95_dialog_content = "(Though she never answered the question, \"What's the use?\".)",
  ui_story_5070_50701301_1_dialog_content = "(The final two days aboard the ship flew by.)",
  ui_story_5070_50701301_2_dialog_content = "(Everyone was physically and mentally exhausted by all the crises and battles.)",
  ui_story_5070_50701301_3_dialog_content = "(Fortunately, just as the repairs were completed—Longzhou came into view.)",
  ui_story_5070_50701301_4_dialog_content = "This voyage was filled with many twists and turns, but everything turned out well.",
  ui_story_5070_50701301_5_dialog_content = "The Shadowind has returned. This voyage is officially over.",
  ui_story_5070_50701301_6_dialog_content = "On behalf of the Shadowind, I want to thank everyone for helping us along the way.",
  ui_story_5070_50701301_7_dialog_content = "Do not overlook your own merits in this.",
  ui_story_5070_50701301_8_dialog_content = "We arrived safely and reestablished the route. We and the Shadowind and have both completed our missions.",
  ui_story_5070_50701301_9_dialog_content = "Princess Dantang, someone just sent word that the Ji Kingdom's enjoy is waiting at the port to escort you back to the palace.",
  ui_story_5070_50701301_10_dialog_content = "I have all the information, so I must report as soon as possible.",
  ui_story_5070_50701301_11_dialog_content = "I see a litany of meetings and banquets in the near future.",
  ui_story_5070_50701301_12_dialog_content = "You'll have to be ready too, PlayerName.",
  ui_story_5070_50701301_13_dialog_content = "Huh? Me?",
  ui_story_5070_50701301_14_dialog_content = "Oh yeah! I totally forgot that I've come to Longzhou as Astra's envoy!",
  ui_story_5070_50701301_15_dialog_content = "W-What do I do? I'm suddenly nervous.",
  ui_story_5070_50701301_16_dialog_content = "Fret not, just treat it as seeing another side of Longzhou.",
  ui_story_5070_50701301_17_dialog_content = "I'm back at last. For a second there, I thought I would be spending my life in Astra...",
  ui_story_5070_50701301_18_dialog_content = "Now that I think about it, I feel like everything has changed even though it's been no longer than half a year since I've been away from Longzhou.",
  ui_story_5070_50701301_19_dialog_content = "That's enough. Now, figure out what we're doing next!",
  ui_story_5070_50701301_20_dialog_content = "Let's get some delicious food? Or a good night's sleep?",
  ui_story_5070_50701301_21_dialog_content = "Return to the Lin Guild.",
  ui_story_5070_50701301_22_dialog_content = "With the help of Princess Dantang and the others, it can be proved that the Lin Guild was unjustly sentenced for the smuggling charge.",
  ui_story_5070_50701301_23_dialog_content = "After everything that's happened, there must be many matters that need urgent treatment.",
  ui_story_5070_50701301_24_dialog_content = "The guildmaster... The guildmaster must still be waiting for me!",
  ui_story_5070_50701301_25_dialog_content = "Hey! Wait up!",
  ui_story_5070_50701301_26_dialog_content = "Don't worry.",
  ui_story_5070_50701301_27_dialog_content = "I've reported everything the moment we landed and sent servants to take the evidence and money to the Maritime Trade Offices...",
  ui_story_5070_50701301_28_dialog_content = "The guildmaster should already be released. Now's the time for your reunion.",
  ui_story_5070_50701301_29_dialog_content = "Look over there.",
  ui_story_5070_50701301_30_dialog_content = "... It's all Xuan Ji's fault. She made Zhong Xu's wheelchair too fast.",
  ui_story_5070_50701301_31_dialog_content = "Brother Zhong!",
  ui_story_5070_50701301_32_dialog_content = "Lin?",
  ui_story_5070_50701301_33_dialog_content = "I never expected that you would still come outside to greet me now that I've lost my legs.",
  ui_story_5070_50701301_34_dialog_content = "Your words... I don't know how to respond to that...",
  ui_story_5070_50701301_35_dialog_content = "I don't even know if I should express gratitude first or apologize to you.",
  ui_story_5070_50701301_36_dialog_content = "There's no need for such words between us.",
  ui_story_5070_50701301_37_dialog_content = "If you really want to do something, welcome Liqing and Captain Yuebai first.",
  ui_story_5070_50701301_38_dialog_content = "I... It's enough for me to see that you're well!",
  ui_story_5070_50701301_39_dialog_content = "Oh, Jiu, please send a letter for me.",
  ui_story_5070_50701301_40_dialog_content = "I must inform my family of the completed mission and my safe return.",
  ui_story_5070_50701301_41_dialog_content = "Yes. Everyone will be happy for you, Your Highness.",
  ui_story_5070_50701301_42_dialog_content = "Anything wrong, PlayerName?",
  ui_story_5070_50701301_43_dialog_content = "Many people disembarked: Dantang, Jiu, Zhong Xu, Liqing, Xuan Ji, and me...",
  ui_story_5070_50701301_44_dialog_content = "But why do I always feel like I'm forgetting something?",
  ui_story_5070_50701301_45_dialog_content = "Eh, forget it. Probably not important. Let's go!",
  ui_story_5070_50701301_46_dialog_content = "Lady Xuan Ji, is it okay to unload these wooden oxen here?",
  ui_story_5070_50701301_47_dialog_content = "Sure, thanks.",
  ui_story_5070_50701301_48_dialog_content = "No big deal. We owe our safe return to you, Lady Xuan Ji, and we've learned quite a bit on the way.",
  ui_story_5070_50701301_49_dialog_content = "It'd be awesome if we could sail together again next time.",
  ui_story_5070_50701301_50_dialog_content = "Yes, hope we'll meet again.",
  ui_story_5070_50701301_X50_dialog_content = "Hmm? It's...",
  ui_story_5070_50701301_X51_dialog_content = "I've been away for so long that I've almost forgotten how every day feels like spring along the southern coast of the Ji Kingdom.",
  ui_story_5070_50701301_X52_dialog_content = "I never thought I'd really be able to return to Longzhou with the thing I was seeking...",
  ui_story_5070_50701301_51_dialog_content = "...",
  ui_story_5070_50701301_52_dialog_content = "Okay, you've seen a lot already.",
  ui_story_5070_50701301_53_dialog_content = "So don't you have more important things to do now?",
  ui_story_5070_50701301_54_dialog_content = "Wait, what's in this wooden ox...?",
  ui_story_5070_50701301_55_dialog_content = "Urgh!",
  ui_story_5070_50701301_56_dialog_content = "It's bright outside? Morning.",
  ui_story_5070_50701301_57_dialog_content = "What are you doing hiding in there?",
  ui_story_5070_50701301_58_dialog_content = "It's because... Ugh, would you give me a hand and pull me out first? Thanks.",
  ui_story_5070_50701301_59_dialog_content = "Owie... I'm so sore from hiding in there.",
  ui_story_5070_50701301_60_dialog_content = "Who knew that we wouldn't just encounter storms and Eclipsites during this journey, we were even attacked by pirates.",
  ui_story_5070_50701301_61_dialog_content = "Luckily, I divined our fortune before setting sail.",
  ui_story_5070_50701301_62_dialog_content = "It took me days of research to figure out the Yin Horse and Yin Ox divination. It probably corresponds to your wooden ox.",
  ui_story_5070_50701301_63_dialog_content = "That's how I found such a perfect place to hide. Otherwise, this journey full of disaster would have taken my life.",
  ui_story_5070_50701301_64_dialog_content = "Urgh...",
  ui_story_5070_50701301_65_dialog_content = "That reminds me, I owe you for using this spot.",
  ui_story_5070_50701301_66_dialog_content = "How about a free divination?",
  ui_story_5070_50701301_67_dialog_content = "It's alright.",
  ui_story_5070_50701301_68_dialog_content = "We artisans put way more stock in our creations than in fate.",
  ui_story_5070_50701301_69_dialog_content = "Even if you foretell something awful, that doesn't mean I shouldn't do what needs to be done!",
  ui_story_5070_50701301_70_dialog_content = "Fine. Good luck to you then.",
  ui_story_5070_50701301_71_dialog_content = "Farewell.",
  ui_story_5070_50701301_72_dialog_content = "(Let's see... While I was in the wooden ox earlier, I drew...)",
  ui_story_5070_50701301_73_dialog_content = "(Yang Tiger and Yin Dragon? Interesting.)",
  ui_story_5070_50701301_74_dialog_content = "(It was a dead ox and silent horse on the ship, so I remained hidden and barely managed to escape danger.)",
  ui_story_5070_50701301_X74_dialog_content = "(Yet now, it's a sign of danger.)",
  ui_story_5070_50701301_75_dialog_content = "(Xuan Ji's always telling everyone to stay away from danger, but she's walking into the tiger's den?)",
  ui_story_5070_50701301_76_dialog_content = "Send a letter.",
  ui_story_5070_50701301_77_dialog_content = "Good to see you again. Two letters, both to be sent to Ye Kingdom, right?",
  ui_story_5070_50701301_78_dialog_content = "Rest assured. They'll be delivered on time.",
  ui_story_5070_50701301_79_dialog_content = "<color=#e8d9bb>Not far from the Post</color>",
  ui_story_5070_50701301_80_dialog_content = "Go report to our lord; Frost Blade has safely escorted the princess back to Longzhou.",
  ui_story_5070_50701301_81_dialog_content = "Take care of the folks at the post; don't leave any loose ends for our lord."
}
return config
